    PLA
    STA.w !Eng_PtrBase,X
    INX
    STX.w !DP_Field+!Oam_Range1HiPtr
    LDX.w !DP_Field+!Oam_Range1LoPtr
    STX.b WMADDL-!DP_PPU
    LDX.w !DP_Field+!Obj_Cur
