    CLC
    ADC.w #!Spr_Size2Tiles*!Oam_EntrySize
    STA.w !DP_Field+!Oam_Range1LoPtr
.t2_entries:                ; shared low-table copy (size 2)
    LDA.w !Obj_TileRecOfs,X
