    LDA.l !Obj_OamHiA,X
    LDX.w !DP_Field+!Oam_Range3HiPtr
    STA.w !Eng_PtrBase,X
    INX
    PLA
    STA.w !Eng_PtrBase,X
    INX
    PLA
    STA.w !Eng_PtrBase,X
    INX
