    CMP.b #!Oam_HiddenY
    BCS .pos_store7
    LDA.b #!Oam_HiddenY
.pos_store7:
    STA.w SprTile[7].Y,X
    SEP #$20
    PLB
    RTS

    ; Spr_BaseYHi != 0: keep a Y only if the add carries and lands on
    ; $E0-$FF, else Oam_HiddenY
.y_hi_set:
    LDA.w SprTile.OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BCC .hi_clamp0
    CMP.b #!Oam_HiddenY
    BCS .hi_store0
.hi_clamp0:
    LDA.b #!Oam_HiddenY
.hi_store0:
    STA.w SprTile.Y,X

    LDA.w SprTile[1].OfsY,X
