; ============================================================
; $C0:BCDC — Spr_Load8 (790 bytes, $BCDC–$BFF1)
; (was Sub_BCDC.) Builds an 8-tile (size 1) object's SprTile records
; from SprTileSrc and places them: OfsX, OfsY and Tile/Attr are copied
; from SprTileSrc, then X, the two high-table bytes and Y are set. Y
; clamps: Spr_BaseYHi != 0 keeps only a carried result of $E0-$FF;
; Spr_BaseY bit 7 set turns $E0-$FF into Oam_HiddenY; bit 7 clear turns
; $80-$DF into Oam_HiddenY for every record.
; Called from Spr_PrepareTiles.
; Callers (1 JSR site): Spr_PrepareTiles ($C0:B744).
; On entry: M=1, X/Y 16-bit, DP=$0100 (Spr_* scratch); loads X =
; Obj_Cur itself.
; Exit: M=1, X/Y 16-bit, DB restored (PLB).
; ============================================================
org $C0BCDC
Spr_Load8:
    PHB
    LDA.b #!Bank7F
    PHA
    PLB
    REP #$20
    LDX.b !Obj_Cur
    LDA.l !Obj_ScreenY,X
    AND.w #!Spr_YMask9
    STA.b !Spr_BaseY
    LDA.l !Obj_ScreenX,X
    STA.b !Spr_BaseX
    STZ.b !Spr_HiBits
    LDA.l !Obj_TileRecOfs,X
    STA.b !Spr_FirstRec
    CLC
    ADC.w #!SprTile_Stride*3

    ; Records 3..0: copy OfsX, set X, high-table bits → Obj_OamHiA
.x1_loop:
    TAX
    LDA.w SprTileSrc.OfsX,X
    STA.w SprTile.OfsX,X
    CLC
    ADC.b !Spr_BaseX
    SEP #$20
    STA.w SprTile.X,X
    XBA
    AND #$01
    STA.b !Spr_HiBitTmp
    LDA.b !Spr_HiBits
    ASL A
    ASL A
    ORA.b !Spr_HiBitTmp
    CPX.b !Spr_FirstRec
    BEQ .x1_done
    STA.b !Spr_HiBits
    REP #$20
    TXA
    SEC
    SBC.w #!SprTile_Stride
    BRA .x1_loop
.x1_done:
    ORA.b #!Oam_HiLarge4
    LDX.b !Obj_Cur
    STA.w !Obj_OamHiA,X
    STZ.b !Spr_HiBits
    REP #$20
    LDA.b !Spr_FirstRec
    CLC
    ADC.w #!SprTile_Stride*4
    STA.b !Spr_GroupRec
    CLC
    ADC.w #!SprTile_Stride*3

    ; Records 7..4, high-table bits → Obj_OamHiA+1
.x2_loop:
    TAX
    LDA.w SprTileSrc.OfsX,X
    STA.w SprTile.OfsX,X
    CLC
    ADC.b !Spr_BaseX
    SEP #$20
    STA.w SprTile.X,X
    XBA
    AND #$01
    STA.b !Spr_HiBitTmp
    LDA.b !Spr_HiBits
    ASL A
    ASL A
    ORA.b !Spr_HiBitTmp
    CPX.b !Spr_GroupRec
    BEQ .x2_done
    STA.b !Spr_HiBits
    REP #$20
    TXA
    SEC
    SBC.w #!SprTile_Stride
    BRA .x2_loop
.x2_done:
    ORA.b #!Oam_HiLarge4
    LDX.b !Obj_Cur
    STA.w !Obj_OamHiA+1,X
    LDX.b !Spr_FirstRec
    LDA.b !Spr_BaseYHi
    BEQ .y_hi_clear
    BRL .y_hi_set

.y_hi_clear:
    LDA.b !Spr_BaseY
    BMI .y_neg
    BRL .y_pos              ; Spr_BaseY bit 7 clear

    ; Spr_BaseY bit 7 set: copy OfsY; a Y of $E0-$FF becomes Oam_HiddenY
.y_neg:
    LDA.w SprTileSrc.OfsY,X
    STA.w SprTile.OfsY,X
    CLC
    ADC.b !Spr_BaseY
    CMP.b #!Oam_HiddenY
    BCC .neg_store0
    LDA.b #!Oam_HiddenY
.neg_store0:
    STA.w SprTile.Y,X
    LDA.w SprTileSrc[1].OfsY,X
    STA.w SprTile[1].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    CMP.b #!Oam_HiddenY
    BCC .neg_store1
    LDA.b #!Oam_HiddenY
.neg_store1:
    STA.w SprTile[1].Y,X
    LDA.w SprTileSrc[2].OfsY,X
    STA.w SprTile[2].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    CMP.b #!Oam_HiddenY
    BCC .neg_store2
    LDA.b #!Oam_HiddenY
.neg_store2:
    STA.w SprTile[2].Y,X
    LDA.w SprTileSrc[3].OfsY,X
    STA.w SprTile[3].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    CMP.b #!Oam_HiddenY
    BCC .neg_store3
    LDA.b #!Oam_HiddenY
.neg_store3:
    STA.w SprTile[3].Y,X
    LDA.w SprTileSrc[4].OfsY,X
    STA.w SprTile[4].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    CMP.b #!Oam_HiddenY
    BCC .neg_store4
    LDA.b #!Oam_HiddenY
.neg_store4:
    STA.w SprTile[4].Y,X
    LDA.w SprTileSrc[5].OfsY,X
    STA.w SprTile[5].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    CMP.b #!Oam_HiddenY
    BCC .neg_store5
    LDA.b #!Oam_HiddenY
.neg_store5:
    STA.w SprTile[5].Y,X
    LDA.w SprTileSrc[6].OfsY,X
    STA.w SprTile[6].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    CMP.b #!Oam_HiddenY
    BCC .neg_store6
    LDA.b #!Oam_HiddenY
.neg_store6:
    STA.w SprTile[6].Y,X
    LDA.w SprTileSrc[7].OfsY,X
    STA.w SprTile[7].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    CMP.b #!Oam_HiddenY
    BCC .neg_store7
    LDA.b #!Oam_HiddenY
.neg_store7:
    STA.w SprTile[7].Y,X
    REP #$20
    LDA.w SprTileSrc.Tile,X
    STA.w SprTile.Tile,X
    LDA.w SprTileSrc[1].Tile,X
    STA.w SprTile[1].Tile,X
    LDA.w SprTileSrc[2].Tile,X
    STA.w SprTile[2].Tile,X
    LDA.w SprTileSrc[3].Tile,X
    STA.w SprTile[3].Tile,X
    LDA.w SprTileSrc[4].Tile,X
    STA.w SprTile[4].Tile,X
    LDA.w SprTileSrc[5].Tile,X
    STA.w SprTile[5].Tile,X
    LDA.w SprTileSrc[6].Tile,X
    STA.w SprTile[6].Tile,X
    LDA.w SprTileSrc[7].Tile,X
    STA.w SprTile[7].Tile,X
    SEP #$20
    PLB
    RTS

    ; Spr_BaseY bit 7 clear: copy OfsY; $80-$DF becomes Oam_HiddenY
.y_pos:
    LDA.w SprTileSrc.OfsY,X
    STA.w SprTile.OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BPL .pos_store0
    CMP.b #!Oam_HiddenY
    BCS .pos_store0
    LDA.b #!Oam_HiddenY
.pos_store0:
    STA.w SprTile.Y,X
    LDA.w SprTileSrc[1].OfsY,X
    STA.w SprTile[1].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BPL .pos_store1
    CMP.b #!Oam_HiddenY
    BCS .pos_store1
    LDA.b #!Oam_HiddenY
.pos_store1:
    STA.w SprTile[1].Y,X
    LDA.w SprTileSrc[2].OfsY,X
    STA.w SprTile[2].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BPL .pos_store2
    CMP.b #!Oam_HiddenY
    BCS .pos_store2
    LDA.b #!Oam_HiddenY
.pos_store2:
    STA.w SprTile[2].Y,X
    LDA.w SprTileSrc[3].OfsY,X
    STA.w SprTile[3].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BPL .pos_store3
    CMP.b #!Oam_HiddenY
    BCS .pos_store3
    LDA.b #!Oam_HiddenY
.pos_store3:
    STA.w SprTile[3].Y,X
    LDA.w SprTileSrc[4].OfsY,X
    STA.w SprTile[4].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BPL .pos_store4
    CMP.b #!Oam_HiddenY
    BCS .pos_store4
    LDA.b #!Oam_HiddenY
.pos_store4:
    STA.w SprTile[4].Y,X
    LDA.w SprTileSrc[5].OfsY,X
    STA.w SprTile[5].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BPL .pos_store5
    CMP.b #!Oam_HiddenY
    BCS .pos_store5
    LDA.b #!Oam_HiddenY
.pos_store5:
    STA.w SprTile[5].Y,X
    LDA.w SprTileSrc[6].OfsY,X
    STA.w SprTile[6].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BPL .pos_store6
    CMP.b #!Oam_HiddenY
    BCS .pos_store6
    LDA.b #!Oam_HiddenY
.pos_store6:
    STA.w SprTile[6].Y,X
    LDA.w SprTileSrc[7].OfsY,X
    STA.w SprTile[7].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BPL .pos_store7
    CMP.b #!Oam_HiddenY
    BCS .pos_store7
    LDA.b #!Oam_HiddenY
.pos_store7:
    STA.w SprTile[7].Y,X
    REP #$20
    LDA.w SprTileSrc.Tile,X
    STA.w SprTile.Tile,X
    LDA.w SprTileSrc[1].Tile,X
    STA.w SprTile[1].Tile,X
    LDA.w SprTileSrc[2].Tile,X
    STA.w SprTile[2].Tile,X
    LDA.w SprTileSrc[3].Tile,X
    STA.w SprTile[3].Tile,X
    LDA.w SprTileSrc[4].Tile,X
    STA.w SprTile[4].Tile,X
    LDA.w SprTileSrc[5].Tile,X
    STA.w SprTile[5].Tile,X
    LDA.w SprTileSrc[6].Tile,X
    STA.w SprTile[6].Tile,X
    LDA.w SprTileSrc[7].Tile,X
    STA.w SprTile[7].Tile,X
    SEP #$20
    PLB
    RTS

    ; Spr_BaseYHi != 0: copy OfsY; keep a Y only if the add carries and
    ; lands on $E0-$FF, else Oam_HiddenY
.y_hi_set:
    LDA.w SprTileSrc.OfsY,X
    STA.w SprTile.OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BCC .hi_clamp0
    CMP.b #!Oam_HiddenY
    BCS .hi_store0
.hi_clamp0:
    LDA.b #!Oam_HiddenY
.hi_store0:
    STA.w SprTile.Y,X
    LDA.w SprTileSrc[1].OfsY,X
    STA.w SprTile[1].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BCC .hi_clamp1
    CMP.b #!Oam_HiddenY
    BCS .hi_store1
.hi_clamp1:
    LDA.b #!Oam_HiddenY
.hi_store1:
    STA.w SprTile[1].Y,X
    LDA.w SprTileSrc[2].OfsY,X
    STA.w SprTile[2].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BCC .hi_clamp2
    CMP.b #!Oam_HiddenY
    BCS .hi_store2
.hi_clamp2:
    LDA.b #!Oam_HiddenY
.hi_store2:
    STA.w SprTile[2].Y,X
    LDA.w SprTileSrc[3].OfsY,X
    STA.w SprTile[3].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BCC .hi_clamp3
    CMP.b #!Oam_HiddenY
    BCS .hi_store3
.hi_clamp3:
    LDA.b #!Oam_HiddenY
.hi_store3:
    STA.w SprTile[3].Y,X
