    ADC.b !Spr_BaseY
    BCC .hi_clamp4
    CMP.b #!Oam_HiddenY
    BCS .hi_store4
.hi_clamp4:
    LDA.b #!Oam_HiddenY
.hi_store4:
    STA.w SprTile[4].Y,X
    LDA.w SprTileSrc[5].OfsY,X
    STA.w SprTile[5].OfsY,X
    CLC
    ADC.b !Spr_BaseY
    BCC .hi_clamp5
    CMP.b #!Oam_HiddenY
