; ============================================================
; $C0:BFF2 — Spr_Place12 (717 bytes, $BFF2–$C2BE)
; (was Sub_BFF2.) Re-places a 12-tile (size 2) object from its
; existing SprTile records: three groups of 4 records give X and the
; high-table bytes (Obj_OamHiA, Obj_OamHiA+1, Obj_OamHiB), then the 12
; Y positions by Spr_BaseYHi / Spr_BaseY bit 7:
;   Spr_BaseYHi != 0      keep only $00-$7F without a carry, else
;                         Oam_HiddenY;
;   bit 7 set ("negative") plain add, no clamp;
;   bit 7 clear           $80-$DF → Oam_HiddenY.
; Called from Spr_PrepareTiles.
; Callers (1 JSR site): Spr_PrepareTiles ($C0:B780).
; On entry: M=1, X/Y 16-bit, DP=$0100 (Spr_* scratch); loads X =
; Obj_Cur itself.
; Exit: M=1, X/Y 16-bit, DB restored (PLB).
; ============================================================
org $C0BFF2
Spr_Place12:
    PHB
    LDA.b #!Bank7F
    PHA
    PLB
    REP #$20
    LDX.b !Obj_Cur
    LDA.l !Obj_ScreenY,X
    AND.w #!Spr_YMask9
    STA.b !Spr_BaseY
    LDA.l !Obj_ScreenX,X
    STA.b !Spr_BaseX
    STZ.b !Spr_HiBits
    LDA.l !Obj_TileRecOfs,X
    STA.b !Spr_FirstRec
    CLC
    ADC.w #!SprTile_Stride*3

    ; X of records 3..0, high-table bits → Obj_OamHiA
.x1_loop:
    TAX
    LDA.w SprTile.OfsX,X
    CLC
    ADC.b !Spr_BaseX
    SEP #$20
    STA.w SprTile.X,X
    XBA
    AND #$01
    STA.b !Spr_HiBitTmp
    LDA.b !Spr_HiBits
    ASL A
    ASL A
    ORA.b !Spr_HiBitTmp
    CPX.b !Spr_FirstRec
    BEQ .x1_done
    STA.b !Spr_HiBits
    REP #$20
    TXA
    SEC
    SBC.w #!SprTile_Stride
    BRA .x1_loop
.x1_done:
    ORA.b #!Oam_HiLarge4
    LDX.b !Obj_Cur
    STA.w !Obj_OamHiA,X
    STZ.b !Spr_HiBits
    REP #$20
    LDA.b !Spr_FirstRec
    CLC
    ADC.w #!SprTile_Stride*4
    STA.b !Spr_GroupRec
    CLC
    ADC.w #!SprTile_Stride*3

    ; X of records 7..4, high-table bits → Obj_OamHiA+1
.x2_loop:
    TAX
    LDA.w SprTile.OfsX,X
    CLC
    ADC.b !Spr_BaseX
    SEP #$20
    STA.w SprTile.X,X
    XBA
    AND #$01
    STA.b !Spr_HiBitTmp
    LDA.b !Spr_HiBits
    ASL A
    ASL A
    ORA.b !Spr_HiBitTmp
    CPX.b !Spr_GroupRec
    BEQ .x2_done
    STA.b !Spr_HiBits
    REP #$20
    TXA
    SEC
    SBC.w #!SprTile_Stride
    BRA .x2_loop
.x2_done:
    ORA.b #!Oam_HiLarge4
    LDX.b !Obj_Cur
    STA.w !Obj_OamHiA+1,X
    STZ.b !Spr_HiBits
    REP #$20
    LDA.b !Spr_FirstRec
    CLC
    ADC.w #!SprTile_Stride*8
    STA.b !Spr_GroupRec
    CLC
    ADC.w #!SprTile_Stride*3

    ; X of records 11..8, high-table bits → Obj_OamHiB
.x3_loop:
    TAX
    LDA.w SprTile.OfsX,X
    CLC
    ADC.b !Spr_BaseX
