    ORA.b !Spr_HiBitTmp
    CPX.b !Spr_GroupRec
    BEQ .x3_done
    STA.b !Spr_HiBits
    REP #$20
    TXA
    SEC
    SBC.w #!SprTile_Stride
    BRA .x3_loop
