    LDX.b !Obj_Cur
    STA.w !Obj_OamHiB,X
    LDX.b !Spr_FirstRec
    LDA.b !Spr_BaseYHi
    BEQ .y_hi_clear
    BRL .y_hi_set               ; Spr_BaseYHi != 0

