    INX
    LDA.l !Evt_Data,X
    STA.b !Field_Unk2B
    INX
    LDA.l !Evt_Data,X
    STA.b !Field_Unk2B+1
    INX
    LDA.l !Evt_Data,X
    STA.b !Field_Unk2D
    INX
    SEC
    RTS

