    BNE .busy
    LDX.b !Obj_Cur
    LDA.l !ObjX_LeaveView,X
    BNE .over
    LDA.b #$01
    STA.l !ObjX_LeaveView,X
    TYX
    INX
    LDA.l !Evt_Data,X                   ; msg
    STA.b !Field_Unk2A
    LDA.b !Obj_Cur
    STA.b !Field_Unk2E
    STZ.b !Field_Unk32
    LDA.b #!Field_Unk29Start
    STA.b !Field_Unk29
    STZ.b !Field_Unk30
    LDA.b #!Field54_WatchBox
    TRB.b !Field_Unk54
    TYX
    CLC
    RTS
.over:
    LDA.b #$00
    STA.l !ObjX_LeaveView,X
    TYX
    INX
    INX
    SEC
    RTS
.busy:
    TYX
    CLC
    RTS

