; ------------------------------------------------------------
; $C0:420C — Evt_Op6C_InitChar5 (8 bytes, $420C–$4213)
; Event opcode $6C (1 byte): as Evt_Op57_InitChar0 for character 5.
; Reached through Evt_OpcodeTable (opcode $6C).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100, DB=$00; Y = the
;   opcode's offset in Evt_Data.
; Exit: as Evt_InitCharCommon (X = Y + 1, C=1).
; ------------------------------------------------------------
Evt_Op6C_InitChar5:
    LDA.b !Obj_Cur
    STA.b !Chr_ObjSlot+5
    LDA.b #$05
    BRA Evt_InitCharTail

; ------------------------------------------------------------
; $C0:4214 — Evt_Op6D_InitChar6 (10 bytes, $4214–$421D; the store from
;   $421A on is the sub-entry Evt_InitCharTail)
; Event opcode $6D (1 byte): as Evt_Op57_InitChar0 for character 6, then
;   falls into Evt_InitCharTail, which stores A (the character) in
;   EvtChar_Id and BRAs to Evt_InitCharCommon; the other one-byte
;   character opcodes BRA to it.
; Reached through Evt_OpcodeTable (opcode $6D).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100, DB=$00; Y = the
;   opcode's offset in Evt_Data. Evt_InitCharTail: A = the character.
; Exit: as Evt_InitCharCommon (X = Y + 1, C=1).
; ------------------------------------------------------------
Evt_Op6D_InitChar6:
    LDA.b !Obj_Cur
    STA.b !Chr_ObjSlot+6
    LDA.b #$06
Evt_InitCharTail:                       ; header: see Evt_Op6D_InitChar6
    STA.b !EvtChar_Id
    BRA Evt_InitCharCommon

; ------------------------------------------------------------
; $C0:421E — Evt_Op80_InitCharObj (600 bytes, $421E–$4475; from $426A on
;   the sub-entry Evt_InitCharCommon)
; Event opcode $80 (2 bytes: $80, char): Chr_ObjSlot[char] = Obj_Cur
;   (char 0-6; a larger one stores nothing), then Evt_InitCharCommon,
;   which the one-byte character opcodes reach too (EvtChar_Id = the
;   character, Y = the offset of the opcode's last byte):
;   - not in Party_Members: Obj_Unk1100 = Obj_Unk1100Skip (its script is
;     never queued), Obj_Unk1101 = char; X = Y + 1, C=1. No sprite.
;   - party member k (0, 1, 2: the first of Party_Members, +1, +2 equal
;     to char): Obj_Unk1100 = k, Obj_Unk1C80 = 0, Obj_Unk1A81 =
;     Obj_Unk1A81On, Obj_Unk1B01 = Obj_Unk1B01Solid, Obj_Unk1101 = char,
;     Party_ObjSlot / 1 / 2 (word) = Obj_Cur, Evt_LoadSpriteRec with
;     record char; then Obj_TileSlot[1 + k] = Obj_Cur, Obj_VramTile =
;     EvtChar_VramTile0/1/2, Obj_TileRecOfs = 0 / $20 / $40, Obj_Unk1000
;     = its bit 7 | 1 (a script run every frame). Member 2 / 3 also: when
;     ObjQ_Unk78 is nonzero it becomes ObjQ_Unk78Head and Obj_AnimTimer =
;     0; Field_UnkAB/AC/AD = 0 (the step log reset, probably).
;     Placement: a member 2 / 3 with a leader present takes the leader's
;     Obj_PosX/Y and Obj_Facing (Obj_VelX = 0); the leader, or a member
;     with none, goes to Loc_EntryX/Y with Obj_Facing = Loc_EntryFacing
;     bits 0-1, the low byte of Obj_PosY $FF (bit 3 clear) or $7F (set)
;     and that of Obj_PosX $80 (bit 2 clear) or $00 (set): where in the
;     entry tile it stands. X = Y (after the record load's INY), C=1.
; Quirk: Obj_TileSlot is written with a 16-bit STX, so the slot after
;   1 + k gets Obj_CurHi (0) too; the next member's store overwrites it.
; Reached through Evt_OpcodeTable (opcode $80); Evt_InitCharCommon by
;   BRA from Evt_InitCharTail.
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur,
;   Chr_ObjSlot, Party_ObjSlot*, Loc_Entry*, ObjQ_Unk78, Field_UnkAB-AD
;   and the scratch are dp), DB=$00 (Obj_* tables absolute); Y = the
;   opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = the next opcode (the
;   opcode's offset + 2 for $80, + 1 for the one-byte ones), C=1; Y =
;   X on the member paths, X - 1 on the other; A clobbered; dp $D9:
;   EvtChar_Id = char on the not-in-party path; on the member paths
;   Evt_LoadSpriteRec leaves EvtSpr_Idx (the same dp $D9, 16-bit) = the
;   record's SprRec_Gfx index, with its other writes.
; ------------------------------------------------------------
Evt_Op80_InitCharObj:
    INY
    TYX
    LDA.l !Evt_Data,X
    STA.b !EvtChar_Id
    CMP.b #$00
    BNE .not0
    LDA.b !Obj_Cur
    STA.b !Chr_ObjSlot
    BRA Evt_InitCharCommon
.not0:
    CMP.b #$01
    BNE .not1
    LDA.b !Obj_Cur
    STA.b !Chr_ObjSlot+1
    BRA Evt_InitCharCommon
.not1:
    CMP.b #$02
    BNE .not2
    LDA.b !Obj_Cur
    STA.b !Chr_ObjSlot+2
    BRA Evt_InitCharCommon
.not2:
    CMP.b #$03
    BNE .not3
    LDA.b !Obj_Cur
    STA.b !Chr_ObjSlot+3
    BRA Evt_InitCharCommon
.not3:
    CMP.b #$04
    BNE .not4
    LDA.b !Obj_Cur
    STA.b !Chr_ObjSlot+4
    BRA Evt_InitCharCommon
.not4:
    CMP.b #$05
    BNE .not5
    LDA.b !Obj_Cur
    STA.b !Chr_ObjSlot+5
    BRA Evt_InitCharCommon
.not5:
    CMP.b #$06
    BNE Evt_InitCharCommon
    LDA.b !Obj_Cur
    STA.b !Chr_ObjSlot+6
Evt_InitCharCommon:                     ; header: see Evt_Op80_InitCharObj
    LDA.b !EvtChar_Id
    CMP.l !Party_Members
    BNE .not_leader
    LDA.b #!Obj_Unk1100Leader
    BRA .leader
.not_leader:
    CMP.l !Party_Members+1
    BNE .not_member2
    LDA.b #!Obj_Unk1100Member2
    BRL .member2
.not_member2:
    CMP.l !Party_Members+2
    BNE .not_member
    LDA.b #!Obj_Unk1100Member3
    BRL .member3
.not_member:
    LDA.b #!Obj_Unk1100Skip
    LDX.b !Obj_Cur
    STA.w !Obj_Unk1100,X
    LDA.b !EvtChar_Id
    STA.w !Obj_Unk1101,X
    TYX
    INX
    SEC
    RTS
.leader:
    LDX.b !Obj_Cur
    STA.w !Obj_Unk1100,X
    STZ.w !Obj_Unk1C80,X
    LDA.b #!Obj_Unk1A81On
    STA.w !Obj_Unk1A81,X
    LDA.b #!Obj_Unk1B01Solid
    STA.w !Obj_Unk1B01,X
    LDA.b !EvtChar_Id
    STA.w !Obj_Unk1101,X
    STX.b !Party_ObjSlot
    JSR Evt_LoadSpriteRec
    LDX.b !Obj_Cur
    LDA.b !Loc_EntryX
    STA.w !Obj_TileX,X
    LDA.b !Loc_EntryY
    STA.w !Obj_TileY,X
    STX.w !Obj_TileSlot+1               ; 16-bit: slot 2 = 0 too (quirk)
    REP #$20
    LDA.w #!EvtChar_VramTile0
    STA.w !Obj_VramTile,X
    LDA.w #$0000
    STA.w !Obj_TileRecOfs,X
    SEP #$20
    LDA.w !Obj_Unk1000,X
    AND.b #!Obj_Unk1000Bit7
    ORA.b #!EvtChar_ScriptPeriod
    STA.w !Obj_Unk1000,X
    LDA.b !Loc_EntryFacing
    AND.b #!Obj_FacingMask
    STA.w !Obj_Facing,X
    LDA.b !Loc_EntryFacing
    BIT.b #!Loc_EntrySubYBit
    BNE .leader_y7f
    LDA.b #!EvtChar_SubYLower
    STA.w !Obj_PosY,X
    BRA .leader_x
.leader_y7f:
    LDA.b #!EvtChar_SubYUpper
    STA.w !Obj_PosY,X
.leader_x:
    LDA.b !Loc_EntryFacing
    BIT.b #!Loc_EntrySubXBit
    BNE .leader_x00
    LDA.b #!EvtChar_SubXCentre
    STA.w !Obj_PosX,X
    TYX
    SEC
    RTS
.leader_x00:
    LDA.b #$00
    STA.w !Obj_PosX,X
    TYX
    SEC
    RTS
.member2:
    LDX.b !Obj_Cur
    STA.w !Obj_Unk1100,X
    STZ.w !Obj_Unk1C80,X
    LDA.b #!Obj_Unk1A81On
    STA.w !Obj_Unk1A81,X
    LDA.b #!Obj_Unk1B01Solid
    STA.w !Obj_Unk1B01,X
    LDA.b !EvtChar_Id
    STA.w !Obj_Unk1101,X
    STX.b !Party_ObjSlot1
    JSR Evt_LoadSpriteRec
    LDX.b !Obj_Cur
    LDA.b !ObjQ_Unk78
    BEQ .m2_slot
    LDA.b #!ObjQ_Unk78Head
    STA.b !ObjQ_Unk78
    STZ.w !Obj_AnimTimer,X
.m2_slot:
    STX.w !Obj_TileSlot+2               ; 16-bit: slot 3 = 0 too (quirk)
    REP #$20
    LDA.w #!EvtChar_VramTile1
    STA.w !Obj_VramTile,X
    LDA.w #!EvtChar_TileRecOfs1
    STA.w !Obj_TileRecOfs,X
    SEP #$20
    LDA.w !Obj_Unk1000,X
    AND.b #!Obj_Unk1000Bit7
    ORA.b #!EvtChar_ScriptPeriod
    STA.w !Obj_Unk1000,X
    STZ.b !Field_UnkAB
    STZ.b !Field_UnkAC
    STZ.b !Field_UnkAD
    LDA.b !Party_ObjSlot
    BMI .m2_no_leader
    REP #$20
    AND.w #!Eng_LowByteMask
    TAX
    LDA.w !Obj_PosX,X
    LDX.b !Party_ObjSlot1
    STA.w !Obj_PosX,X
    LDX.b !Party_ObjSlot
    LDA.w !Obj_PosY,X
    LDX.b !Party_ObjSlot1
    STA.w !Obj_PosY,X
    STZ.w !Obj_VelX,X
    SEP #$20
    LDX.b !Party_ObjSlot
    LDA.w !Obj_Facing,X
    LDX.b !Party_ObjSlot1
    STA.w !Obj_Facing,X
    TYX
    SEC
    RTS
.m2_no_leader:
    LDA.b !Loc_EntryX
    STA.w !Obj_TileX,X
    LDA.b !Loc_EntryY
    STA.w !Obj_TileY,X
    LDA.b !Loc_EntryFacing
    AND.b #!Obj_FacingMask
    STA.w !Obj_Facing,X
    LDA.b !Loc_EntryFacing
    BIT.b #!Loc_EntrySubYBit
    BNE .m2_y7f
    LDA.b #!EvtChar_SubYLower
    STA.w !Obj_PosY,X
    BRA .m2_x
.m2_y7f:
    LDA.b #!EvtChar_SubYUpper
    STA.w !Obj_PosY,X
.m2_x:
    LDA.b !Loc_EntryFacing
    BIT.b #!Loc_EntrySubXBit
    BNE .m2_x00
    LDA.b #!EvtChar_SubXCentre
    STA.w !Obj_PosX,X
    TYX
    SEC
    RTS
.m2_x00:
    LDA.b #$00
    STA.w !Obj_PosX,X
    TYX
    SEC
    RTS
.member3:
    LDX.b !Obj_Cur
    STA.w !Obj_Unk1100,X
    STZ.w !Obj_Unk1C80,X
    LDA.b #!Obj_Unk1A81On
    STA.w !Obj_Unk1A81,X
    LDA.b #!Obj_Unk1B01Solid
    STA.w !Obj_Unk1B01,X
    LDA.b !EvtChar_Id
    STA.w !Obj_Unk1101,X
    STX.b !Party_ObjSlot2
    JSR Evt_LoadSpriteRec
    LDX.b !Obj_Cur
    LDA.b !ObjQ_Unk78
    BEQ .m3_slot
    LDA.b #!ObjQ_Unk78Head
    STA.b !ObjQ_Unk78
    STZ.w !Obj_AnimTimer,X
.m3_slot:
    STX.w !Obj_TileSlot+3               ; 16-bit: slot 4 = 0 too (quirk)
    REP #$20
    LDA.w #!EvtChar_VramTile2
    STA.w !Obj_VramTile,X
    LDA.w #!EvtChar_TileRecOfs2
    STA.w !Obj_TileRecOfs,X
    SEP #$20
    LDA.w !Obj_Unk1000,X
    AND.b #!Obj_Unk1000Bit7
    ORA.b #!EvtChar_ScriptPeriod
    STA.w !Obj_Unk1000,X
    STZ.b !Field_UnkAB
    STZ.b !Field_UnkAC
    STZ.b !Field_UnkAD
    LDA.b !Party_ObjSlot
    BMI .m3_no_leader
    REP #$20
    AND.w #!Eng_LowByteMask
    TAX
    LDA.w !Obj_PosX,X
    LDX.b !Party_ObjSlot2
    STA.w !Obj_PosX,X
    LDX.b !Party_ObjSlot
    LDA.w !Obj_PosY,X
    LDX.b !Party_ObjSlot2
    STA.w !Obj_PosY,X
    STZ.w !Obj_VelX,X
    SEP #$20
    LDX.b !Party_ObjSlot
    LDA.w !Obj_Facing,X
    LDX.b !Party_ObjSlot2
    STA.w !Obj_Facing,X
    TYX
    SEC
    RTS
.m3_no_leader:
    LDA.b !Loc_EntryX
    STA.w !Obj_TileX,X
    LDA.b !Loc_EntryY
    STA.w !Obj_TileY,X
    LDA.b !Loc_EntryFacing
    AND.b #!Obj_FacingMask
    STA.w !Obj_Facing,X
    LDA.b !Loc_EntryFacing
    BIT.b #!Loc_EntrySubYBit
    BNE .m3_y7f
    LDA.b #!EvtChar_SubYLower
    STA.w !Obj_PosY,X
    BRA .m3_x
.m3_y7f:
    LDA.b #!EvtChar_SubYUpper
    STA.w !Obj_PosY,X
.m3_x:
    LDA.b !Loc_EntryFacing
    BIT.b #!Loc_EntrySubXBit
    BNE .m3_x00
    LDA.b #!EvtChar_SubXCentre
    STA.w !Obj_PosX,X
    TYX
    SEC
    RTS
.m3_x00:
    LDA.b #$00
    STA.w !Obj_PosX,X
    TYX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4476 — Evt_Op81_InitSprite (225 bytes, $4476–$4556; from $448D
;   on the sub-entry Evt_LoadSpriteRec)
; Event opcode $81 (2 bytes: $81, record): Obj_Cur becomes an object
;   with sprite record `record`: Obj_Unk1100 = Obj_Unk1100Kind3,
;   Obj_Unk1B01 = Obj_Unk1B01Solid, Obj_Unk1101 = record, then
;   Evt_LoadSpriteRec. X = Y + 2, C=1.
; Evt_LoadSpriteRec (A = the record number, Y = the offset of the byte
;   before the next opcode; Evt_InitCharCommon JSRs it with a
;   character's number) loads RomE4_SprRec record A into Obj_Cur's
;   Obj_FrameOfs/FrameBank, Obj_PalSrc, Obj_AnimFacingStride /
;   AnimFrameTbl / AnimTimeTbl, Obj_SprSize and Obj_GfxOfs/GfxBank (see
;   the banner), sets Obj_PrioLow/High = EvtSpr_PrioInit (OAM priority
;   bit 1 in both), Obj_AnimRow = Obj_AnimColumn = 0 and Obj_Facing =
;   Obj_FacingDown; Y + 1 is kept in EvtOp_SavedPos and returned in X
;   and Y, with C=1.
; Quirk: the ADC of Obj_PalSrcBase ($0000) to the palette offset adds
;   nothing.
; Reached through Evt_OpcodeTable (opcode $81).
; Callers of Evt_LoadSpriteRec (3 JSR sites): Evt_InitCharCommon ($C0:42B5, $C0:4329, $C0:43DC).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur, the
;   Field_E4Ptr* pointers and the scratch are dp), DB=$00 (Obj_* tables
;   and the multiplier absolute); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = Y = EvtOp_SavedPos = the
;   opcode + 2 (Evt_LoadSpriteRec: the entry Y + 1), C=1; A clobbered;
;   EvtSpr_RecOfs and EvtSpr_Idx written.
; ------------------------------------------------------------
Evt_Op81_InitSprite:
    LDA.b #!Obj_Unk1100Kind3
    LDX.b !Obj_Cur
    STA.w !Obj_Unk1100,X
    LDA.b #!Obj_Unk1B01Solid
    STA.w !Obj_Unk1B01,X
    INY
    TYX
    LDA.l !Evt_Data,X
    LDX.b !Obj_Cur
    STA.w !Obj_Unk1101,X
Evt_LoadSpriteRec:                      ; header: see Evt_Op81_InitSprite
    STA.w WRMPYA
    INY
    LDA.b #!SprRec_Bytes
    STA.w WRMPYB
    STY.b !EvtOp_SavedPos
    NOP                                 ; wait for the product
    NOP
    NOP
    LDX.w RDMPYL
    STX.b !EvtSpr_RecOfs
    LDA.l !RomE4_SprRec+!SprRec_Frames,X
    REP #$20
    AND.w #!Eng_LowByteMask
    STA.b !EvtSpr_Idx
    CLC
    ADC.b !EvtSpr_Idx
    ADC.b !EvtSpr_Idx                   ; x 3: a 24-bit pointer
    TAY
    LDA.b [!Field_E4Ptr1],Y
    LDX.b !Obj_Cur
    STA.w !Obj_FrameOfs,X
    SEP #$20
    INY
    INY
    LDA.b [!Field_E4Ptr1],Y
    STA.w !Obj_FrameBank,X
    LDX.b !EvtSpr_RecOfs
    LDA.l !RomE4_SprRec+!SprRec_Pal,X
    STA.w WRMPYA
    LDA.b #!Pal_ObjColorBytes
    STA.w WRMPYB
    NOP                                 ; wait for the product
    NOP
    NOP
    REP #$20
    LDA.w RDMPYL
    CLC
    ADC.w #!Obj_PalSrcBase              ; adds 0 (quirk)
    LDX.b !Obj_Cur
    STA.w !Obj_PalSrc,X
    SEP #$20
    LDX.b !EvtSpr_RecOfs
    LDA.l !RomE4_SprRec+!SprRec_Anim,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAY
    INY
    INY
    LDA.b [!Field_E4Ptr2],Y             ; the next entry
    SEC
    DEY
    DEY
    SBC.b [!Field_E4Ptr2],Y
    LSR A
    LSR A
    LDX.b !Obj_Cur
    STA.w !Obj_AnimFacingStride,X
    LDA.b [!Field_E4Ptr2],Y
    STA.w !Obj_AnimFrameTbl,X
    LDA.b [!Field_E4Ptr3],Y
    STA.w !Obj_AnimTimeTbl,X
    SEP #$20
    LDX.b !EvtSpr_RecOfs
    LDA.l !RomE4_SprRec+!SprRec_Size,X
    LDX.b !Obj_Cur
    STA.w !Obj_SprSize,X
    LDX.b !EvtSpr_RecOfs
    LDA.l !RomE4_SprRec+!SprRec_Gfx,X
    REP #$20
    AND.w #!Eng_LowByteMask
    STA.b !EvtSpr_Idx
    CLC
    ADC.b !EvtSpr_Idx
    ADC.b !EvtSpr_Idx                   ; x 3: a 24-bit pointer
    TAY
    LDA.b [!Field_E4Ptr0],Y
    LDX.b !Obj_Cur
    STA.w !Obj_GfxOfs,X
    SEP #$20
    INY
    INY
    LDA.b [!Field_E4Ptr0],Y
    STA.w !Obj_GfxBank,X
    REP #$20
    LDA.w #!EvtSpr_PrioInit
    STA.w !Obj_PrioLow,X                ; and Obj_PrioHigh
    SEP #$20
    LDA.b #!ObjAnim_RowStand
    STA.w !Obj_AnimRow,X
    LDA.b #$00
    STA.w !Obj_AnimColumn,X
    LDA.b #!Obj_FacingDown
    STA.w !Obj_Facing,X
    LDY.b !EvtOp_SavedPos
    TYX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4557 — Evt_InitWramSprite (57 bytes, $4557–$458F)
; The common start of Evt_Op82_InitWramSprite and Evt_Op83_InitEnemySprite
;   (A = the Obj_Unk1100 kind, 4 or 5): Obj_Unk1100 =
;   A, Obj_Unk1101 = the operand after the opcode (also left in WRMPYA
;   for the caller's record product), Obj_GfxOfs = ObjQ_Unk71 with
;   Obj_GfxBank = $7F (the graphics go to WRAM there, unpacked by the
;   caller), Obj_PrioLow/High = EvtSpr_PrioInit, Obj_Facing =
;   Obj_FacingDown, Obj_AnimRow = Obj_AnimColumn = 0. Returns Y = the
;   opcode's offset + 2, C=0.
; Callers (2 JSR sites): Evt_Op82_InitWramSprite ($C0:4592) and Evt_Op83_InitEnemySprite ($C0:46E1).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur and
;   ObjQ_Unk71 are dp), DB=$00 (Obj_* tables and the multiplier
;   absolute); Y = the opcode's offset in Evt_Data; A = the kind.
; Exit: M=1, X=0, DP and DB unchanged; Y = the opcode + 2, C=0; X =
;   Obj_Cur; A = 0.
; ------------------------------------------------------------
Evt_InitWramSprite:
    LDX.b !Obj_Cur
    STA.w !Obj_Unk1100,X
    INY
    TYX
    LDA.l !Evt_Data,X
    LDX.b !Obj_Cur
    STA.w !Obj_Unk1101,X
    STA.w WRMPYA
    REP #$20
    LDA.b !ObjQ_Unk71
    STA.w !Obj_GfxOfs,X
    LDA.w #!EvtSpr_PrioInit
    STA.w !Obj_PrioLow,X
    SEP #$20
    LDA.b #!Bank7F
    STA.w !Obj_GfxBank,X
    LDA.b #!Obj_FacingDown
    STA.w !Obj_Facing,X
    LDA.b #!ObjAnim_RowStand
    STA.w !Obj_AnimRow,X
    LDA.b #$00
    STA.w !Obj_AnimColumn,X
    INY
    CLC
    RTS

; ------------------------------------------------------------
; $C0:4590 — Evt_Op82_InitWramSprite (335 bytes, $4590–$46DE)
; Event opcode $82 (2 bytes: $82, n): Evt_InitWramSprite with kind 4
;   (Obj_Unk1100Kind4), then Obj_Unk1B01 = Obj_Unk1B01Solid and sprite
;   record SprRec_FirstNpc + n of RomE4_SprRec loaded as
;   Evt_LoadSpriteRec loads one (frames, palette, animation, size), but
;   the graphics are unpacked to bank $7F: the record's SprRec_Gfx index
;   is looked up with Evt_FindOrAddUnk0920 (Evt_Unk0920Key). Found (an
;   object already unpacked it): Obj_GfxOfs = that object's. Not found:
;   the pack its Field_E4Ptr0 pointer names is unpacked (Decomp_ToWramVec)
;   to $7F:ObjQ_Unk71 (where Evt_InitWramSprite pointed Obj_GfxOfs) and
;   ObjQ_Unk71 moves past it (Decomp_OutLen); if that wraps below
;   ObjQ_Unk71Init, the game stops on colour Halt_ColorWramGfxFull
;   (Sys_HaltWithColor, never returns). On both paths ObjQ_Unk71 (as it
;   was before the unpack) is stored in the GfxOfs field of FieldBtlObj
;   record 0, 1 or 2 by ObjQ_Unk73 (0, 1, 2-$80; the CMP #$01 / BMI
;   also sends $81 and up to record 0; what reads them there outside a
;   battle is not traced) and ObjQ_Unk73 counts up.
;   X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $82).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur, ObjQ_*,
;   the Field_E4Ptr* pointers and the scratch are dp), DB=$00 (Obj_*
;   tables, the Decomp_* block and the multiplier absolute); Y = the
;   opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = EvtOp_SavedPos = Y + 2, C=1;
;   A and Y clobbered; EvtSpr_RecOfs, EvtSpr_Idx, Evt_Unk0920Key and the
;   Decomp_* block (when unpacked) written.
; ------------------------------------------------------------
Evt_Op82_InitWramSprite:
    LDA.b #!Obj_Unk1100Kind4
    JSR Evt_InitWramSprite
    LDA.b #!SprRec_Bytes
    STA.w WRMPYB
    STY.b !EvtOp_SavedPos
    LDX.b !Obj_Cur
    LDA.b #!Obj_Unk1B01Solid
    STA.w !Obj_Unk1B01,X
    LDX.w RDMPYL
    STX.b !EvtSpr_RecOfs
    LDA.l !RomE4_NpcSprRec+!SprRec_Frames,X
    REP #$20
    AND.w #!Eng_LowByteMask
    STA.b !EvtSpr_Idx
    CLC
    ADC.b !EvtSpr_Idx
    ADC.b !EvtSpr_Idx                   ; x 3: a 24-bit pointer
    TAY
    LDA.b [!Field_E4Ptr1],Y
    LDX.b !Obj_Cur
    STA.w !Obj_FrameOfs,X
    SEP #$20
    INY
    INY
    LDA.b [!Field_E4Ptr1],Y
    STA.w !Obj_FrameBank,X
    LDX.b !EvtSpr_RecOfs
    LDA.l !RomE4_NpcSprRec+!SprRec_Pal,X
    STA.w WRMPYA
    LDA.b #!Pal_ObjColorBytes
    STA.w WRMPYB
    NOP                                 ; wait for the product
    NOP
    NOP
    REP #$20
    LDA.w RDMPYL
    CLC
    ADC.w #!Obj_PalSrcBase              ; adds 0 (quirk)
    LDX.b !Obj_Cur
    STA.w !Obj_PalSrc,X
    SEP #$20
    LDX.b !EvtSpr_RecOfs
    LDA.l !RomE4_NpcSprRec+!SprRec_Anim,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAY
    INY
    INY
    LDA.b [!Field_E4Ptr2],Y             ; the next entry
    DEY
    DEY
    SEC
    SBC.b [!Field_E4Ptr2],Y
    LSR A
    LSR A
    LDX.b !Obj_Cur
    STA.w !Obj_AnimFacingStride,X
    LDA.b [!Field_E4Ptr2],Y
    STA.w !Obj_AnimFrameTbl,X
    LDA.b [!Field_E4Ptr3],Y
    STA.w !Obj_AnimTimeTbl,X
    SEP #$20
    LDX.b !EvtSpr_RecOfs
    LDA.l !RomE4_NpcSprRec+!SprRec_Size,X
    LDX.b !Obj_Cur
    STA.w !Obj_SprSize,X
    LDX.b !EvtSpr_RecOfs
    LDA.l !RomE4_NpcSprRec+!SprRec_Gfx,X
    STA.b !Evt_Unk0920Key
    JSR Evt_FindOrAddUnk0920
    BCC .unpack
    REP #$20
    AND.w #!Eng_LowByteMask
    TAX
    LDA.w !Obj_GfxOfs,X                 ; the object that unpacked it
    LDX.b !Obj_Cur
    STA.w !Obj_GfxOfs,X
    SEP #$20
    LDA.b !ObjQ_Unk73
    CMP.b #$01
    BMI .shared_rec0
    BEQ .shared_rec1
    REP #$20
    LDA.b !ObjQ_Unk71
    STA.l FieldBtlObj[2].GfxOfs
    SEP #$20
    BRA .shared_done
.shared_rec0:
    REP #$20
    LDA.b !ObjQ_Unk71
    STA.l FieldBtlObj[0].GfxOfs
    SEP #$20
    BRA .shared_done
.shared_rec1:
    REP #$20
    LDA.b !ObjQ_Unk71
    STA.l FieldBtlObj[1].GfxOfs
    SEP #$20
.shared_done:
    INC.b !ObjQ_Unk73
    LDX.b !EvtOp_SavedPos
    SEC
    RTS
.unpack:
    LDA.b !Evt_Unk0920Key
    REP #$20
    AND.w #!Eng_LowByteMask
    STA.b !EvtSpr_Idx
    CLC
    ADC.b !EvtSpr_Idx
    ADC.b !EvtSpr_Idx                   ; x 3: a 24-bit pointer
    TAY
    LDA.b [!Field_E4Ptr0],Y
    STA.w !Decomp_Src
    LDA.b !ObjQ_Unk71
    STA.w !Decomp_Dest
    SEP #$20
    LDA.b !ObjQ_Unk73
    CMP.b #$01
    BMI .unpack_rec0
    BEQ .unpack_rec1
    REP #$20
    LDA.b !ObjQ_Unk71
    STA.l FieldBtlObj[2].GfxOfs
    SEP #$20
    BRA .unpack_go
.unpack_rec0:
    REP #$20
    LDA.b !ObjQ_Unk71
    STA.l FieldBtlObj[0].GfxOfs
    SEP #$20
    BRA .unpack_go
.unpack_rec1:
    REP #$20
    LDA.b !ObjQ_Unk71
    STA.l FieldBtlObj[1].GfxOfs
    SEP #$20
.unpack_go:
    INY
    INY
    LDA.b [!Field_E4Ptr0],Y
    STA.w !Decomp_SrcBank
    LDA.b #!Bank7F
    STA.w !Decomp_DestBank
    JSL Decomp_ToWramVec
    REP #$20
    LDA.w !Decomp_OutLen
    CLC
    ADC.b !ObjQ_Unk71
    STA.b !ObjQ_Unk71
    CMP.w #!ObjQ_Unk71Init
    BPL .fits
    SEP #$20
    LDX.w #!Halt_ColorWramGfxFull
    BRL Sys_HaltWithColor
.fits:
    SEP #$20
    INC.b !ObjQ_Unk73
    LDX.b !EvtOp_SavedPos
    SEC
    RTS

; ------------------------------------------------------------
; $C0:46DF — Evt_Op83_InitEnemySprite (392 bytes, $46DF–$4866)
; Event opcode $83 (3 bytes: $83, n, b): Evt_InitWramSprite with kind 5
;   (Obj_Unk1100Kind5), Obj_Unk1B01 = Obj_Unk1B01Solid, then record n
;   of RomE4_EnemySprRec (EvtSpr_EnemyRecBytes each; its first five
;   bytes laid out as a RomE4_SprRec record; "enemy" is a guess from the
;   table's size and its own graphics path) loaded as
;   Evt_Op82_InitWramSprite loads one, except for the graphics:
;   - n below EvtSpr_RomGfxMin: Evt_FindOrAddUnk0920 as in opcode $82
;     (shared, or unpacked to $7F:ObjQ_Unk71 with the same overflow
;     stop), without the FieldBtlObj stores and ObjQ_Unk73;
;   - n EvtSpr_RomGfxMin ($F8) and up: Obj_GfxOfs / Obj_GfxBank = the
;     Field_E4Ptr0 pointer itself (graphics read from ROM).
;   Then (.tile_slot) the object gets the fixed OBJ tile slot s = (b &
;   EvtSpr_SlotMask) + 1: Obj_TileSlot[s] = Obj_Cur, Obj_VramTile = (s &
;   $FE) x 16 + (s & 1) x 8 and Obj_TileRecOfs = s x $20 (as the slot
;   banner of Obj_Unk6F9A reads them); with Obj_SprSize size class 3,
;   Field_UnkAEObj = Obj_Cur and Spr_LoadLargeObj; with b bit 7 set,
;   Obj_Unk1100 = Obj_Unk1100Kind6. X = Y + 3, C=1.
; Reached through Evt_OpcodeTable (opcode $83).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur, ObjQ_*,
;   the Field_E4Ptr* pointers and the scratch are dp), DB=$00 (Obj_*
;   tables, the Decomp_* block and the multiplier absolute); Y = the
;   opcode's offset in Evt_Data.
; Exit: M=1, X=0 (REP #$10 after the 8-bit slot code), DP and DB
;   unchanged; X = Y + 3, C=1; A and Y clobbered; EvtOp_SavedPos = Y +
;   2; EvtSpr_RecOfs, EvtSpr_Idx (its low byte = s at the end),
;   Evt_Unk0920Key and EvtSpr_SlotArg written, the Decomp_* block when
;   unpacked, Field_UnkAEObj and Spr_LoadLargeObj's writes for size 3.
; ------------------------------------------------------------
Evt_Op83_InitEnemySprite:
    LDA.b #!Obj_Unk1100Kind5
    JSR Evt_InitWramSprite
    LDA.b #!EvtSpr_EnemyRecBytes
    STA.w WRMPYB
    STY.b !EvtOp_SavedPos
    LDX.b !Obj_Cur
    LDA.b #!Obj_Unk1B01Solid
    STA.w !Obj_Unk1B01,X
    LDX.w RDMPYL
    STX.b !EvtSpr_RecOfs
    LDA.l !RomE4_EnemySprRec+!SprRec_Frames,X
    REP #$20
    AND.w #!Eng_LowByteMask
    STA.b !EvtSpr_Idx
    CLC
    ADC.b !EvtSpr_Idx
    ADC.b !EvtSpr_Idx                   ; x 3: a 24-bit pointer
    TAY
    LDA.b [!Field_E4Ptr1],Y
    LDX.b !Obj_Cur
    STA.w !Obj_FrameOfs,X
    SEP #$20
    INY
    INY
    LDA.b [!Field_E4Ptr1],Y
    STA.w !Obj_FrameBank,X
    LDX.b !EvtSpr_RecOfs
    LDA.l !RomE4_EnemySprRec+!SprRec_Pal,X
    STA.w WRMPYA
    LDA.b #!Pal_ObjColorBytes
    STA.w WRMPYB
    NOP                                 ; wait for the product
    NOP
    NOP
    REP #$20
    LDA.w RDMPYL
    CLC
    ADC.w #!Obj_PalSrcBase              ; adds 0 (quirk)
    LDX.b !Obj_Cur
    STA.w !Obj_PalSrc,X
    SEP #$20
    LDX.b !EvtSpr_RecOfs
    LDA.l !RomE4_EnemySprRec+!SprRec_Anim,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAY
    INY
    INY
    LDA.b [!Field_E4Ptr2],Y             ; the next entry
    DEY
    DEY
    SEC
    SBC.b [!Field_E4Ptr2],Y
    LSR A
    LSR A
    LDX.b !Obj_Cur
    STA.w !Obj_AnimFacingStride,X
    LDA.b [!Field_E4Ptr2],Y
    STA.w !Obj_AnimFrameTbl,X
    LDA.b [!Field_E4Ptr3],Y
    STA.w !Obj_AnimTimeTbl,X
    SEP #$20
    LDX.b !EvtSpr_RecOfs
    LDA.l !RomE4_EnemySprRec+!SprRec_Size,X
    LDX.b !Obj_Cur
    STA.w !Obj_SprSize,X
    LDX.b !EvtSpr_RecOfs
    LDA.l !RomE4_EnemySprRec+!SprRec_Gfx,X
    STA.b !Evt_Unk0920Key
    LDX.b !Obj_Cur
    LDA.w !Obj_Unk1101,X
    CMP.b #!EvtSpr_RomGfxMin
    BCC .lookup
    BRL .rom_gfx
.lookup:
    JSR Evt_FindOrAddUnk0920
    BCS .shared
    BRL .unpack
.shared:
    REP #$20
    AND.w #!Eng_LowByteMask
    TAX
    LDA.w !Obj_GfxOfs,X                 ; the object that unpacked it
    LDX.b !Obj_Cur
    STA.w !Obj_GfxOfs,X
    SEP #$20
.tile_slot:
    LDX.b !EvtOp_SavedPos
    LDA.l !Evt_Data,X
    STA.b !EvtSpr_SlotArg
    AND.b #!EvtSpr_SlotMask
    INC A
    SEP #$10
    TAX
    LDA.b !Obj_Cur
    STA.w !Obj_TileSlot,X
    TXA
    REP #$20
    AND.w #!ObjTile_PairMask
    ASL A
    ASL A
    ASL A
    ASL A
    STA.b !EvtSpr_Idx
    TXA
    AND.w #!ObjTile_OddBit
    ASL A
    ASL A
    ASL A
    CLC
    ADC.b !EvtSpr_Idx
    STX.b !EvtSpr_Idx
    LDX.b !Obj_Cur
    STA.w !Obj_VramTile,X
    SEP #$20
    LDA.b !EvtSpr_Idx
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    ASL A
    ASL A
    ASL A
    ASL A
    STA.w !Obj_TileRecOfs,X
    SEP #$20
    LDA.w !Obj_SprSize,X
    AND.b #!ObjSpr_SizeMask
    CMP.b #!ObjSpr_SizeLarge
    BCC .not_large
    LDX.b !Obj_Cur
    STX.b !Field_UnkAEObj
    JSR Spr_LoadLargeObj
.not_large:
    LDA.b !EvtSpr_SlotArg
    BPL .done
    LDA.b #!Obj_Unk1100Kind6
    LDX.b !Obj_Cur
    STA.w !Obj_Unk1100,X
.done:
    REP #$10
    LDX.b !EvtOp_SavedPos
    INX
    SEC
    RTS
.unpack:
    LDA.b !Evt_Unk0920Key
    REP #$20
    AND.w #!Eng_LowByteMask
    STA.b !EvtSpr_Idx
    CLC
    ADC.b !EvtSpr_Idx
    ADC.b !EvtSpr_Idx                   ; x 3: a 24-bit pointer
    TAY
    LDA.b [!Field_E4Ptr0],Y
    STA.w !Decomp_Src
    LDA.b !ObjQ_Unk71
    STA.w !Decomp_Dest
    SEP #$20
    INY
    INY
    LDA.b [!Field_E4Ptr0],Y
    STA.w !Decomp_SrcBank
    LDA.b #!Bank7F
    STA.w !Decomp_DestBank
    JSL Decomp_ToWramVec
    REP #$20
    LDA.w !Decomp_OutLen
    CLC
    ADC.b !ObjQ_Unk71
    STA.b !ObjQ_Unk71
    CMP.w #!ObjQ_Unk71Init
    BPL .fits
    SEP #$20
    LDX.w #!Halt_ColorWramGfxFull
    BRL Sys_HaltWithColor
.fits:
    SEP #$20
    BRL .tile_slot
.rom_gfx:
    LDA.b !Evt_Unk0920Key
    REP #$20
    AND.w #!Eng_LowByteMask
    STA.b !EvtSpr_Idx
    CLC
    ADC.b !EvtSpr_Idx
    ADC.b !EvtSpr_Idx                   ; x 3: a 24-bit pointer
    TAY
    LDA.b [!Field_E4Ptr0],Y
    LDX.b !Obj_Cur
    STA.w !Obj_GfxOfs,X
    SEP #$20
    INY
    INY
    LDA.b [!Field_E4Ptr0],Y
    STA.w !Obj_GfxBank,X
    BRL .tile_slot

; ============================================================
; Event opcodes: object settings and palette animations
; ($C0:4867–$C0:4D05)
; Handlers in Evt_OpcodeTable for the object's flags, speed,
; place and priority bits, and the two opcodes that start the location's
; palette animations: they fill a free FieldAnimB record (the 12-byte
; records FieldFD_LoadAnimSetB fills from the location's list, worked on
; each frame by FdVec_FFF7: not analysed, so the record fields keep Unk
; names) or copy colours straight into Pal_Buf / Pal_CgramBuf. As the
; other handlers: entered with Y = the opcode's offset in Evt_Data, they
; return X = where the script goes on and C=1 (keep running) or C=0
; (stop this object for this run). "a" / "b" name event words at
; Evt_Unk7F0200 + a x 2 (their low byte is used).
; ============================================================

; ------------------------------------------------------------
; $C0:4867 — Evt_Op84_SetUnk1B01 (15 bytes, $4867–$4875)
; Event opcode $84 (2 bytes: $84, value): Obj_Cur's Obj_Unk1B01 = value
;   (bit 0: the object blocks the leader, Obj_Unk1B01Solid; bit 1: it
;   can be pushed, Obj_Unk1B01Push). X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $84).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur is dp),
;   DB=$00 (Obj_* tables absolute); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = the opcode + 2, C=1; A = the
;   value; Y = the opcode + 2.
; ------------------------------------------------------------
Evt_Op84_SetUnk1B01:
    INY
    TYX
    LDA.l !Evt_Data,X
    LDX.b !Obj_Cur
    STA.w !Obj_Unk1B01,X
    INY
    TYX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4876 — Evt_Op87_SetScriptPeriod (28 bytes, $4876–$4891)
; Event opcode $87 (2 bytes: $87, n): Obj_Cur's Obj_Unk1000 = (n + 1)
;   | its old bit 7 (Obj_Unk1000Bit7 kept): the object's script runs
;   every n + 1 frames (Vblank_Unk59D9 reloads Obj_Unk1001 from it), and
;   Obj_Unk1001 (the countdown) gets the same value at once. Quirk: the
;   countdown is not masked, so with bit 7 set it gets bit 7 too; n + 1
;   is not masked either (n = $7F gives bit 7). X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $87).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur and the
;   scratch are dp), DB=$00 (Obj_* tables absolute); Y = the opcode's
;   offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = the opcode + 2, C=1; A = the
;   new Obj_Unk1000; Y = the opcode + 1; Eng_Scratch ($D9) = n + 1.
; ------------------------------------------------------------
Evt_Op87_SetScriptPeriod:
    INY
    TYX
    LDA.l !Evt_Data,X
    LDX.b !Obj_Cur
    INC A
    STA.b !Eng_Scratch
    LDA.w !Obj_Unk1000,X
    AND.b #!Obj_Unk1000Bit7
    ORA.b !Eng_Scratch
    STA.w !Obj_Unk1000,X
    STA.w !Obj_Unk1001,X
    TYX
    INX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4892 — Evt_Op88_ObjPalAnim (444 bytes, $4892–$4A4D)
; Event opcode $88 ($88, kind, ...): palette animations on Obj_Cur's
;   own palette (its colour 0 is EvtPal_Base = Obj_OamAttr x 8 +
;   EvtPal_SpriteColor0: Obj_OamAttr holds the palette slot x 2). By
;   the kind byte:
; - 0 (2 bytes): undo: when ObjX_PalAnimRec is not ObjX_PalAnimNone,
;   that record's FieldAnimB.Unk0 = 0 (free) and ObjX_PalAnimRec =
;   ObjX_PalAnimNone, and the object's 12 colours are copied again
;   from bank $E4 (Obj_PalSrc) into colours 1-12 of its rows in
;   Pal_Buf and Pal_CgramBuf, as Obj_PalSlotFixed does. X = Y + 2, C=1
;   (also when there was no record: nothing is copied then).
; - $20 or $30 exactly (4 bytes: $88, kind, c, s): a free record (from
;   Evt_FindFreeAnimB) gets .Unk0 = kind, .Unk1 = EvtPal_Base + (c >>
;   4), .Unk2 = c & $0F, .Unk4 = 0, .Unk5 = s; ObjX_PalAnimRec = its
;   offset (a record the object already had is not freed). X = Y + 4,
;   C=1; with no record free X = Y + 4, C=0 (the opcode is dropped).
; - $4x or $5x (5 bytes: $88, kind, c, d, s): a free record gets .Unk0
;   = kind & $F0, .Unk6 = kind & $0F, .Unk1 / .Unk2 from c as above,
;   .Unk3 = EvtPal_Unk3Init, .Unk4 = 0, .Unk5 = s, .Unk7 = d's high
;   nibble in both nibbles, .Unk8 = d's low nibble in both; not linked
;   to the object. X = Y + 5, C=1; no record free: X = Y + 5, C=0.
; - $8x (2 + n bytes: $88, kind, the word n, n - 2 colour bytes): the
;   colour bytes are copied (MVN from bank $7F) to Pal_CgramBuf and
;   Pal_Buf from colour EvtPal_Base | (kind & $0F) on. X = Y + n + 2,
;   C=1.
; - any other kind (2 bytes): nothing; X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $88).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur and the
;   EvtPal_* scratch are dp; EvtOp_SavedPos), DB=$00 (Obj_* tables and
;   FieldAnimB absolute); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged (DB saved around the MVNs); X and
;   C as above; A and Y clobbered (Y = the record's offset on the
;   record paths); EvtOp_SavedPos = the opcode's offset; EvtPal_Arg,
;   EvtPal_Base / Src, EvtPal_Speeds / ColOfs and EvtPal_Count ($C1)
;   written on the paths that use them.
; ------------------------------------------------------------
Evt_Op88_ObjPalAnim:
    STY.b !EvtOp_SavedPos
    TYX
    INX
    LDA.l !Evt_Data,X
    BEQ .restore
    STA.b !EvtPal_Arg
    CMP.b #!EvtPal_Kind20
    BEQ .linked
    CMP.b #!EvtPal_Kind30
    BEQ .linked
    AND.b #!FieldAnimB_KindMask
    CMP.b #!EvtPal_Kind40
    BNE .not_40
    BRL .cycle
.not_40:
    CMP.b #!EvtPal_Kind50
    BNE .not_50
    BRL .cycle
.not_50:
    CMP.b #!FieldAnimB_Kind80
    BNE .ignored
    BRL .copy
.ignored:
    INX
    SEC
    RTS
.restore:
    LDX.b !Obj_Cur
    REP #$20
    LDA.l !ObjX_PalAnimRec,X
    BMI .no_record
    TAY
    LDA.w #!ObjX_PalAnimNone
    STA.l !ObjX_PalAnimRec,X
    SEP #$20
    LDA.b #$00
    STA.w FieldAnimB.Unk0,Y             ; free the record
    LDX.b !Obj_Cur
    LDA.w !Obj_OamAttr,X
    REP #$30
    AND.w #!Eng_LowByteMask
    ASL A
    ASL A
    ASL A
    ASL A                               ; slot x $20: its Pal_Buf row
    INC A
    INC A                               ; colour 1
    CLC
    ADC.w #!Pal_SpriteRows&$FFFF
    TAY
    PHB
    PHY
    LDA.w !Obj_PalSrc,X
    TAX
    PHX
    LDA.w #!ObjPal_CopyCount
    MVN !Bank7E,!BankE4                 ; lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    PLX
    PLA
    CLC
    ADC.w #!Pal_CgramBuf-!Pal_Buf       ; the same colours in Pal_CgramBuf
    TAY
    LDA.w #!ObjPal_CopyCount
    MVN !Bank7E,!BankE4                 ; lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    PLB
    SEP #$20
    LDX.b !EvtOp_SavedPos
    INX
    INX
    SEC
    RTS
.no_record:
    SEP #$20
    LDX.b !EvtOp_SavedPos
    INX
    INX
    SEC
    RTS
.linked:
    JSR Evt_FindFreeAnimB
    BCC .linked_free
    LDX.b !EvtOp_SavedPos
    INX
    INX
    INX
    INX
    CLC
    RTS
.linked_free:
    REP #$20
    TYA
    LDX.b !Obj_Cur
    STA.l !ObjX_PalAnimRec,X
    SEP #$20
    LDA.b !EvtPal_Arg
    STA.w FieldAnimB.Unk0,Y
    LDX.b !Obj_Cur
    LDA.w !Obj_OamAttr,X
    ASL A
    ASL A
    ASL A
    CLC
    ADC.b #!EvtPal_SpriteColor0
    STA.b !EvtPal_Base
    LDX.b !EvtOp_SavedPos
    INX
    INX
    LDA.l !Evt_Data,X
    STA.b !EvtPal_Arg                   ; c
    INX
    LDA.l !Evt_Data,X
    STA.w FieldAnimB.Unk5,Y
    LDA.b #$00
    STA.w FieldAnimB.Unk4,Y
    INX
    LDA.b !EvtPal_Arg
    AND.b #!EvtPal_NibbleMask
    STA.w FieldAnimB.Unk2,Y
    LDA.b !EvtPal_Arg
    LSR A
    LSR A
    LSR A
    LSR A
    CLC
    ADC.b !EvtPal_Base
    STA.w FieldAnimB.Unk1,Y
    SEC
    RTS
.cycle:
    JSR Evt_FindFreeAnimB
    BCC .cycle_free
    LDX.b !EvtOp_SavedPos
    INX
    INX
    INX
    INX
    INX
    CLC
    RTS
.cycle_free:
    LDA.b !EvtPal_Arg
    AND.b #!FieldAnimB_KindMask
    STA.w FieldAnimB.Unk0,Y
    LDA.b !EvtPal_Arg
    AND.b #!EvtPal_NibbleMask
    STA.w FieldAnimB.Unk6,Y
    LDX.b !Obj_Cur
    LDA.w !Obj_OamAttr,X
    ASL A
    ASL A
    ASL A
    CLC
    ADC.b #!EvtPal_SpriteColor0
    STA.b !EvtPal_Base
    LDX.b !EvtOp_SavedPos
    INX
    INX
    LDA.l !Evt_Data,X
    STA.b !EvtPal_Arg                   ; c
    INX
    LDA.l !Evt_Data,X
    STA.b !EvtPal_Speeds                ; d
    INX
    LDA.l !Evt_Data,X
    STA.w FieldAnimB.Unk5,Y
    LDA.b #$00
    STA.w FieldAnimB.Unk4,Y
    LDA.b #!EvtPal_Unk3Init
    STA.w FieldAnimB.Unk3,Y
    INX
    LDA.b !EvtPal_Arg
    AND.b #!EvtPal_NibbleMask
    STA.w FieldAnimB.Unk2,Y
    LDA.b !EvtPal_Arg
    LSR A
    LSR A
    LSR A
    LSR A
    CLC
    ADC.b !EvtPal_Base
    STA.w FieldAnimB.Unk1,Y
    LDA.b !EvtPal_Speeds
    AND.b #!FieldAnimB_KindMask
    LSR A
    LSR A
    LSR A
    LSR A
    STA.b !EvtPal_Arg
    LDA.b !EvtPal_Speeds
    AND.b #!FieldAnimB_KindMask
    ORA.b !EvtPal_Arg
    STA.w FieldAnimB.Unk7,Y             ; d's high nibble, twice
    LDA.b !EvtPal_Speeds
    AND.b #!EvtPal_NibbleMask
    ASL A
    ASL A
    ASL A
    ASL A
    STA.b !EvtPal_Arg
    LDA.b !EvtPal_Speeds
    AND.b #!EvtPal_NibbleMask
    ORA.b !EvtPal_Arg
    STA.w FieldAnimB.Unk8,Y             ; d's low nibble, twice
    SEC
    RTS
.copy:
    LDX.b !Obj_Cur
    LDA.w !Obj_OamAttr,X
    ASL A
    ASL A
    ASL A
    CLC
    ADC.b #!EvtPal_SpriteColor0
    STA.b !EvtPal_Base
    LDA.b !EvtPal_Arg
    AND.b #!EvtPal_NibbleMask
    ORA.b !EvtPal_Base                  ; the first colour
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    STA.b !EvtPal_ColOfs
    CLC
    ADC.w #!Pal_CgramBuf&$FFFF
    TAY
    LDX.b !EvtOp_SavedPos
    INX
    INX
    LDA.l !Evt_Data,X                   ; the word n
    DEC A
    DEC A
    DEC A                               ; MVN count: n - 2 bytes
    STA.b !EvtPal_Count
    INX
    INX
    TXA
    CLC
    ADC.w #!Evt_DataAddr
    STA.b !EvtPal_Src
    TAX
    LDA.b !EvtPal_Count
    PHB
    MVN !Bank7E,!Bank7F                 ; lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    LDA.b !EvtPal_ColOfs
    CLC
    ADC.w #!Pal_Buf&$FFFF
    TAY
    LDX.b !EvtPal_Src
    LDA.b !EvtPal_Count
    MVN !Bank7E,!Bank7F                 ; lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    PLB
    TXA                                 ; past the colour bytes
    SEC
    SBC.w #!Evt_DataAddr
    TAX
    SEP #$20
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4A4E — Evt_Op2E_PalAnim (222 bytes, $4A4E–$4B2B)
; Event opcode $2E ($2E, kind, ...): as Evt_Op88_ObjPalAnim's kinds
;   $4x/$5x and $8x, with absolute colour numbers instead of the
;   object's palette. By kind & $F0:
; - $40 or $50 (6 bytes: $2E, kind, c, e, d, s): a free FieldAnimB
;   record (Evt_FindFreeAnimB) gets .Unk0 = kind & $F0, .Unk6 = kind &
;   $0F, .Unk1 = c, .Unk2 = e, .Unk3 = EvtPal_Unk3Init, .Unk4 = 0,
;   .Unk5 = s, .Unk7 = d's high nibble in both nibbles, .Unk8 = d's low
;   nibble in both. X = Y + 6, C=1; with no record free X = Y + 6, C=0
;   (the opcode is dropped).
; - $80 (3 + n bytes: $2E, kind, c, the word n, n - 2 colour bytes): the
;   colour bytes are copied (MVN from bank $7F) to Pal_CgramBuf and
;   Pal_Buf from colour c on. X = Y + n + 3, C=1.
; - any other (2 bytes): nothing; X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $2E).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (the EvtPal_*
;   scratch and EvtOp_SavedPos are dp), DB=$00 (FieldAnimB absolute);
;   Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged (DB saved around the MVNs); X and
;   C as above; A and Y clobbered (Y = the record's offset on the
;   record path); EvtOp_SavedPos = the opcode's offset; EvtPal_Arg,
;   EvtPal_Speeds / ColOfs, EvtPal_Src and EvtPal_Count ($C1) written
;   on the paths that use them.
; ------------------------------------------------------------
Evt_Op2E_PalAnim:
    STY.b !EvtOp_SavedPos
    TYX
    INX
    LDA.l !Evt_Data,X
    STA.b !EvtPal_Arg
    AND.b #!FieldAnimB_KindMask
    CMP.b #!EvtPal_Kind40
    BNE .not_40
    BRL .cycle
.not_40:
    CMP.b #!EvtPal_Kind50
    BNE .not_50
    BRL .cycle
.not_50:
    CMP.b #!FieldAnimB_Kind80
    BNE .ignored
    BRL .copy
.ignored:
    INX
    SEC
    RTS
.cycle:
    JSR Evt_FindFreeAnimB
    BCC .cycle_free
    LDX.b !EvtOp_SavedPos
    INX
    INX
    INX
    INX
    INX
    INX
    CLC
    RTS
.cycle_free:
    LDA.b !EvtPal_Arg
    AND.b #!FieldAnimB_KindMask
    STA.w FieldAnimB.Unk0,Y
    LDA.b !EvtPal_Arg
    AND.b #!EvtPal_NibbleMask
    STA.w FieldAnimB.Unk6,Y
    LDX.b !EvtOp_SavedPos
    INX
    INX
    LDA.l !Evt_Data,X
    STA.w FieldAnimB.Unk1,Y             ; c
    INX
    LDA.l !Evt_Data,X
    STA.w FieldAnimB.Unk2,Y             ; e
    INX
    LDA.l !Evt_Data,X
    STA.b !EvtPal_Speeds                ; d
    INX
    LDA.l !Evt_Data,X
    STA.w FieldAnimB.Unk5,Y
    LDA.b #$00
    STA.w FieldAnimB.Unk4,Y
    LDA.b #!EvtPal_Unk3Init
    STA.w FieldAnimB.Unk3,Y
    INX
    LDA.b !EvtPal_Speeds
    AND.b #!FieldAnimB_KindMask
    LSR A
    LSR A
    LSR A
    LSR A
    STA.b !EvtPal_Arg
    LDA.b !EvtPal_Speeds
    AND.b #!FieldAnimB_KindMask
    ORA.b !EvtPal_Arg
    STA.w FieldAnimB.Unk7,Y             ; d's high nibble, twice
    LDA.b !EvtPal_Speeds
    AND.b #!EvtPal_NibbleMask
    ASL A
    ASL A
    ASL A
    ASL A
    STA.b !EvtPal_Arg
    LDA.b !EvtPal_Speeds
    AND.b #!EvtPal_NibbleMask
    ORA.b !EvtPal_Arg
    STA.w FieldAnimB.Unk8,Y             ; d's low nibble, twice
    SEC
    RTS
.copy:
    LDX.b !EvtOp_SavedPos
    INX
    INX
    LDA.l !Evt_Data,X                   ; c
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    STA.b !EvtPal_ColOfs
    CLC
    ADC.w #!Pal_CgramBuf&$FFFF
    TAY
    INX
    LDA.l !Evt_Data,X                   ; the word n
    DEC A
    DEC A
    DEC A                               ; MVN count: n - 2 bytes
    STA.b !EvtPal_Count
    INX
    INX
    TXA
    CLC
    ADC.w #!Evt_DataAddr
    STA.b !EvtPal_Src
    TAX
    LDA.b !EvtPal_Count
    PHB
    MVN !Bank7E,!Bank7F                 ; lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    LDA.b !EvtPal_ColOfs
    CLC
    ADC.w #!Pal_Buf&$FFFF
    TAY
    LDX.b !EvtPal_Src
    LDA.b !EvtPal_Count
    MVN !Bank7E,!Bank7F                 ; lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    PLB
    TXA                                 ; past the colour bytes
    SEC
    SBC.w #!Evt_DataAddr
    TAX
    SEP #$20
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4B2C — Evt_FindFreeAnimB (29 bytes, $4B2C–$4B48)
; Finds a free FieldAnimB record (.Unk0 = 0) among the first
;   FieldAnimB_Searched (8) of the 12, from record 0 on; records 8-11
;   are never handed out here.
; Callers (3 JSR sites): Evt_Op88_ObjPalAnim ($C0:4919, $C0:4970) and Evt_Op2E_PalAnim ($C0:4A72).
; On entry: M=1 (8-bit A), X=0 (16-bit Y), DP any (not used), DB=$00
;   (FieldAnimB absolute).
; Exit: M=1, X=0, DP and DB unchanged; C=0: Y = the free record's
;   offset; C=1: none free, Y = FieldAnimB_Size x 8; A clobbered; X
;   unchanged.
; ------------------------------------------------------------
Evt_FindFreeAnimB:
    LDY.w #$0000
.loop:
    LDA.w FieldAnimB.Unk0,Y
    BEQ .free
    REP #$20
    TYA
    CLC
    ADC.w #!FieldAnimB_Size
    TAY
    SEP #$20
    CPY.w #!FieldAnimB_Size*!FieldAnimB_Searched
    BCS .none
    BRA .loop
.free:
    CLC
    RTS
.none:
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4B49 — Evt_Op89_SetSpeed (15 bytes, $4B49–$4B57)
; Event opcode $89 (2 bytes: $89, speed): Obj_Cur's Obj_Speed = speed
;   (the step the Obj_SetVelocity* routines scale the direction by).
;   X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $89).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur is dp),
;   DB=$00 (Obj_* tables absolute); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = the opcode + 2, C=1; A = the
;   speed; Y = the opcode + 1.
; ------------------------------------------------------------
Evt_Op89_SetSpeed:
    INY
    TYX
    LDA.l !Evt_Data,X
    LDX.b !Obj_Cur
    STA.w !Obj_Speed,X
    TYX
    INX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4B58 — Evt_Op8A_SetSpeedVar (28 bytes, $4B58–$4B73)
; Event opcode $8A (2 bytes: $8A, a): as Evt_Op89_SetSpeed with the low
;   byte of the event word a. X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $8A).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur is dp),
;   DB=$00 (Obj_* tables absolute); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = the opcode + 2, C=1; A = the
;   speed (B = a x 2 >> 8); Y = the opcode + 1.
; ------------------------------------------------------------
Evt_Op8A_SetSpeedVar:
    INY
    TYX
    LDA.l !Evt_Data,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAX
    SEP #$20
    LDA.l !Evt_Unk7F0200,X
    LDX.b !Obj_Cur
    STA.w !Obj_Speed,X
    TYX
    INX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4B74 — Evt_Op8B_PlaceAtTile (79 bytes, $4B74–$4BC2)
; Event opcode $8B (3 bytes: $8B, column, row): puts Obj_Cur on the
;   tile: Obj_PosX = column << 8 | EvtChar_SubXCentre, Obj_PosY = row
;   << 8 | EvtChar_SubYLower. When its Obj_OamFlags bit 7 is set
;   (Obj_OamFlagsTilePrio) the priorities follow the tile: Obj_PrioHigh
;   = (Map_TileAttrA & TileAttr_Prio) >> 2 | Oam_Prio2, Obj_PrioLow =
;   the same from Map_TileAttrB. That is the other way round from
;   Obj_SetVelocityChecked (A to PrioLow, B to PrioHigh); kept as found.
;   The tile index is column | row << 8 unmasked (no Map_ColMask1).
;   X = Y + 3, C=1.
; Reached through Evt_OpcodeTable (opcode $8B).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y: the 16-bit tile index),
;   DP=$0100 (Obj_Cur and EvtTile_Pos are dp), DB=$00 (Obj_* tables
;   absolute); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = the opcode + 3, C=1; A
;   clobbered; Y = the opcode + 2; EvtTile_Pos ($D9/$DA) written.
; ------------------------------------------------------------
Evt_Op8B_PlaceAtTile:
    INY
    TYX
    LDA.l !Evt_Data,X
    LDX.b !Obj_Cur
    STA.w !Obj_TileX,X
    STA.b !EvtTile_Pos
    LDA.b #!EvtChar_SubXCentre
    STA.w !Obj_PosX,X
    INY
    TYX
    LDA.l !Evt_Data,X
    LDX.b !Obj_Cur
    STA.w !Obj_TileY,X
    STA.b !EvtTile_Pos+1
    LDA.b #!EvtChar_SubYLower
    STA.w !Obj_PosY,X
    LDA.w !Obj_OamFlags,X
    BPL .done
    LDX.b !EvtTile_Pos
    LDA.l !Map_TileAttrA,X
    AND.b #!TileAttr_Prio
    LSR A
    LSR A
    ORA.b #!Oam_Prio2
    STA.b !EvtTile_PrioA
    LDA.l !Map_TileAttrB,X
    AND.b #!TileAttr_Prio
    LSR A
    LSR A
    ORA.b #!Oam_Prio2
    LDX.b !Obj_Cur
    STA.w !Obj_PrioLow,X
    LDA.b !EvtTile_PrioA
    STA.w !Obj_PrioHigh,X
.done:
    TYX
    INX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4BC3 — Evt_Op8C_PlaceAtTileVar (100 bytes, $4BC3–$4C26)
; Event opcode $8C (3 bytes: $8C, a, b): as Evt_Op8B_PlaceAtTile with
;   the column and row from the low bytes of the event words a and b,
;   except that Obj_PosX's low byte is not set (only Obj_TileX; the
;   object keeps its old place within the column). Priorities from the
;   tile as there (Map_TileAttrA to Obj_PrioHigh). X = Y + 3, C=1.
; Reached through Evt_OpcodeTable (opcode $8C).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y: the 16-bit tile index),
;   DP=$0100 (Obj_Cur and EvtTile_Pos are dp), DB=$00 (Obj_* tables
;   absolute); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = the opcode + 3, C=1; A
;   clobbered; Y = the opcode + 2; EvtTile_Pos ($D9/$DA) written.
; ------------------------------------------------------------
Evt_Op8C_PlaceAtTileVar:
    INY
    TYX
    LDA.l !Evt_Data,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAX
    SEP #$20
    LDA.l !Evt_Unk7F0200,X
    LDX.b !Obj_Cur
    STA.w !Obj_TileX,X
    STA.b !EvtTile_Pos
    INY
    TYX
    LDA.l !Evt_Data,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAX
    SEP #$20
    LDA.l !Evt_Unk7F0200,X
    LDX.b !Obj_Cur
    STA.w !Obj_TileY,X
    STA.b !EvtTile_Pos+1
    LDA.b #!EvtChar_SubYLower
    STA.w !Obj_PosY,X
    LDA.w !Obj_OamFlags,X
    BPL .done
    LDX.b !EvtTile_Pos
    LDA.l !Map_TileAttrA,X
    AND.b #!TileAttr_Prio
    LSR A
    LSR A
    ORA.b #!Oam_Prio2
    STA.b !EvtTile_PrioA
    LDA.l !Map_TileAttrB,X
    AND.b #!TileAttr_Prio
    LSR A
    LSR A
    ORA.b #!Oam_Prio2
    LDX.b !Obj_Cur
    STA.w !Obj_PrioLow,X
    LDA.b !EvtTile_PrioA
    STA.w !Obj_PrioHigh,X
.done:
    TYX
    INX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4C27 — Evt_Op8D_SetPos (77 bytes, $4C27–$4C73)
; Event opcode $8D (5 bytes: $8D, the words x, y): Obj_Cur's Obj_PosX =
;   x, Obj_PosY = y (16-bit: tile in the high byte); with Obj_OamFlags
;   bit 7 set the priorities follow the new tile (Obj_TileY << 8 |
;   Obj_TileX, unmasked) as in Evt_Op8B_PlaceAtTile (Map_TileAttrA to
;   Obj_PrioHigh). X = Y + 5, C=1.
; Reached through Evt_OpcodeTable (opcode $8D).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y: the 16-bit tile index),
;   DP=$0100 (Obj_Cur and EvtTile_PrioA are dp), DB=$00 (Obj_* tables
;   absolute); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = the opcode + 5, C=1; A
;   clobbered; Y = the opcode + 3; EvtTile_PrioA ($D9) written on the
;   bit-7 path.
; ------------------------------------------------------------
Evt_Op8D_SetPos:
    INY
    TYX
    REP #$20
    LDA.l !Evt_Data,X
    LDX.b !Obj_Cur
    STA.w !Obj_PosX,X
    INY
    INY
    TYX
    LDA.l !Evt_Data,X
    LDX.b !Obj_Cur
    STA.w !Obj_PosY,X
    SEP #$20
    LDA.w !Obj_OamFlags,X
    BPL .done
    LDA.w !Obj_TileY,X
    XBA
    LDA.w !Obj_TileX,X
    TAX
    LDA.l !Map_TileAttrA,X
    AND.b #!TileAttr_Prio
    LSR A
    LSR A
    ORA.b #!Oam_Prio2
    STA.b !EvtTile_PrioA
    LDA.l !Map_TileAttrB,X
    AND.b #!TileAttr_Prio
    LSR A
    LSR A
    ORA.b #!Oam_Prio2
    LDX.b !Obj_Cur
    STA.w !Obj_PrioLow,X
    LDA.b !EvtTile_PrioA
    STA.w !Obj_PrioHigh,X
.done:
    TYX
    INX
    INX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4C74 — Evt_Op8E_SetOamFlags (97 bytes, $4C74–$4CD4)
; Event opcode $8E (2 bytes: $8E, flags): Obj_Cur's Obj_OamFlags =
;   flags. With bit 7 (Obj_OamFlagsTilePrio) the priorities follow the
;   object's tile as in Evt_Op8D_SetPos (Map_TileAttrA to Obj_PrioHigh);
;   else they are fixed: Obj_PrioHigh = flags & $30
;   (Obj_OamFlagsPrioMask), Obj_PrioLow = (flags << 4) & $30. Either way
;   Obj_LastFrame = Obj_LastFrameNone and Obj_AnimTimer = 0 (the frame
;   is built again, probably). X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $8E).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y: the 16-bit tile index),
;   DP=$0100 (Obj_Cur and the scratch are dp), DB=$00 (Obj_* tables
;   absolute); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = the opcode + 2, C=1; A =
;   Obj_LastFrameNone; Y = the opcode + 1; Eng_Scratch ($D9) written
;   (EvtTile_PrioA or EvtPrio_Flags).
; ------------------------------------------------------------
Evt_Op8E_SetOamFlags:
    INY
    TYX
    LDA.l !Evt_Data,X
    LDX.b !Obj_Cur
    STA.w !Obj_OamFlags,X
    BIT.b #!Obj_OamFlagsTilePrio
    BEQ .fixed
    LDA.w !Obj_TileY,X
    XBA
    LDA.w !Obj_TileX,X
    TAX
    LDA.l !Map_TileAttrA,X
    AND.b #!TileAttr_Prio
    LSR A
    LSR A
    ORA.b #!Oam_Prio2
    STA.b !EvtTile_PrioA
    LDA.l !Map_TileAttrB,X
    AND.b #!TileAttr_Prio
    LSR A
    LSR A
    ORA.b #!Oam_Prio2
    LDX.b !Obj_Cur
    STA.w !Obj_PrioLow,X
    LDA.b !EvtTile_PrioA
    STA.w !Obj_PrioHigh,X
    LDA.b #!Obj_LastFrameNone
    STA.w !Obj_LastFrame,X
    STZ.w !Obj_AnimTimer,X
    TYX
    INX
    SEC
    RTS
.fixed:
    STA.b !EvtPrio_Flags
    AND.b #!Obj_OamFlagsPrioMask
    STA.w !Obj_PrioHigh,X
    LDA.b !EvtPrio_Flags
    ASL A
    ASL A
    ASL A
    ASL A
    AND.b #!Obj_OamFlagsPrioMask
    STA.w !Obj_PrioLow,X
    LDA.b #!Obj_LastFrameNone
    STA.w !Obj_LastFrame,X
    STZ.w !Obj_AnimTimer,X
    TYX
    INX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:4CD5 — Evt_Op90_SetUnk1A81On (11 bytes, $4CD5–$4CDF)
; Event opcode $90 (1 byte): Obj_Cur's Obj_Unk1A81 = Obj_Unk1A81On (1:
;   its frames are built, so it is probably shown). X = Y + 1, C=0 (the
;   object's run ends here).
; Evt_Op90_Store (the STA, X = Y + 1, C=0, with A = the value and X =
;   the object) is the shared tail of Evt_Op91_ClearUnk1A81,
;   Evt_Op7E_SetUnk1A81Bit7, Evt_Op7C_SetObjUnk1A81On and
;   Evt_Op7D_ClearObjUnk1A81 (BRA).
; Reached through Evt_OpcodeTable (opcode $90).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur is dp),
;   DB=$00 (Obj_* tables absolute); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = Y + 1, C=0; A = the value
;   stored; Y unchanged.
; ------------------------------------------------------------
Evt_Op90_SetUnk1A81On:
    LDX.b !Obj_Cur
    LDA.b #!Obj_Unk1A81On
Evt_Op90_Store:                         ; header: see Evt_Op90_SetUnk1A81On
    STA.w !Obj_Unk1A81,X
    TYX
    INX
    CLC
    RTS

; ------------------------------------------------------------
; $C0:4CE0 — Evt_Op91_ClearUnk1A81 (6 bytes, $4CE0–$4CE5)
; Event opcode $91 (1 byte): Obj_Cur's Obj_Unk1A81 = 0 (no frame build:
;   hidden, probably); X = Y + 1, C=0 through Evt_Op90_Store.
; Reached through Evt_OpcodeTable (opcode $91).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur is dp),
;   DB=$00 (Obj_* tables absolute); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = Y + 1, C=0; A = 0; Y
;   unchanged.
; ------------------------------------------------------------
Evt_Op91_ClearUnk1A81:
    LDX.b !Obj_Cur
    LDA.b #$00
    BRA Evt_Op90_Store

; ------------------------------------------------------------
; $C0:4CE6 — Evt_Op7E_SetUnk1A81Bit7 (6 bytes, $4CE6–$4CEB)
; Event opcode $7E (1 byte): Obj_Cur's Obj_Unk1A81 = $80 (bit 7 only,
;   FieldBtl_ObjUnk1A81Bit: outside 1..$7F, so no frame build, and the
;   battle hand-off treats the object specially); X = Y + 1, C=0
;   through Evt_Op90_Store.
; Reached through Evt_OpcodeTable (opcode $7E).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur is dp),
;   DB=$00 (Obj_* tables absolute); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = Y + 1, C=0; A = $80; Y
;   unchanged.
; ------------------------------------------------------------
Evt_Op7E_SetUnk1A81Bit7:
    LDX.b !Obj_Cur
    LDA.b #!FieldBtl_ObjUnk1A81Bit
    BRA Evt_Op90_Store

; ------------------------------------------------------------
; $C0:4CEC — Evt_Op7C_SetObjUnk1A81On (13 bytes, $4CEC–$4CF8)
; Event opcode $7C (2 bytes: $7C, slot): as Evt_Op90_SetUnk1A81On for
;   the object in slot: Obj_Unk1A81 = Obj_Unk1A81On. X = Y + 2, C=0
;   through Evt_Op90_Store.
; Reached through Evt_OpcodeTable (opcode $7C).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (its low byte
;   must be 0: TDC/XBA sets B from it), DB=$00 (Obj_* tables absolute);
;   Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = the opcode + 2, C=0; A = 1;
;   Y = the opcode + 1; B = 0 (TDC/XBA).
; ------------------------------------------------------------
Evt_Op7C_SetObjUnk1A81On:
    INY
    TYX
    TDC
    XBA                                 ; B = 0 for the 16-bit TAX
    LDA.l !Evt_Data,X
    TAX
    LDA.b #!Obj_Unk1A81On
    BRA Evt_Op90_Store

; ------------------------------------------------------------
; $C0:4CF9 — Evt_Op7D_ClearObjUnk1A81 (13 bytes, $4CF9–$4D05)
; Event opcode $7D (2 bytes: $7D, slot): as Evt_Op91_ClearUnk1A81 for
;   the object in slot: Obj_Unk1A81 = 0. X = Y + 2, C=0 through
;   Evt_Op90_Store.
; Reached through Evt_OpcodeTable (opcode $7D).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (its low byte
;   must be 0: TDC/XBA sets B from it), DB=$00 (Obj_* tables absolute);
;   Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = the opcode + 2, C=0; A = 0;
;   Y = the opcode + 1; B = 0 (TDC/XBA).
; ------------------------------------------------------------
Evt_Op7D_ClearObjUnk1A81:
    INY
    TYX
    TDC
    XBA                                 ; B = 0 for the 16-bit TAX
    LDA.l !Evt_Data,X
    TAX
    LDA.b #$00
    BRA Evt_Op90_Store

; ============================================================
; $C0:75A0 — Map_ClearBufC800 (73 bytes, $75A0–$75E8)
; (was Map_Unk75A0.) Zeroes the 2 KB WRAM buffer Map_BufC800
; ($7E:C800–$7E:CFFF) that Field_BuildC800Mode1/2/4 fill: the first MVN
; copies the 32 zero bytes at GfxRom_D2 to its start, and each later
; MVN copies the zeroed part ($C800..$C800+n-1) to the n bytes right
; after it (adjacent, not overlapping; X restarts at the buffer start
; each time, n = 32 up to 1,024), so the cleared size doubles from 64
; up to 2,048 bytes.
; Callers (2 JSR sites): Field_ServiceUnk54 ($C0:2787) and Evt_Op29_StartCredits ($C0:3E96).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DB any (saved); DP not
; used.
; Exit: M=1, X=0, DB unchanged (PHB/PLB around the MVNs, which set it
; to $7E); A = $FFFF (the last MVN's count ran out; B = $FF), X =
; $CC00, Y = $D000.
; ============================================================
org $C075A0
Map_ClearBufC800:
    REP #$20
    PHB
    LDX.w #!GfxRom_D2&$FFFF
    LDY.w #!Map_BufC800&$FFFF
    LDA.w #!Map_ZeroChunk-1
    MVN !Bank7E,!BankD2         ; 32 zeros -> $7E:C800  lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    LDX.w #!Map_BufC800&$FFFF
    LDA.w #!Map_ZeroChunk-1
    MVN !Bank7E,!Bank7E         ; $C800-$C81F -> $C820 (64 zeroed)  lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    LDX.w #!Map_BufC800&$FFFF
    LDA.w #!Map_ZeroChunk*2-1
    MVN !Bank7E,!Bank7E         ; 128 zeroed  lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    LDX.w #!Map_BufC800&$FFFF
    LDA.w #!Map_ZeroChunk*4-1
    MVN !Bank7E,!Bank7E         ; 256 zeroed  lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    LDX.w #!Map_BufC800&$FFFF
    LDA.w #!Map_ZeroChunk*8-1
    MVN !Bank7E,!Bank7E         ; 512 zeroed  lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    LDX.w #!Map_BufC800&$FFFF
    LDA.w #!Map_ZeroChunk*16-1
    MVN !Bank7E,!Bank7E         ; 1,024 zeroed  lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    LDX.w #!Map_BufC800&$FFFF
    LDA.w #!Map_ZeroChunk*32-1
    MVN !Bank7E,!Bank7E         ; 2,048 zeroed  lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    PLB
    SEP #$20
    RTS

; ============================================================
; Map layer redraws, row / column writers and edge VRAM addresses
; ($C0:75E9–$C0:8242)
; The map sits in WRAM as metatile numbers. Each 256-byte row of
; $7E:3000 holds layer 1 at +$00 (Map_TileProps), layer 2 at +$40
; (Map_Layer2Tiles), layer 3 at +$80 (Map_Layer3Tiles) and at +$C0 the
; high bits (Map_TileHiBits: bit 0 / bit 1 = bit 8 of the layer-1 /
; layer-2 number), inferred from the writers' reads. A 16x16 metatile is
; 8 bytes in Map_Meta12* (layers 1 and 2) or Map_Meta3* (layer 3): four
; tilemap words, top-left, top-right, bottom-left, bottom-right
; (inferred from which words a top / bottom and left / right half
; write). The six writers turn a run of the map into tilemap words and
; send them to WMDATA. The redraws Field_BuildC800Mode1/2/4 write a
; whole screen into Map_BufC800; the edge builders (Map_Build*, after
; this block) write one row or column into a layer's edge buffer.
; Map_UploadBuf* send Map_BufC800 to VRAM, and Sub_C07F9A with the
; Bg_*Span64x32 helpers computes the tilemap VRAM addresses of the
; edges. Layers 1-3 as in ram_engine.inc's map page notes.
; ============================================================
org $C075E9
; ------------------------------------------------------------
; $C0:75E9 — Field_BuildC800Mode1 (41 bytes, $75E9–$7611)
; Redraws layer 1 into Map_BufC800: points WMADD at $7E:C800 and writes
;   32 rows (Map_RedrawRows) of 16 metatiles (Map_RedrawLen: 32 tilemap
;   words, 64 bytes) with Map_WriteRow1, from row Map_TileOriginY and
;   column Map_TileOriginX: 2,048 bytes, the whole buffer.
; Callers (6 JSR sites): LocLoad_DrawMap ($C0:0A96), DefaultHandler ($C0:17A9, $C0:17FE, $C0:183E),
;   Field_HookLeaveToBankC3 ($C0:2617) and Field_HookWinPulse ($C0:2658).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$1D00 (!DP_Map), DB=$00
;   (WMADDL/H here and WMDATA in Map_WriteRow1 are written absolute).
; Exit: M=1, X=0, DP and DB unchanged; Map_RowsLeft = 0, Map_BuildRow
;   advanced by 32, Map_BuildLen = 0; A, X, Map_WrCol and Map_WrRow
;   clobbered by Map_WriteRow1; Y unchanged.
; ------------------------------------------------------------
Field_BuildC800Mode1:
    REP #$20
    LDA.w #!Map_BufC800&$FFFF
    STA.w WMADDL
    SEP #$20
    LDA.b #$00
    STA.w WMADDH
    LDA.b !Map_TileOriginY-!DP_Map
    STA.b !Map_BuildRow-!DP_Map
    LDA.b #!Map_RedrawRows
    STA.b !Map_RowsLeft-!DP_Map
.row_loop:
    LDA.b !Map_TileOriginX-!DP_Map
    STA.b !Map_BuildCol-!DP_Map
    LDA.b #!Map_RedrawLen
    STA.b !Map_BuildLen-!DP_Map
    JSR Map_WriteRow1
    INC.b !Map_BuildRow-!DP_Map
    DEC.b !Map_RowsLeft-!DP_Map
    BNE .row_loop
    RTS

; ------------------------------------------------------------
; $C0:7612 — Map_WriteRow1 (466 bytes, $7612–$77E3)
; Writes one row of layer-1 tilemap words to WMDATA (WRAM at WMADD).
;   Arguments in 8x8-tile units: Map_BuildRow (bit 0, Map_HalfTileBit,
;   picks the top or bottom half of metatile row Map_BuildRow / 2),
;   Map_BuildCol (bit 0 set: start with a right half) and Map_BuildLen in
;   metatiles. The metatile row and column are ANDed with Map_RowMask1 /
;   Map_ColMask1, the column again at every step (so it wraps). Each
;   metatile's 9-bit number (Map_TileProps, bit 8 from Map_TileHiBits
;   bit 0) times 8 indexes Map_Meta12*; a top half writes its TL and TR
;   words, a bottom half BL and BR.
;   An even start writes Map_BuildLen whole metatiles. An odd start
;   writes the right word of the first metatile, Map_BuildLen - 1 whole
;   ones, and then one more word, again a right word (TR / BR) of the
;   next metatile where a left one would continue the row. Kept as is:
;   both give 2 x Map_BuildLen words, and the edge rows start one column
;   left of the screen, so that word probably lands off-screen (not
;   traced).
; Quirk: on an odd start the count is decremented once before the loop
;   tests it, so Map_BuildLen = 1 would run 256 more metatiles; callers
;   pass Map_RedrawLen or Map_EdgeRowLen.
; Callers (3 JSR sites): Field_BuildC800Mode1 ($C0:7608), Map_BuildRowYInc1 ($C0:825B) and
;   Map_BuildRowYDec1 ($C0:82DD).
; On entry: M=1 (8-bit A), X=0 (16-bit X: the map index row << 8 |
;   column, then the Map_Meta12* offset), DP=$1D00 (!DP_Map), DB=$00
;   (WMDATA written absolute).
; Exit: M=1, X=0, DP and DB unchanged; Map_BuildLen = 0; Map_WrRow =
;   the masked metatile row, Map_WrCol = the last or next metatile
;   column; A and X clobbered; Y unchanged; WMADD advanced past the
;   words written.
; ------------------------------------------------------------
Map_WriteRow1:
    LDA.b !Map_BuildRow-!DP_Map
    BIT.b #!Map_HalfTileBit
    BEQ .top_half
    BRL .bottom_half
.top_half:
    LSR A
    AND.b !Map_RowMask1-!DP_Map
    STA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_BuildCol-!DP_Map
    BIT.b #!Map_HalfTileBit
    BNE .top_odd
    LSR A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
.top_even_loop:
    TAX
    LDA.l !Map_TileHiBits,X
    AND.b #$01
    XBA
    LDA.l !Map_TileProps,X
    REP #$20
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta12TL,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
    LDA.l !Map_Meta12TR,X
    STA.w WMDATA
    LDA.l !Map_Meta12TR+1,X
    STA.w WMDATA
    LDA.b !Map_WrCol-!DP_Map
    INC A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
    DEC.b !Map_BuildLen-!DP_Map
    BEQ .top_done
    LDA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    BRA .top_even_loop
.top_done:
    RTS
.top_odd:
    LSR A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
    TAX
    LDA.l !Map_TileHiBits,X
    AND.b #$01
    XBA
    LDA.l !Map_TileProps,X
    REP #$20
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta12TR,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
    DEC.b !Map_BuildLen-!DP_Map
    LDA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    INC A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
.top_odd_loop:
    TAX
    LDA.l !Map_TileHiBits,X
    AND.b #$01
    XBA
    LDA.l !Map_TileProps,X
    REP #$20
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta12TL,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
    LDA.l !Map_Meta12TR,X
    STA.w WMDATA
    LDA.l !Map_Meta12TR+1,X
    STA.w WMDATA
    LDA.b !Map_WrCol-!DP_Map
    INC A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
    DEC.b !Map_BuildLen-!DP_Map
    BEQ .top_odd_last
    LDA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    BRA .top_odd_loop
.top_odd_last:
    LDA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    TAX
    LDA.l !Map_TileHiBits,X
    AND.b #$01
    XBA
    LDA.l !Map_TileProps,X
    REP #$20
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta12TR,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
.done:
    RTS
.bottom_half:
    LSR A
    AND.b !Map_RowMask1-!DP_Map
    STA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_BuildCol-!DP_Map
    BIT.b #!Map_HalfTileBit
    BNE .bottom_odd
    LSR A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
.bottom_even_loop:
    TAX
    LDA.l !Map_TileHiBits,X
    AND.b #$01
    XBA
    LDA.l !Map_TileProps,X
    REP #$20
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta12BL,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
    LDA.l !Map_Meta12BR,X
    STA.w WMDATA
    LDA.l !Map_Meta12BR+1,X
    STA.w WMDATA
    LDA.b !Map_WrCol-!DP_Map
    INC A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
    DEC.b !Map_BuildLen-!DP_Map
    BEQ .done
    LDA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    BRA .bottom_even_loop
.bottom_odd:
    LSR A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
    TAX
    LDA.l !Map_TileHiBits,X
    AND.b #$01
    XBA
    LDA.l !Map_TileProps,X
    REP #$20
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta12BR,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
    DEC.b !Map_BuildLen-!DP_Map
    LDA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    INC A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
.bottom_odd_loop:
    TAX
    LDA.l !Map_TileHiBits,X
    AND.b #$01
    XBA
    LDA.l !Map_TileProps,X
    REP #$20
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta12BL,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
    LDA.l !Map_Meta12BR,X
    STA.w WMDATA
    LDA.l !Map_Meta12BR+1,X
    STA.w WMDATA
    LDA.b !Map_WrCol-!DP_Map
    INC A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
    DEC.b !Map_BuildLen-!DP_Map
    BEQ .bottom_odd_last
    LDA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    BRA .bottom_odd_loop
.bottom_odd_last:
    LDA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    TAX
    LDA.l !Map_TileHiBits,X
    AND.b #$01
    XBA
    LDA.l !Map_TileProps,X
    REP #$20
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta12BR,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
    RTS

; ------------------------------------------------------------
; $C0:77E4 — Map_WriteCol1 (264 bytes, $77E4–$78EB)
; Writes one column of layer-1 tilemap words to WMDATA, top to bottom.
;   Map_BuildCol bit 0 picks the left words (TL, BL) or the right ones
;   (TR, BR) of metatile column Map_BuildCol / 2; Map_BuildRow is the
;   first 8x8 row and Map_BuildLen counts metatiles. Each step writes a
;   metatile's top and bottom word and moves one metatile row down (ANDed
;   with Map_RowMask1, so it wraps). An odd first row writes the bottom
;   word of the first metatile alone and then Map_BuildLen whole ones:
;   2 x Map_BuildLen + 1 words, against 2 x Map_BuildLen for an even
;   start. Lookup as Map_WriteRow1 (Map_TileProps, Map_TileHiBits bit 0,
;   Map_Meta12*).
; Callers (2 JSR sites): Map_BuildColXInc1 ($C0:835D) and Map_BuildColXDec1 ($C0:83DD).
; On entry: M=1 (8-bit A), X=0 (16-bit X), DP=$1D00 (!DP_Map), DB=$00
;   (WMDATA written absolute).
; Exit: M=1, X=0, DP and DB unchanged; Map_BuildLen = 0; Map_WrCol =
;   the masked metatile column, Map_WrRow = the last metatile row; A and
;   X clobbered; Y unchanged; WMADD advanced past the words written.
; ------------------------------------------------------------
Map_WriteCol1:
    LDA.b !Map_BuildRow-!DP_Map
    BIT.b #!Map_HalfTileBit
    BEQ .even_row
    BRL .odd_row
.even_row:
    LSR A
    AND.b !Map_RowMask1-!DP_Map
    STA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_BuildCol-!DP_Map
    BIT.b #!Map_HalfTileBit
    BNE .right_start
    LSR A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
.left_loop:
    TAX
    LDA.l !Map_TileHiBits,X
    AND.b #$01
    XBA
    LDA.l !Map_TileProps,X
    REP #$20
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta12TL,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
    LDA.l !Map_Meta12BL,X
    STA.w WMDATA
    LDA.l !Map_Meta12BL+1,X
    STA.w WMDATA
    LDA.b !Map_WrRow-!DP_Map
    DEC.b !Map_BuildLen-!DP_Map
    BEQ .done
    INC A
    AND.b !Map_RowMask1-!DP_Map
    STA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    BRA .left_loop
.right_start:
    LSR A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
.right_loop:
    TAX
    LDA.l !Map_TileHiBits,X
    AND.b #$01
    XBA
    LDA.l !Map_TileProps,X
    REP #$20
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta12TR,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
    LDA.l !Map_Meta12BR,X
    STA.w WMDATA
    LDA.l !Map_Meta12BR+1,X
    STA.w WMDATA
    LDA.b !Map_WrRow-!DP_Map
    DEC.b !Map_BuildLen-!DP_Map
    BEQ .done
    INC A
    AND.b !Map_RowMask1-!DP_Map
    STA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    BRA .right_loop
.done:
    RTS
.odd_row:
    LSR A
    AND.b !Map_RowMask1-!DP_Map
    STA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_BuildCol-!DP_Map
    BIT.b #!Map_HalfTileBit
    BNE .odd_row_right
    LSR A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
    TAX
    LDA.l !Map_TileHiBits,X
    AND.b #$01
    XBA
    LDA.l !Map_TileProps,X
    REP #$20
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta12BL,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
    LDA.b !Map_WrRow-!DP_Map
    INC A
    AND.b !Map_RowMask1-!DP_Map
    STA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    BRL .left_loop
.odd_row_right:
    LSR A
    AND.b !Map_ColMask1-!DP_Map
    STA.b !Map_WrCol-!DP_Map
    TAX
    LDA.l !Map_TileHiBits,X
    AND.b #$01
    XBA
    LDA.l !Map_TileProps,X
    REP #$20
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta12BR,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
    LDA.b !Map_WrRow-!DP_Map
    INC A
    AND.b !Map_RowMask1-!DP_Map
    STA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    BRL .right_loop

; ------------------------------------------------------------
; $C0:78EC — Field_BuildC800Mode2 (227 bytes, $78EC–$79CE)
; Redraws layer 2 into Map_BufC800 (WMADD = $7E:C800) with
;   Map_WriteRow2, 16 metatiles (Map_RedrawLen) per row, one of three ways:
;   - Map_LayerEdgeOff bit 1 clear, Map_Unk0BC9 bit 7 clear: as
;     Field_BuildC800Mode1 (32 rows from Map_TileOriginY, column
;     Map_TileOriginX: layer 1's origin, as the normal-rate builders).
;   - bit 1 clear, Map_Unk0BC9 bit 7 set (half-rate layer 2): rows
;     Map_Unk1D16 through Map_Unk1D18 from column Map_Unk1D12.
;   - Map_LayerEdgeOff bit 1 set (no edge builds for the layer): a fixed
;     map from row 0, column 0. Rows 0-31 (2 KB), then a second 2 KB:
;     columns 32-63 when Map_Unk0BCF is not 16 (Map_ScreenMetatiles),
;     else rows 32-63 when Map_Unk0BD1 is not 16 (and the high byte of
;     Map_TilemapVram4 set to 2), else rows 0-31 again. The second block
;     runs past $7E:CFFF into Map_BufD000's space; $C0:0ABB then uploads
;     4 KB (Map_UploadBuf4K) when the bit is set.
; Quirk: the two layer-2-moving paths start with a REP #$20 that the
;   SEP #$20 after the branch undoes at once; kept.
; Callers (3 JSR sites): LocLoad_DrawMap ($C0:0AAB) and DefaultHandler ($C0:17D2, $C0:1817).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$1D00 (!DP_Map), DB=$00
;   (Map_LayerEdgeOff, Map_Unk0BC9, Map_Unk0BCF/0BD1, WMADD and WMDATA
;   are absolute).
; Exit: M=1, X=0, DP and DB unchanged; Map_BuildCol/Row/Len, A, X,
;   Map_WrCol and Map_WrRow clobbered (Map_RowsLeft = 0 on the first
;   path); Y unchanged.
; ------------------------------------------------------------
Field_BuildC800Mode2:
    REP #$20
    LDA.w #!Map_BufC800&$FFFF
    STA.w WMADDL
    SEP #$20
    LDA.b #$00
    STA.w WMADDH
    LDA.w !Map_LayerEdgeOff
    BIT.b #!Map_Layer2
    BEQ .not_edge_off
    BRL .edge_off
.not_edge_off:
    LDA.w !Map_Unk0BC9
    BMI .half_rate
    REP #$20
    BRA .normal_rate
.half_rate:
    REP #$20
    BRL .half_rate_rows
