    STA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_WrCol-!DP_Map
    BRA .left_loop
.right_start:
    LSR A
    AND.b !Map_ColMask3-!DP_Map
    STA.b !Map_WrCol-!DP_Map
.right_loop:
    TAX
    LDA.l !Map_Layer3Tiles,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    ASL A
    ASL A
    TAX
    LDA.l !Map_Meta3TR,X
    SEP #$20
    STA.w WMDATA
    XBA
    STA.w WMDATA
    LDA.l !Map_Meta3BR,X
    STA.w WMDATA
    LDA.l !Map_Meta3BR+1,X
