    BRA .right_loop
.done:
    RTS
.odd_row:
    LSR A
    AND.b !Map_RowMask3-!DP_Map
    STA.b !Map_WrRow-!DP_Map
    XBA
    LDA.b !Map_BuildCol-!DP_Map
    BIT.b #!Map_HalfTileBit
    BNE .odd_row_right
    LSR A
    AND.b !Map_ColMask3-!DP_Map
