    LDX.b !Map_EdgeSize3-!DP_Map
    BEQ .piece2
    REP #$20
    LDA.b !Map_EdgeSize3-!DP_Map
    STA.w DAS7L
    SEP #$20
    LDX.b !Map_EdgeVram3-!DP_Map
    STX.w VMADDL
    LDX.w #!Map_BufD800&$FFFF
    STX.w A1T7L
    JSR Map_EdgeDmaRow
.piece2:
