    LDA.b #!DMAP_TwoRegs
    STA.w DMAP7
    LDA.b #!BBAD_VMDATAL
    STA.w BBAD7
    LDA.b #!Bank7E
    STA.w A1B7
    LDA.b #!MDMAEN_Ch7
    STA.w MDMAEN
    RTS

