Evt_Op98_WalkTowardObj:
    LDX.b !Obj_Cur
    LDA.w !Obj_Unk1A80,X
    BEQ .aim
    LDA.w !Obj_MoveFrames,X
    BEQ .arrived
    TYX
    CLC
    RTS
.arrived:
    STZ.w !Obj_Unk1A80,X
    TYX
    INX
    INX
    INX
    SEC
    RTS
.aim:
    TYX
    INX
    TDC
    XBA
    LDA.l !Evt_Data,X
