    STA.b !ObjDir_ToX
    LDA.w !Obj_TileY,X
    STA.b !ObjDir_ToY
    STX.b !ObjFront_Other
    LDX.b !Obj_Cur
    LDA.w !Obj_TileX,X
    STA.b !ObjDir_FromX
    LDA.w !Obj_TileY,X
    STA.b !ObjDir_FromY
    CMP.b !ObjDir_ToY
    BEQ .near_y
    INC A
    CMP.b !ObjDir_ToY
    BEQ .near_y
    DEC A
    DEC A
    CMP.b !ObjDir_ToY
    BNE .step
.near_y:
    LDA.b !ObjDir_FromX
