    INX
    INX
    LDA.l !Evt_Data,X
    LDX.b !Obj_Cur
    STA.w !Obj_MoveFrames,X
    STA.l !ObjX_Unk7F0B00,X
    INC.w !Obj_Unk1A80,X
    STY.b !ObjFront_SavedY
    JSR Obj_SetVelocityChecked
    JSR Obj_SetMoveAnim
    LDX.b !ObjFront_SavedY
    CLC
    RTS

