    STX.b !EvtFace_Target
    LDX.b !Obj_Cur
    LDA.w !Obj_TileX,X
    STA.b !ObjDir_FromX
    LDA.w !Obj_TileY,X
    STA.b !ObjDir_FromY
    CMP.b !ObjDir_ToY
    BNE .aim
    LDA.b !ObjDir_FromX
    CMP.b !ObjDir_ToX
    BNE .aim
    LDA.w !Obj_PosX,X
    STA.b !ObjDir_FromX
    LDA.w !Obj_PosY,X
    STA.b !ObjDir_FromY
    LDX.b !EvtFace_Target
    LDA.w !Obj_PosX,X
    STA.b !ObjDir_ToX
    LDA.w !Obj_PosY,X
    STA.b !ObjDir_ToY
.aim:
    JSR Obj_CalcDirection
    REP #$20
    LDA.b !Obj_Direction
    TAX
    SEP #$20
    LDA.w !Rom_DirToFacing,X
    LDX.b !Obj_Cur
    STA.w !Obj_Facing,X
    STZ.w !Obj_AnimTimer,X
    TYX
    INX
    INX
    CLC
    RTS
.skip:
    TYX
    INX
    INX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:5605 — Evt_OpA9_FacePc (15 bytes, $5605–$5613)
; Event opcode $A9 (2 bytes: $A9, p): Evt_OpA8_FaceObj toward a party
;   member's object (X = Party_ObjSlot + p, p = 0, 2 or 4) through
;   Evt_OpA8_Body.
; Reached through Evt_OpcodeTable (opcode $A9).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur and the
;   scratch below are dp), DB=$00 (Obj_* tables absolute); Y = the
;   opcode's offset in Evt_Data (operands read long at Evt_Data + Y + n).
; Exit: as Evt_OpA8_FaceObj.
; ------------------------------------------------------------
Evt_OpA9_FacePc:
    TYX
    INX
    TDC
    XBA
    LDA.l !Evt_Data,X
    TAX
    LDA.b !Party_ObjSlot,X
    TAX
    BRL Evt_OpA8_Body

; ------------------------------------------------------------
; $C0:5614 — Obj_SetMoveAnim (119 bytes, $5614–$568A)
; Picks Obj_Cur's animation row from its speed. Only in Obj_AnimMode 0;
;   in Obj_AnimModeFixed (3) it first leaves that mode: to mode 1 (and
;   stops there) unless Obj_AnimRow is $FF, then to mode 0; modes 1 and 2
;   are left alone. With s = |Obj_VelX| + |Obj_VelY| (low bytes): s = 0
;   row ObjAnim_RowStand (0); s below ObjAnim_RunSpeed ($20) row
;   ObjAnim_RowWalk (1); s at or above it row ObjAnim_RowRun (6) when
;   Obj_Unk1100 is below ObjAnim_RunKinds (4), else row 1. A row is set
;   only when it differs, with Obj_AnimColumn and Obj_AnimTimer = 0.
;   (Rows read as stand / walk / run from this use; not checked against
;   the frames.)
; Callers (13 JSR sites): Evt_Op92_WalkDir ($C0:4EC0), Evt_Op96_WalkToTile ($C0:4FA5, $C0:4FE3),
;   Evt_Op9A_WalkTowardTile ($C0:5037, $C0:507D), Evt_Op97_WalkToTileVar ($C0:50E4, $C0:5122),
;   Evt_Op94_Body ($C0:527B, $C0:52B9), Evt_Op98_Body ($C0:53C4, $C0:5409) and Evt_Op8F_FollowPc
;   ($C0:54B0, $C0:54EE).
; Callers note: Evt_Op8F_FollowPc's $C0:54B0 is in its unreached bytes.
; On entry: M=1 (8-bit A), X=0 (16-bit X), DP=$0100 (Obj_Cur,
;   Eng_Scratch), DB=$00 (Obj_* tables absolute).
; Exit: M=1, X=0, DP and DB unchanged; A clobbered, X = Obj_Cur, Y
;   unchanged; Eng_Scratch ($D9) written in mode 0.
; ------------------------------------------------------------
Obj_SetMoveAnim:
    LDX.b !Obj_Cur
    LDA.w !Obj_AnimMode,X
    BEQ .by_speed
    CMP.b #!Obj_AnimModeFixed
    BEQ .fixed
    RTS
.fixed:
    LDA.w !Obj_AnimRow,X
    CMP.b #!Anim_EndMarker
    BEQ .to_mode0
    LDA.b #!Obj_AnimModeNormal
    STA.w !Obj_AnimMode,X
    RTS
.to_mode0:
    STZ.w !Obj_AnimMode,X
.by_speed:
    LDA.w !Obj_VelX,X
    BPL .x_abs
    EOR.b #!Eng_Invert8
    INC A
.x_abs:
    STA.b !Eng_Scratch
    LDA.w !Obj_VelY,X
    BPL .y_abs
    EOR.b #!Eng_Invert8
    INC A
.y_abs:
    CLC
    ADC.b !Eng_Scratch
    BEQ .stand
    CMP.b #!ObjAnim_RunSpeed
    BCS .fast
.walk:
    LDA.w !Obj_AnimRow,X
    CMP.b #!ObjAnim_RowWalk
    BEQ .done
    LDA.b #!ObjAnim_RowWalk
    STA.w !Obj_AnimRow,X
    STZ.w !Obj_AnimColumn,X
    STZ.w !Obj_AnimTimer,X
    RTS
.stand:
    LDA.w !Obj_AnimRow,X
    CMP.b #!ObjAnim_RowStand
    BEQ .done
    LDA.b #!ObjAnim_RowStand
    STA.w !Obj_AnimRow,X
    STZ.w !Obj_AnimColumn,X
    STZ.w !Obj_AnimTimer,X
.done:
    RTS
.fast:
    LDA.w !Obj_Unk1100,X
    CMP.b #!ObjAnim_RunKinds
    BCS .walk
    LDA.w !Obj_AnimRow,X
    CMP.b #!ObjAnim_RowRun
    BEQ .done
    LDA.b #!ObjAnim_RowRun
    STA.w !Obj_AnimRow,X
    STZ.w !Obj_AnimColumn,X
    STZ.w !Obj_AnimTimer,X
    RTS

; ------------------------------------------------------------
; $C0:568B — Obj_SetStandAnim (27 bytes, $568B–$56A5)
; In Obj_AnimMode 0 only: Obj_Cur's Obj_AnimRow = ObjAnim_RowStand (0)
;   unless it already is, with Obj_AnimColumn and Obj_AnimTimer = 0.
; Callers (7 JSR sites): Evt_Op92_WalkDir ($C0:4E85), Evt_Op96_WalkToTile ($C0:4F9C),
;   Evt_Op9A_WalkTowardTile ($C0:502D), Evt_Op97_WalkToTileVar ($C0:50DB), Evt_Op94_Body ($C0:5273),
;   Evt_Op98_Body ($C0:53BB) and Evt_Op8F_FollowPc ($C0:54A8).
; On entry: M=1 (8-bit A), X=0 (16-bit X), DP=$0100 (Obj_Cur), DB=$00
;   (Obj_* tables absolute).
; Exit: M=1, X=0, DP and DB unchanged; A clobbered, X = Obj_Cur, Y
;   unchanged.
; ------------------------------------------------------------
Obj_SetStandAnim:
    LDX.b !Obj_Cur
    LDA.w !Obj_AnimMode,X
    BEQ .mode0
    RTS
.mode0:
    LDA.w !Obj_AnimRow,X
    CMP.b #!ObjAnim_RowStand
    BEQ .done
    LDA.b #!ObjAnim_RowStand
    STA.w !Obj_AnimRow,X
    STZ.w !Obj_AnimColumn,X
    STZ.w !Obj_AnimTimer,X
.done:
    RTS


; ============================================================
; Location objects and event data at a location load ($C0:56A6-
; $C0:595B, $C0:5CC7-$C0:5D6D): LocLoad_Unk56D4 unpacks the location's
; event data to Evt_ObjCount/Evt_Data ($7F:2000), checks it and seeds
; Map_Unk7F3700; Scene_PostLoadInit later resets the object tables and
; runs every object's init function (Evt_InitObjects).
; ============================================================

; ------------------------------------------------------------
; $C0:56A6 — Scene_PostLoadInit (46 bytes, $56A6–$56D3)
; The object side of a location load, run once by GameLoop_LoadField
; after LoadLocation: ObjQ_Unk69 = $0048, ObjQ_ScanlineLimit = $0078,
; VramQ_Valid = 0 (empty VRAM queue); then Field_ResetUnk0B88,
; Field_ResetUnk0B80, SprBuf_FreeAll, Evt_ClearUnk0920,
; Obj_ResetDrawLists, Obj_ResetFrameState,
; Evt_InitObjects (object tables and init functions; it ends with
; Map_InitEntryTile) and Evt_RunObj0Func1 (object 0's function 1); and
; last BankC2_Entry8004 with A = BankC2_PostLoadArg ($0B; B = 0 from
; TDC/XBA), a bank-$C2 command that is not traced.
; Callers (1 JSR site): GameLoop_LoadField ($C0:008E).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100, DB=$00
; (VramQ_Valid absolute; the callees assume the same).
; Exit: M=1, X=0, DP=$0100 and DB=$00 unchanged as far as is known
; (the bank-$C2 command is not matched); A, X, Y clobbered, Obj_Cur and
; what the callees change.
; ------------------------------------------------------------
org $C056A6
Scene_PostLoadInit:
    LDX.w #!ObjQ_Unk69Init
    STX.b !ObjQ_Unk69
    LDX.w #!ObjQ_ScanlineInit
    STX.b !ObjQ_ScanlineLimit
    STZ.w !VramQ_Valid
    JSR Field_ResetUnk0B88
    JSR Field_ResetUnk0B80
    JSR SprBuf_FreeAll
    JSR Evt_ClearUnk0920
    JSR Obj_ResetDrawLists
    JSR Obj_ResetFrameState
    JSR Evt_InitObjects
    JSR Evt_RunObj0Func1
    TDC                                 ; C = D = $0100
    XBA                                 ; B = 0 for the command word
    LDA.b #!BankC2_PostLoadArg
    JSL BankC2_Entry8004
    RTS

; ------------------------------------------------------------
; $C0:56D4 — LocLoad_Unk56D4 (53 bytes, $56D4–$5708)
; The last location-load step: unpacks the location's event data. The
; Evt_PackPtrs entry LocRom.Events is unpacked with Decomp_ToWramVec to
; $7F:2000 (Evt_ObjCount, then Evt_Data); LocLoad_CheckEvtData stops
; the game on two bad cases, and the tail jump to LocLoad_InitUnk7F3700
; seeds Map_Unk7F3700 from ROM. (Called as LocLoad_Unk56D4 by verified
; code, so the name stays.)
; Callers (3 JSR sites): LoadLocation ($C0:010F), Field_RestoreState ($C0:01D8) and Scene_Unk0283
;   ($C0:032D).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Loc_RecOfs,
; Eng_Scratch), DB=$00 (the Decomp_* block absolute).
; Exit (through LocLoad_InitUnk7F3700): M=1, X=0, DP and DB unchanged;
; A, X and Y clobbered; Eng_Scratch and the Decomp_* block written.
; ------------------------------------------------------------
LocLoad_Unk56D4:
    REP #$20
    LDX.b !Loc_RecOfs
    LDA.l LocRom.Events,X
    STA.b !Eng_Scratch
    CLC
    ADC.b !Eng_Scratch
    ADC.b !Eng_Scratch                  ; x Evt_PackPtrSize
    TAX
    LDA.l !Evt_PackPtrs,X
    STA.w !Decomp_Src
    LDA.w #!Evt_ObjCount&$FFFF
    STA.w !Decomp_Dest
    SEP #$20
    LDA.l !Evt_PackPtrs+2,X
    STA.w !Decomp_SrcBank
    LDA.b #!Bank7F
    STA.w !Decomp_DestBank
    JSL Decomp_ToWramVec
    JSR LocLoad_CheckEvtData
    BRL LocLoad_InitUnk7F3700

; ------------------------------------------------------------
; $C0:5709 — Evt_InitObjects (544 bytes, $5709–$5928)
; Resets the object tables for the Evt_ObjCount objects of the new
; location and runs each one's init function:
; 1. Clears $7F:0200-$7F:03FF (Evt_Unk7F0200, with ClearRAMDMA; it
;    starts with Treasure_ItemId).
; 2. With DP=$2100, fills per-object tables through the WRAM port
;    (WMADD/WMDATA), one byte pair per object for Evt_ObjCount objects:
;    Obj_ScriptPos = the object's function 0 (init) offset (word 0 of
;    each Evt_FuncTableBytes block of Evt_Data); Obj_Unk1C00/1C01 =
;    Obj_Unk1C00Init/0; Obj_Unk1000/1001 = Obj_Unk1000Init/0;
;    Obj_Unk1080/Obj_QueueNext = ObjQ_Empty; Obj_Unk1100 = $80/$00 for
;    63 slots, then Obj_Unk1100Seven/0 for the objects; Obj_PosX and
;    Obj_PosY = Obj_PosOffMap ($FF00); Obj_Unk1A00/1A01 =
;    Obj_Unk1A00Init/0; Obj_Unk1A80/1A81 = 0/1; Obj_AnimMode/AnimRowAlt
;    = 0/0; Obj_Unk1C80/1C81 = Obj_Unk1C80Init/0; Obj_OamFlags/OamAttr
;    = $80/0; ObjX_Unk7F0B00 / ObjX_AnimLoops = 0/0 and ObjX_Unk7F0B80
;    = $FF/$FF (both in bank $7F).
; 3. Clears Obj_Unk1900 (a page) and $7F:0580-$7F:1B3F (ObjX_Unk7F0580
;    on). That second clear covers $7F:0B00-$7F:0BFF too, so the
;    ObjX_Unk7F0B00/AnimLoops/7F0B80 fills of step 2 are wiped right
;    away; kept as found.
; 4. ObjQ_Unk74/75, ObjQ_Head/Tail = ObjQ_Empty, ObjQ_Unk71 = $8000,
;    ObjQ_Unk73 = 0, Evt_ObjSlotEnd = Evt_ObjCount x 2.
; 5. For each object slot: Obj_Unk1B01 = Obj_Unk1B80 = 0; unless
;    the word at Obj_Unk1100 is negative, runs its opcodes from
;    Obj_ScriptPos through Evt_OpcodeTable up to opcode $00 (as
;    Evt_RunObjInit does) with Obj_Cur = the slot, and leaves
;    Obj_ScriptPos past that $00. A is 16-bit in this loop, so the
;    skip test reads bit 7 of the byte after Obj_Unk1100, which step 2
;    zeroed for every object: no object is skipped. The 16-bit STZ of
;    Obj_Unk1B01 also clears the next slot's Obj_State byte.
; 6. Tail jump to Map_InitEntryTile.
; The LDA #$00 before the first loop is overwritten at once; the CLC
; before it holds for the loop's ADC because the CPX that ends each
; pass leaves C clear while the loop goes on.
; Callers (1 JSR site): Scene_PostLoadInit ($C0:56C5).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (DmaFill_*,
; Eng_Scratch, Obj_Cur, the queue bytes), DB=$00 (the per-object tables
; and Eng_Scratch through DP_Field are absolute).
; Exit (through Map_InitEntryTile): M=1, X=0, DP and DB unchanged; A, X,
; Y clobbered; Obj_Cur = the last slot run, and whatever the opcode
; handlers and Map_InitEntryTile change.
; ------------------------------------------------------------
Evt_InitObjects:
    LDX.w #!Evt_Unk7F0200Bytes
    STX.b !DmaFill_Size
    LDX.w #!Evt_Unk7F0200&$FFFF
    STX.b !DmaFill_Dest
    LDA.b #!Bank7F
    STA.b !DmaFill_Bank
    JSR ClearRAMDMA
    PHD
    LDA.l !Evt_ObjCount
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    ASL A
    ASL A
    ASL A
    ASL A                               ; x Evt_FuncTableBytes
    STA.b !Eng_Scratch                  ; end of the function tables
    LDA.w #!DP_PPU
    TCD
    SEP #$20
    LDX.w #!Obj_ScriptPos
    STX.b WMADDL-!DP_PPU
    LDA.b #$00                          ; WRAM bank $7E
    STA.b WMADDH-!DP_PPU
    CLC
    LDA.b #$00                          ; overwritten below
    LDX.w #$0000                        ; offset of object 0's function table
.script_loop:
    LDA.l !Evt_Data,X
    STA.b WMDATA-!DP_PPU
    LDA.l !Evt_Data+1,X
    STA.b WMDATA-!DP_PPU                ; Obj_ScriptPos = function 0
    REP #$20
    TXA
    ADC.w #!Evt_FuncTableBytes
    TAX
    SEP #$20
    CPX.w !DP_Field+!Eng_Scratch
    BMI .script_loop
    LDX.w #!Obj_Unk1C00
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
    LDX.b #!Obj_Unk1C00Init
    LDY.b #$00
.fill_1c00:
    STX.b WMDATA-!DP_PPU
    STY.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_1c00
    REP #$10
    LDX.w #!Obj_Unk1000
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
.fill_1000:
    LDX.b #!Obj_Unk1000Init
    STX.b WMDATA-!DP_PPU
    LDX.b #$00
    STX.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_1000
    REP #$10
    LDX.w #!Obj_Unk1080
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
.fill_1080:
    LDX.b #!ObjQ_Empty
    STX.b WMDATA-!DP_PPU                ; Obj_Unk1080
    STX.b WMDATA-!DP_PPU                ; Obj_QueueNext
    DEC A
    BNE .fill_1080
    REP #$10
    LDX.w #!Obj_Unk1100
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.b #!Obj_Unk1100SkipSlots
    LDX.b #!Obj_Unk1100Skip
    LDY.b #$00
.fill_1100_skip:
    STX.b WMDATA-!DP_PPU
    STY.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_1100_skip
    REP #$10
    LDX.w #!Obj_Unk1100
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
    LDX.b #!Obj_Unk1100Seven
    LDY.b #$00
.fill_1100:
    STX.b WMDATA-!DP_PPU
    STY.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_1100
    REP #$10
    LDX.w #!Obj_PosX
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
    LDX.b #!Obj_PosOffMap&$FF
    LDY.b #!Obj_PosOffMap>>8
.fill_posx:
    STX.b WMDATA-!DP_PPU
    STY.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_posx
    REP #$10
    LDX.w #!Obj_PosY
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
    LDX.b #!Obj_PosOffMap&$FF
    LDY.b #!Obj_PosOffMap>>8
.fill_posy:
    STX.b WMDATA-!DP_PPU
    STY.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_posy
    REP #$10
    LDX.w #!Obj_Unk1A00
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
    LDX.b #!Obj_Unk1A00Init
    LDY.b #$00
.fill_1a00:
    STX.b WMDATA-!DP_PPU
    STY.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_1a00
    REP #$10
    LDX.w #!Obj_Unk1A80
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
    LDX.b #$00
    LDY.b #!Obj_Unk1A81Init
.fill_1a80:
    STX.b WMDATA-!DP_PPU
    STY.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_1a80
    REP #$10
    LDX.w #!Obj_AnimMode
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
    LDX.b #$00
    LDY.b #$00
.fill_animmode:
    STX.b WMDATA-!DP_PPU
    STY.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_animmode
    REP #$10
    LDX.w #!Obj_Unk1C80
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
    LDX.b #!Obj_Unk1C80Init
    LDY.b #$00
.fill_1c80:
    STX.b WMDATA-!DP_PPU
    STY.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_1c80
    REP #$10
    LDX.w #!Obj_OamFlags
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
    LDX.b #!Obj_OamFlagsInit
    LDY.b #$00
.fill_oamflags:
    STX.b WMDATA-!DP_PPU
    STY.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_oamflags
    REP #$10
    LDX.w #!ObjX_Unk7F0B00&$FFFF
    STX.b WMADDL-!DP_PPU
    LDA.b #!WMADDH_Bank7F
    STA.b WMADDH-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
    LDX.b #$00
    LDY.b #$00
.fill_7f0b00:
    STX.b WMDATA-!DP_PPU
    STY.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_7f0b00
    REP #$10
    LDX.w #!ObjX_Unk7F0B80&$FFFF
    STX.b WMADDL-!DP_PPU
    SEP #$10
    LDA.l !Evt_ObjCount
    LDX.b #!ObjX_Unk7F0B80Init
    LDY.b #!ObjX_Unk7F0B80Init
.fill_7f0b80:
    STX.b WMDATA-!DP_PPU
    STY.b WMDATA-!DP_PPU
    DEC A
    BNE .fill_7f0b80
    REP #$10
    PLD
    LDX.w #!Obj_Unk1900Bytes
    STX.b !DmaFill_Size
    LDX.w #!Obj_Unk1900
    STX.b !DmaFill_Dest
    LDA.b #$00                          ; bank $00: low WRAM
    STA.b !DmaFill_Bank
    JSR ClearRAMDMA
    LDX.w #!ObjX_ClearBytes
    STX.b !DmaFill_Size
    LDX.w #!ObjX_Unk7F0580&$FFFF
    STX.b !DmaFill_Dest
    LDA.b #!Bank7F
    STA.b !DmaFill_Bank
    JSR ClearRAMDMA                     ; also wipes $7F:0B00-$7F:0BFF
    LDA.b #!ObjQ_Empty
    STA.b !ObjQ_Unk74
    STA.b !ObjQ_Unk75
    STA.b !ObjQ_Head
    STA.b !ObjQ_Tail
    LDX.w #!ObjQ_Unk71Init
    STX.b !ObjQ_Unk71
    STZ.b !ObjQ_Unk73
    LDA.l !Evt_ObjCount
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    STA.b !Evt_ObjSlotEnd
    LDX.w #$0000                        ; object 0
.object_loop:
    STZ.w !Obj_Unk1B01,X                ; 16-bit: also the next slot's Obj_State
    STZ.w !Obj_Unk1B80,X                ; 16-bit: the slot's word
    LDA.w !Obj_Unk1100,X                ; 16-bit: N = bit 7 of Obj_Unk1100+1
    BMI .next_object                    ; never taken (step 2 zeroed it)
    LDA.w !Obj_ScriptPos,X
    STX.b !Obj_Cur
    TAX
    SEP #$20
.opcode_loop:
    LDA.l !Evt_Data,X                   ; opcode
    BEQ .init_done                      ; $00 = return
    TXY                                 ; Y = opcode's offset
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A                               ; word table index
    TAX
    SEP #$20
    JSR (Evt_OpcodeTable,X)             ; handler returns X = next opcode
    BRA .opcode_loop
.init_done:
    REP #$20
    INX                                 ; past the $00
    TXA
    LDX.b !Obj_Cur
    STA.w !Obj_ScriptPos,X
.next_object:
    INX
    INX
    CPX.b !Evt_ObjSlotEnd
    BNE .object_loop
    SEP #$20
    BRL Map_InitEntryTile

; ------------------------------------------------------------
; $C0:5929 — Evt_ClearUnk0920 (51 bytes, $5929–$595B)
; Sets the 16 bytes Evt_Unk0920 to Evt_Unk0920Free ($FF), one STA each.
; Evt_FindOrAddUnk0920 searches this list for Evt_Unk0920Key (dp $E3),
; takes the first free entry for a new key and keeps the low byte of
; Obj_Cur beside it in Evt_Unk0930; what the entries stand for is not
; traced.
; Callers (1 JSR site): Scene_PostLoadInit ($C0:56BC).
; On entry: M=1 (8-bit A), DB=$00 (absolute stores); X and DP not used.
; Exit: M, X, DP and DB unchanged; A = Evt_Unk0920Free.
; ------------------------------------------------------------
Evt_ClearUnk0920:
    LDA.b #!Evt_Unk0920Free
    STA.w !Evt_Unk0920
    STA.w !Evt_Unk0920+1
    STA.w !Evt_Unk0920+2
    STA.w !Evt_Unk0920+3
    STA.w !Evt_Unk0920+4
    STA.w !Evt_Unk0920+5
    STA.w !Evt_Unk0920+6
    STA.w !Evt_Unk0920+7
    STA.w !Evt_Unk0920+8
    STA.w !Evt_Unk0920+9
    STA.w !Evt_Unk0920+10
    STA.w !Evt_Unk0920+11
    STA.w !Evt_Unk0920+12
    STA.w !Evt_Unk0920+13
    STA.w !Evt_Unk0920+14
    STA.w !Evt_Unk0920+15
    RTS

; ============================================================
; $C0:595C — Evt_RunObj0Func1 (33 bytes, $595C–$597C)
; (was Sub_595C.) Runs one event-script function of object 0: the
; offset stored at Evt_Data+2 (object 0's second function pointer),
; executing opcodes through Evt_OpcodeTable until opcode $00. Each
; opcode handler gets Y = the opcode's offset and must return with X
; at the next opcode. (Earlier notes called the opcodes "entity type
; bytes".) Called from Field_RestoreState, Scene_Unk0283 ($C0:0330)
; and Scene_PostLoadInit ($C0:56C8, on every location load).
; Callers (3 JSR sites): Field_RestoreState ($C0:0206), Scene_Unk0283 ($C0:0330) and
;   Scene_PostLoadInit ($C0:56C8).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100.
; Exit: M=1, X=0; A = 0, X = offset of the closing $00, Obj_Cur = 0
; (16-bit); Y and anything else are as the last opcode handler left them.
; ============================================================
org $C0595C
Evt_RunObj0Func1:
    REP #$20                ; A → 16-bit
    STZ.b !Obj_Cur          ; object 0 (16-bit store clears Obj_CurHi too)
    LDA.l !Evt_Data+2       ; object 0, function 1 offset
    TAX
    SEP #$20                ; A → 8-bit
.dispatch_loop:
    LDA.l !Evt_Data,X       ; opcode
    BEQ .done               ; $00 = return
    TXY                     ; Y = opcode's offset
    REP #$20                ; A → 16-bit
    AND.w #!Eng_LowByteMask
    ASL                     ; word table index
    TAX
    SEP #$20                ; A → 8-bit
    JSR (Evt_OpcodeTable,X) ; handler returns X = next opcode
    BRA .dispatch_loop
.done:
    RTS

; ============================================================
; $C0:597D — Evt_RunObjInit (92 bytes, $597D–$59D8)
; (was Sub_597D.) Runs object Obj_Cur's init function: the first of
; its 16 function offsets (Evt_Data + Obj_Cur*16, i.e. 32 bytes per
; object) is executed through Evt_OpcodeTable until opcode $00. Then
; Obj_ScriptPos = the offset after that $00, eight per-object words in
; bank $7F are cleared and Obj_Unk1C00 = 7.
; Called from Party_ReinitIfChanged for each character object.
; Callers (7 JSR sites): Party_ReinitIfChanged ($C0:1A24, $C0:1A2D, $C0:1A36, $C0:1A3F, $C0:1A48,
;   $C0:1A51, $C0:1A5A).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100, Obj_Cur = object
; (Obj_CurHi 0).
; Exit: M=1, X=0; X = Obj_Cur, A = Obj_Unk1C00Init; Y and anything else
; are as the last opcode handler left them.
; ============================================================
org $C0597D
Evt_RunObjInit:
    LDA.b !Obj_Cur          ; object x 2
    REP #$20                ; A → 16-bit
    AND.w #!Eng_LowByteMask
    ASL
    ASL
    ASL
    ASL                     ; x 16 = object x 32: its function table
    TAX
    LDA.l !Evt_Data,X       ; function 0 (init) offset
    TAX
    SEP #$20                ; A → 8-bit
.inner_loop:
    LDA.l !Evt_Data,X       ; opcode
    BEQ .list_done          ; $00 = return
    TXY                     ; Y = opcode's offset
    REP #$20                ; A → 16-bit
    AND.w #!Eng_LowByteMask
    ASL                     ; word table index
    TAX
    SEP #$20                ; A → 8-bit
    JSR (Evt_OpcodeTable,X) ; handler returns X = next opcode
    BRA .inner_loop
.list_done:
    REP #$20                ; A → 16-bit
    INX                     ; past the $00
    TXA
    LDX.b !Obj_Cur          ; 16-bit; Obj_CurHi is 0
    STA.w !Obj_ScriptPos,X  ; where the object's script continues
    LDA #$0000
    STA.l !ObjX_Unk7F0580,X ; clear the object's bank-$7F words
    STA.l !ObjX_Unk7F0600,X
    STA.l !ObjX_Unk7F0680,X
    STA.l !ObjX_Unk7F0700,X
    STA.l !ObjX_Unk7F0780,X
    STA.l !ObjX_Unk7F0800,X
    STA.l !ObjX_Unk7F0880,X
    STA.l !ObjX_Unk7F0900,X
    SEP #$20                ; A → 8-bit
    LDA.b #!Obj_Unk1C00Init
    STA.w !Obj_Unk1C00,X
    RTS

; ============================================================
; Object script scheduler ($C0:59D9–$C0:5AC4)
; Each frame Field_EndOfFrame first runs Vblank_Unk59D9, which counts
; down every object's script timer and queues the objects whose timer
; ran out (the ObjQ_Unk74 list, linked through Obj_Unk1080), then
; Vblank_ReadScanlineCounters, which runs the queued objects' scripts
; (Evt_RunObjScriptSteps) while the frame still has time. An opcode
; handler returns C=1 to go on with the next opcode, C=0 to stop the
; object for this frame, and X = where its script goes on.
; The two keep their names because Field_EndOfFrame calls them by them
; (better: Obj_QueueScripts and Obj_RunQueuedScripts).
; ============================================================

; ------------------------------------------------------------
; $C0:59D9 — Vblank_Unk59D9 (109 bytes, $59D9–$5A45)
; With DP=$1000 (the Obj_Unk1000 page), for each object slot below
;   Evt_ObjSlotEnd (= Evt_ObjCount x 2, stored here) whose Obj_Unk1000
;   has bit 7 clear: Obj_Unk1001 is counted down (when not already 0);
;   at 0 the object is queued, unless its Obj_Unk1100 has bit 7 set:
;   - Obj_Unk1100 = 0: at the head of the ObjQ_Unk74 list (Obj_Unk1080
;     = the old head), unless it is the head already;
;   - other kinds: at the tail (ObjQ_Unk75; the old tail's
;     Obj_Unk1080 = it), unless it is the tail or already queued
;     (Obj_Unk1080 bit 7 clear);
;   - into an empty list: head and tail.
;   On queueing Obj_Unk1001 is reloaded from Obj_Unk1000 (the period;
;   Obj_Unk1000Init = 4 at load); an object left unqueued keeps
;   Obj_Unk1001 = 0 and is tried again next frame.
; Quirk: the head insert checks only that the object is not the head,
;   not Obj_Unk1080, so an object of kind 0 already further down the
;   list would be linked in twice (not known to happen).
; Callers (1 JSR site): Field_EndOfFrame ($C0:00C1).
; On entry: M=1 (8-bit A), X=1 (8-bit X/Y), DP any (saved; set to
;   $1000 here, restored), DB=$00 (Obj_Unk1100 and the field bytes
;   absolute).
; Exit: M=1, X=1, DP and DB unchanged; A, X and Y clobbered;
;   Evt_ObjSlotEnd, ObjQ_Unk74/75 and the objects' Obj_Unk1001 /
;   Obj_Unk1080 written.
; ------------------------------------------------------------
Vblank_Unk59D9:
    PHD
    REP #$20
    LDA.w #!Obj_Unk1000
    TCD
    SEP #$20
    LDA.l !Evt_ObjCount
    ASL A
    STA.w !DP_Field+!Evt_ObjSlotEnd
    LDX.b #$00
.obj_loop:
    LDA.b !Obj_Unk1000-!Obj_Unk1000,X
    BMI .next
    LDA.b !Obj_Unk1001-!Obj_Unk1000,X
    BEQ .due
    DEC.b !Obj_Unk1001-!Obj_Unk1000,X
    BEQ .due
.next:
    INX
    INX
    CPX.w !DP_Field+!Evt_ObjSlotEnd
    BNE .obj_loop
    PLD
    RTS
.due:
    LDA.w !Obj_Unk1100,X
    BEQ .at_head
    BMI .next
    CPX.w !DP_Field+!ObjQ_Unk75
    BEQ .next                           ; already the tail
    LDA.b !Obj_Unk1080-!Obj_Unk1000,X
    BPL .next                           ; already linked
    LDA.w !DP_Field+!ObjQ_Unk75
    BMI .first
    TXY
    TAX
    TYA
    STA.b !Obj_Unk1080-!Obj_Unk1000,X   ; old tail -> this object
    STA.w !DP_Field+!ObjQ_Unk75
    TAX
    LDA.b !Obj_Unk1000-!Obj_Unk1000,X
    STA.b !Obj_Unk1001-!Obj_Unk1000,X   ; reload the timer
    BRA .next
.first:
    STX.w !DP_Field+!ObjQ_Unk74
    STX.w !DP_Field+!ObjQ_Unk75
    LDA.b !Obj_Unk1000-!Obj_Unk1000,X
    STA.b !Obj_Unk1001-!Obj_Unk1000,X
    BRA .next
.at_head:
    CPX.w !DP_Field+!ObjQ_Unk74
    BEQ .next                           ; already the head
    LDA.w !DP_Field+!ObjQ_Unk74
    BMI .first
    STA.b !Obj_Unk1080-!Obj_Unk1000,X   ; this object -> old head
    STX.w !DP_Field+!ObjQ_Unk74
    LDA.b !Obj_Unk1000-!Obj_Unk1000,X
    STA.b !Obj_Unk1001-!Obj_Unk1000,X
    BRA .next

; ------------------------------------------------------------
; $C0:5A46 — Vblank_ReadScanlineCounters (77 bytes, $5A46–$5A92)
; Runs the queued objects' scripts while there is time left in the
;   frame: before each object it reads the V counter (as
;   Field_ProcessAnimQueue does) and stops once it is at ObjQ_Unk69 or
;   more but below line 240 (Ppu_FirstHiddenLine). Each time it takes
;   the ObjQ_Unk74 head off the list (its Obj_Unk1080 = $80; when it was
;   also the tail the list becomes empty) and runs
;   Evt_RunObjScriptSteps for it. Returns when the list is empty.
; Quirk: the TAX right after the LDA of the head is redundant (both
;   paths load X again).
; Callers (1 JSR site): Field_EndOfFrame ($C0:00C4).
; On entry: M=1 (8-bit A), X=1 (8-bit X/Y), DP=$0100 (ObjQ_*, Obj_Cur),
;   DB=$00 (PPU counters and Obj_* tables absolute).
; Exit: M=1, X=1, DP and DB unchanged; A, X and Y clobbered (and what
;   the opcode handlers change); Obj_Cur = the last object run.
; ------------------------------------------------------------
Vblank_ReadScanlineCounters:
    LDA.w STAT78                        ; reset the OPVCT read flip-flop
.latch:
    LDA.w SLHV                          ; latch H/V
    LDA.w OPVCT                         ; low 8 bits
    XBA
    LDA.w OPVCT                         ; bit 0 = bit 8 of V
    AND.b #$01
    XBA
    REP #$20                            ; A = 9-bit V counter
    CMP.w #!Ppu_FirstHiddenLine
    BPL .in_window                      ; line 240 or later: keep going
    CMP.b !ObjQ_Unk69
    BCS .exit                           ; out of time for this frame
.in_window:
    LDA.w #$0000                        ; clear B
    SEP #$20
    LDA.b !ObjQ_Unk74
    BMI .exit                           ; list empty
    TAX                                 ; (redundant)
    LDA.b !ObjQ_Unk74
    CMP.b !ObjQ_Unk75
    BEQ .last
    TAX
    LDA.w !Obj_Unk1080,X
    STA.b !ObjQ_Unk74                   ; next becomes the head
    LDA.b #!ObjQ_Empty
    STA.w !Obj_Unk1080,X
    JSR Evt_RunObjScriptSteps
    BRA .latch
.last:
    TAX
    LDA.b #!ObjQ_Empty
    STA.w !Obj_Unk1080,X
    STA.b !ObjQ_Unk74
    STA.b !ObjQ_Unk75
    JSR Evt_RunObjScriptSteps
    BRA .latch
.exit:
    SEP #$20
    RTS

; ------------------------------------------------------------
; $C0:5A93 — Evt_RunObjScriptSteps (50 bytes, $5A93–$5AC4)
; Runs object X's script from Obj_ScriptPos: Obj_Cur = X, then up to
;   Field_Unk68 opcodes (Evt_StepsLeft counts them; 5 from load) through
;   Evt_OpcodeTable, each with Y = the opcode's Evt_Data offset; it goes
;   on while a handler returns C=1 and stops at the first C=0. The X the
;   last handler returned is stored back in Obj_ScriptPos.
; Callers (2 JSR sites): Vblank_ReadScanlineCounters ($C0:5A7C, $C0:5A8B).
; On entry: M=1 (8-bit A), X=1 (8-bit X/Y), DP=$0100 (Field_Unk68,
;   Evt_StepsLeft, Obj_Cur), DB=$00 (Obj_ScriptPos absolute); X = the
;   object's slot; Obj_CurHi = 0 (only the low byte is stored, and
;   16-bit loads of Obj_Cur follow).
; Exit: M=1, X=1 (SEP #$30), DP and DB unchanged; A, X and Y clobbered
;   (and what the handlers change); Obj_Cur = the slot (low byte).
; ------------------------------------------------------------
Evt_RunObjScriptSteps:
    LDA.b !Field_Unk68
    STA.b !Evt_StepsLeft
    REP #$20
    LDA.w !Obj_ScriptPos,X
    STX.b !Obj_Cur                      ; 8-bit store: Obj_CurHi stays 0
    REP #$10
    TAX
    SEP #$20
.step:
    LDA.l !Evt_Data,X                   ; opcode
    TXY                                 ; Y = the opcode's offset
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAX
    SEP #$20
    JSR (Evt_OpcodeTable,X)             ; returns X = where to go on
    BCC .stop                           ; C=0: wait for a later frame
    DEC.b !Evt_StepsLeft
    BNE .step
.stop:
    REP #$20
    TXA
    LDX.b !Obj_Cur
    STA.w !Obj_ScriptPos,X
    SEP #$30
    RTS

; ============================================================
; $C0:5AC5 — Evt_StartTargetFunc1 (90 bytes, $5AC5–$5B1E)
; Starts function 1 of the object in Field_UnkEB (the one the action
; button found). It does nothing unless
; that object's Obj_Unk1C01 is 0, Obj_Unk1100 and Obj_Unk1000 have
; bit 7 clear and Obj_Unk1C00 is at least Obj_Unk1C00Min. Then it
; saves Obj_ScriptPos in the ObjX_Unk7F0580 table of level
; Obj_Unk1C00 (index level x Evt_PrioStride + slot, through the
; hardware multiplier), points Obj_ScriptPos at function 1 (the second
; word of the object's function table at Evt_Data + slot x 16), sets
; Obj_Unk1C00 = 1 and zeroes Obj_Unk1A80, Obj_Unk1A01 and Obj_Unk1001.
; Reading Obj_Unk1C00 as a priority level whose interrupted position is
; kept per level is an inference from this save; not established.
; The 16-bit loads of Field_UnkEB also take $01EC as the high byte;
; Field_FindObjInFront's 16-bit store keeps it 0.
; Callers (1 JSR site): Field_ActionButton ($C0:1AD7).
; On entry: M=1 (8-bit A), X=1 (8-bit X/Y), DP=$0100, DB=$00;
; Field_UnkEB = the object's slot (object x 2).
; Exit: M=1, X=1, DP and DB unchanged; A and X clobbered (when started:
; A = 1, X = the slot); Eng_Scratch overwritten.
; ============================================================
org $C05AC5
Evt_StartTargetFunc1:
    LDX.b !Field_UnkEB
    LDA.w !Obj_Unk1C01,X
    BNE .done
    LDA.w !Obj_Unk1100,X
    BMI .done
    LDA.w !Obj_Unk1000,X
    BMI .done
    LDA.w !Obj_Unk1C00,X
    CMP.b #!Obj_Unk1C00Min
    BCC .done
    STA.w WRMPYA
    LDA.b #!Evt_PrioStride
    STA.w WRMPYB
    NOP                         ; wait for the product
    NOP
    REP #$30
    CLC
    LDA.w RDMPYL
    ADC.b !Field_UnkEB
    STA.b !Eng_Scratch          ; level x $80 + slot
    LDA.w !Obj_ScriptPos,X
    LDX.b !Eng_Scratch
    STA.l !ObjX_Unk7F0580,X     ; save where the object was
    LDA.b !Field_UnkEB
    ASL A
    ASL A
    ASL A
    ASL A                       ; slot x 16: its function table
    CLC
    ADC.w #!Evt_Func1Ofs
    TAX
    LDA.l !Evt_Data,X
    LDX.b !Field_UnkEB
    STA.w !Obj_ScriptPos,X
    SEP #$30
    LDA.b #!Obj_Unk1C00Func1
    STA.w !Obj_Unk1C00,X
    STZ.w !Obj_Unk1A80,X
    STZ.w !Obj_Unk1A01,X
    STZ.w !Obj_Unk1001,X
.done:
    RTS

; ------------------------------------------------------------
; $C0:5B1F — Evt_RedirectObjScript (68 bytes, $5B1F–$5B62)
; Evt_StartTargetFunc1's save without its target: for the object in
; Field_UnkEB, unless Obj_Unk1100 has bit 7 set or Obj_Unk1C00 is 0,
; saves Obj_ScriptPos in the ObjX_Unk7F0580 table of level Obj_Unk1C00
; (level x Evt_PrioStride + slot), then sets Obj_ScriptPos =
; Evt_RedirectPos, Obj_Unk1C00 = 0 and zeroes Obj_Unk1A80, Obj_Unk1A01
; and Obj_Unk1001. Unlike Evt_StartTargetFunc1 it does not test
; Obj_Unk1C01 or Obj_Unk1000, and its lower bound is 1 (CMP #1), not
; Obj_Unk1C00Min. Field_Unk034B runs it for party members 2 and 3.
; Callers (2 JSR sites): Field_Unk034B ($C0:036A, $C0:037B).
; On entry: M=1 (8-bit A), X=1 (8-bit X/Y), DP=$0100, DB=$00;
; Field_UnkEB = the object's slot (16-bit loads take $01EC as the high
; byte).
; Exit: M=1, X=1, DP and DB unchanged; A and X clobbered (when
; redirected: A = 0, X = the slot); Eng_Scratch written.
; ------------------------------------------------------------
org $C05B1F
Evt_RedirectObjScript:
    LDX.b !Field_UnkEB
    LDA.w !Obj_Unk1100,X
    BMI .done
    LDA.w !Obj_Unk1C00,X
    CMP.b #$01
    BCC .done                           ; level 0: nothing to save
    STA.w WRMPYA
    LDA.b #!Evt_PrioStride
    STA.w WRMPYB
    NOP                                 ; wait for the product
    NOP
    REP #$30
    CLC
    LDA.w RDMPYL
    ADC.b !Field_UnkEB
    STA.b !Eng_Scratch                  ; level x $80 + slot
    LDA.w !Obj_ScriptPos,X
    LDX.b !Eng_Scratch
    STA.l !ObjX_Unk7F0580,X             ; save where the object was
    LDX.b !Field_UnkEB
    LDA.w #!Evt_RedirectPos
    STA.w !Obj_ScriptPos,X
    SEP #$30
    LDA.b #$00
    STA.w !Obj_Unk1C00,X
    STZ.w !Obj_Unk1A80,X
    STZ.w !Obj_Unk1A01,X
    STZ.w !Obj_Unk1001,X
.done:
    RTS

; ------------------------------------------------------------
; $C0:5B63 — Map_LeaderPastRowMax (14 bytes, $5B63–$5B70)
; Map_Unk9175's test for a downward step: C=1 when the leader's
; Obj_TileY is past Map_Unk1D1D (TileY >= Map_Unk1D1D + 1).
; Callers (1 JSR site): Map_Unk9175 ($C0:91A2).
; On entry: M=1 (8-bit A), X = the leader's slot (either width), DB=$00;
; absolute operands only, DP not used.
; Exit: M, X, DP and DB unchanged; C as above; A clobbered; Eng_Scratch
; ($01D9) = Map_Unk1D1D + 1.
; ------------------------------------------------------------
org $C05B63
Map_LeaderPastRowMax:
    LDA.w !Map_Unk1D1D
    INC A
    STA.w !DP_Field+!Eng_Scratch
    LDA.w !Obj_TileY,X
    CMP.w !DP_Field+!Eng_Scratch
    RTS

; ------------------------------------------------------------
; $C0:5B71 — Map_LeaderPastRowMin (8 bytes, $5B71–$5B78)
; Map_Unk9175's test for an upward step: C=1 when the leader's
; Obj_TileY <= Map_Unk1D1C + 1. Both row tests take their bound one
; row lower (+1) than the column tests do; kept as found.
; Callers (1 JSR site): Map_Unk9175 ($C0:919B).
; On entry: M=1 (8-bit A), X = the leader's slot (either width), DB=$00;
; absolute operands only, DP not used.
; Exit: M, X, DP and DB unchanged; C as above; A clobbered.
; ------------------------------------------------------------
Map_LeaderPastRowMin:
    LDA.w !Map_Unk1D1C
    INC A
    CMP.w !Obj_TileY,X
    RTS

; ------------------------------------------------------------
; $C0:5B79 — Map_LeaderPastColMax (13 bytes, $5B79–$5B85)
; Map_Unk9175's test for a rightward step: C=1 when the leader's
; Obj_TileX >= Map_Unk1D1B.
; Callers (1 JSR site): Map_Unk9175 ($C0:918C).
; On entry: M=1 (8-bit A), X = the leader's slot (either width), DB=$00;
; absolute operands only, DP not used.
; Exit: M, X, DP and DB unchanged; C as above; A clobbered; Eng_Scratch
; ($01D9) = Map_Unk1D1B.
; ------------------------------------------------------------
Map_LeaderPastColMax:
    LDA.w !Map_Unk1D1B
    STA.w !DP_Field+!Eng_Scratch
    LDA.w !Obj_TileX,X
    CMP.w !DP_Field+!Eng_Scratch
    RTS

; ------------------------------------------------------------
; $C0:5B86 — Map_LeaderPastColMin (7 bytes, $5B86–$5B8C)
; Map_Unk9175's test for a leftward step: C=1 when the leader's
; Obj_TileX <= Map_Unk1D1A.
; Callers (1 JSR site): Map_Unk9175 ($C0:9185).
; On entry: M=1 (8-bit A), X = the leader's slot (either width), DB=$00;
; absolute operands only, DP not used.
; Exit: M, X, DP and DB unchanged; C as above; A clobbered.
; ------------------------------------------------------------
Map_LeaderPastColMin:
    LDA.w !Map_Unk1D1A
    CMP.w !Obj_TileX,X
    RTS

; ============================================================
; Event helpers ($C0:5B8D–$C0:5CC6)
; Called from event-opcode handlers: the action-target
; test, the in-front object search and the Evt_Unk0920 list.
; ============================================================

; ------------------------------------------------------------
; $C0:5B8D — Evt_HasActionTarget (8 bytes, $5B8D–$5B94)
; C=1 when Field_UnkEB holds an object (bit 7 clear), C=0 when it is
;   $80 (none).
; Callers (1 JSR site): Evt_OpB0_PartyControl ($C0:304F).
; On entry: M=1 (8-bit A), DP=$0100 (Field_UnkEB); X and DB not used.
; Exit: M, X, DP and DB unchanged; A = Field_UnkEB; C as above.
; ------------------------------------------------------------
Evt_HasActionTarget:
    LDA.b !Field_UnkEB
    BPL .target
    CLC
    RTS
.target:
    SEC
    RTS

; ------------------------------------------------------------
; $C0:5B95 — Evt_FindSolidObjInFront (93 bytes, $5B95–$5BF1)
; Looks for a solid object within a tile in front of Obj_Cur. Nothing
;   (C=0) unless Obj_Cur's Obj_Unk0F00 is nonzero and its Obj_Unk1C80 has
;   bit 1 (Obj_Unk1C80Front) set. Then for each object from
;   Evt_ObjCount x 2 down to 2 (object 0 is never tested) that has
;   Obj_Unk0F00 nonzero, Obj_Unk1100 bit 7 clear, Obj_Unk1B01Solid set
;   and is not Obj_Cur, runs Evt_InFrontTests entry Obj_Facing (of
;   Obj_Cur; not masked to 0-3) with ObjFront_X/Y = Obj_Cur's
;   Obj_PosX/Y; the first that gives C=1 ends the search.
; Callers (9 JSR sites): Evt_Op96_WalkToTile ($C0:4FBD), Evt_Op9A_WalkTowardTile ($C0:504F),
;   Evt_Op97_WalkToTileVar ($C0:50FC), Evt_OpA0_MoveToTile ($C0:5170), Evt_OpA1_MoveToTileVar
;   ($C0:51F4), Evt_Op94_Body ($C0:5293), Evt_Op9E_Body ($C0:5329), Evt_Op98_Body ($C0:53DC) and
;   Evt_Op8F_FollowPc ($C0:54C8).
; Callers note: all in the event movement opcodes (or their shared
;   bodies).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Obj_Cur and the
;   ObjFront_* scratch), DB=$00 (Obj_* tables absolute); Y = the
;   caller's script offset.
; Exit: M=1, X=0, DP and DB unchanged; Y as on entry (saved in
;   ObjFront_SavedY); C=1: X = the object found; C=0: X = 0 after a
;   search, or Obj_Cur when it did not search; A clobbered;
;   ObjFront_OtherHi = 0, and after a search ObjFront_FacingX2,
;   ObjFront_X/Y and ObjFront_Other written.
; ------------------------------------------------------------
Evt_FindSolidObjInFront:
    STZ.b !ObjFront_OtherHi
    LDX.b !Obj_Cur
    LDA.w !Obj_Unk0F00,X
    BNE .active
.none:
    CLC
    RTS
.active:
    LDA.w !Obj_Unk1C80,X
    BIT.b #!Obj_Unk1C80Front
    BEQ .none
    STY.b !ObjFront_SavedY
    LDA.w !Obj_Facing,X
    ASL A
    STA.b !ObjFront_FacingX2
    REP #$20
    LDA.w !Obj_PosX,X
    STA.b !ObjFront_X
    LDA.w !Obj_PosY,X
    STA.b !ObjFront_Y
    SEP #$30
    LDA.l !Evt_ObjCount
    ASL A
    TAX
.obj_loop:
    LDA.w !Obj_Unk0F00,X
    BNE .candidate
.next:
    DEX
    DEX
    BNE .obj_loop
    REP #$10
    LDY.b !ObjFront_SavedY
    CLC
    RTS
.candidate:
    LDA.w !Obj_Unk1100,X
    BMI .next
    CPX.b !Obj_Cur
    BEQ .next
    LDA.w !Obj_Unk1B01,X
    BIT.b #!Obj_Unk1B01Solid
    BEQ .next
    STX.b !ObjFront_Other
    LDX.b !ObjFront_FacingX2
    JSR (Evt_InFrontTests,X)
    LDX.b !ObjFront_Other
    BCC .next
    REP #$10
    LDY.b !ObjFront_SavedY
    RTS

; Evt_FindSolidObjInFront's tests by Obj_Facing x 2 (facings 0-3).
Evt_InFrontTests:
    dw Evt_InFrontUp                    ; 0
    dw Evt_InFrontDown                  ; 1
    dw Evt_InFrontLeft                  ; 2
    dw Evt_InFrontRight                 ; 3

; ------------------------------------------------------------
; $C0:5BFA — Evt_InFrontUp (38 bytes, $5BFA–$5C1F)
; Facing 0: C=1 when ObjFront_Other is above Obj_Cur and within a tile:
;   its Obj_PosY - ObjFront_Y is negative with magnitude under
;   ObjFront_Reach, and its |Obj_PosX - ObjFront_X| is under it too.
; Quirk: neither SBC has a SEC before it. The first takes the carry of
;   Evt_FindSolidObjInFront's CPX of the slot against Obj_Cur (set when
;   the slot is the higher, so the difference is exact, else one less);
;   the second the clear carry of the CMP before it (one less). The
;   negative differences are then complemented with EOR, not negated
;   (one less again), so the bounds are off by one or two units.
; Reached through Evt_InFrontTests.
; On entry: M=1 (8-bit A), X=1 (8-bit X/Y), DP=$0100 (ObjFront_*),
;   DB=$00 (Obj_* tables absolute); ObjFront_OtherHi = 0.
; Exit: M=1, X=1, DP and DB unchanged; C as above; A clobbered; X =
;   ObjFront_Other; Y unchanged.
; ------------------------------------------------------------
Evt_InFrontUp:
    REP #$20
    LDX.b !ObjFront_Other
    LDA.w !Obj_PosY,X
    SBC.b !ObjFront_Y                   ; no SEC (see above)
    BPL Evt_InFrontNo
    EOR.w #!Eng_Invert16
    CMP.w #!ObjFront_Reach
    BCS Evt_InFrontNo
    LDA.w !Obj_PosX,X
    SBC.b !ObjFront_X                   ; C = 0 from the CMP
    BPL .x_abs
    EOR.w #!Eng_Invert16
.x_abs:
    CMP.w #!ObjFront_Reach
    BCS Evt_InFrontNo
    SEP #$20
    SEC
    RTS

; ------------------------------------------------------------
; $C0:5C20 — Evt_InFrontDown (35 bytes, $5C20–$5C42; then the shared
;   failure exit Evt_InFrontNo, 4 bytes, $5C43–$5C46)
; Facing 1: C=1 when ObjFront_Other is below Obj_Cur within a tile:
;   Obj_PosY - ObjFront_Y from 0 to under ObjFront_Reach and
;   |Obj_PosX - ObjFront_X| under it, with the same SBC carries as
;   Evt_InFrontUp. Evt_InFrontNo (SEP #$20, CLC, RTS) is where every
;   test fails to.
; Reached through Evt_InFrontTests; Evt_InFrontNo by branches from all
;   four tests.
; On entry: M=1 (8-bit A), X=1 (8-bit X/Y), DP=$0100 (ObjFront_*),
;   DB=$00 (Obj_* tables absolute); ObjFront_OtherHi = 0.
; Exit: M=1, X=1, DP and DB unchanged; C as above; A clobbered; X =
;   ObjFront_Other; Y unchanged.
; ------------------------------------------------------------
Evt_InFrontDown:
    REP #$20
    LDX.b !ObjFront_Other
    LDA.w !Obj_PosY,X
    SBC.b !ObjFront_Y
    BMI Evt_InFrontNo
    CMP.w #!ObjFront_Reach
    BCS Evt_InFrontNo
    LDA.w !Obj_PosX,X
    SBC.b !ObjFront_X
    BPL .x_abs
    EOR.w #!Eng_Invert16
.x_abs:
    CMP.w #!ObjFront_Reach
    BCS Evt_InFrontNo
    SEP #$20
    SEC
    RTS
Evt_InFrontNo:                          ; header: see Evt_InFrontDown
    SEP #$20
    CLC
    RTS

; ------------------------------------------------------------
; $C0:5C47 — Evt_InFrontLeft (38 bytes, $5C47–$5C6C)
; Facing 2: as Evt_InFrontUp on the other axis: C=1 when
;   Obj_PosX - ObjFront_X is negative with magnitude under
;   ObjFront_Reach and |Obj_PosY - ObjFront_Y| is under it (same SBC
;   carries).
; Reached through Evt_InFrontTests.
; On entry: M=1 (8-bit A), X=1 (8-bit X/Y), DP=$0100 (ObjFront_*),
;   DB=$00 (Obj_* tables absolute); ObjFront_OtherHi = 0.
; Exit: M=1, X=1, DP and DB unchanged; C as above; A clobbered; X =
;   ObjFront_Other; Y unchanged.
; ------------------------------------------------------------
Evt_InFrontLeft:
    REP #$20
    LDX.b !ObjFront_Other
    LDA.w !Obj_PosX,X
    SBC.b !ObjFront_X
    BPL Evt_InFrontNo
    EOR.w #!Eng_Invert16
    CMP.w #!ObjFront_Reach
    BCS Evt_InFrontNo
    LDA.w !Obj_PosY,X
    SBC.b !ObjFront_Y
    BPL .y_abs
    EOR.w #!Eng_Invert16
.y_abs:
    CMP.w #!ObjFront_Reach
    BCS Evt_InFrontNo
    SEP #$20
    SEC
    RTS

; ------------------------------------------------------------
; $C0:5C6D — Evt_InFrontRight (35 bytes, $5C6D–$5C8F)
; Facing 3: as Evt_InFrontDown on the other axis: C=1 when
;   Obj_PosX - ObjFront_X is from 0 to under ObjFront_Reach and
;   |Obj_PosY - ObjFront_Y| is under it (same SBC carries).
; Reached through Evt_InFrontTests.
; On entry: M=1 (8-bit A), X=1 (8-bit X/Y), DP=$0100 (ObjFront_*),
;   DB=$00 (Obj_* tables absolute); ObjFront_OtherHi = 0.
; Exit: M=1, X=1, DP and DB unchanged; C as above; A clobbered; X =
;   ObjFront_Other; Y unchanged.
; ------------------------------------------------------------
Evt_InFrontRight:
    REP #$20
    LDX.b !ObjFront_Other
    LDA.w !Obj_PosX,X
    SBC.b !ObjFront_X
    BMI Evt_InFrontNo
    CMP.w #!ObjFront_Reach
    BCS Evt_InFrontNo
    LDA.w !Obj_PosY,X
    SBC.b !ObjFront_Y
    BPL .y_abs
    EOR.w #!Eng_Invert16
.y_abs:
    CMP.w #!ObjFront_Reach
    BCS Evt_InFrontNo
    SEP #$20
    SEC
    RTS

; ------------------------------------------------------------
; $C0:5C90 — Evt_FindOrAddUnk0920 (55 bytes, $5C90–$5CC6)
; Looks up Evt_Unk0920Key in the Evt_Unk0920Entries (16) bytes of
;   Evt_Unk0920: found at n, A = Evt_Unk0930[n] (the Obj_Cur stored with
;   it) and C=1. Not found: the first free entry (Evt_Unk0920Free) gets
;   the key and Evt_Unk0930 = the low byte of Obj_Cur, C=0. No free
;   entry: the game stops on colour Halt_ColorUnk0920Full
;   (Sys_HaltWithColor, never returns).
; Callers (2 JSR sites): Evt_Op82_InitWramSprite ($C0:4626) and Evt_Op83_InitEnemySprite ($C0:4781).
; Callers note: Evt_Op82_InitWramSprite ($C0:4626) and Evt_Op83_InitEnemySprite
;   ($C0:4781), with the sprite's graphics index as the key.
; On entry: M=1 (8-bit A), X=0 (16-bit X: CPX #imm is 3 bytes),
;   DP=$0100 (Evt_Unk0920Key, Obj_Cur), DB=$00 or $7E (Evt_Unk0920/0930
;   absolute, low WRAM).
; Exit: M=1, X=0, DP and DB unchanged; C as above; X = the entry; A =
;   its Evt_Unk0930 (C=1) or Obj_Cur (C=0); Y unchanged.
; ------------------------------------------------------------
Evt_FindOrAddUnk0920:
    LDA.b !Evt_Unk0920Key
    LDX.w #$0000
.find:
    CMP.w !Evt_Unk0920,X
    BEQ .found
    INX
    CPX.w #!Evt_Unk0920Entries
    BMI .find
    LDX.w #$0000
    LDA.b #!Evt_Unk0920Free
.find_free:
    CMP.w !Evt_Unk0920,X
    BEQ .add
    INX
    CPX.w #!Evt_Unk0920Entries
    BMI .find_free
    LDX.w #!Halt_ColorUnk0920Full
    BRL Sys_HaltWithColor
.add:
    LDA.b !Evt_Unk0920Key
    STA.w !Evt_Unk0920,X
    LDA.b !Obj_Cur
    STA.w !Evt_Unk0930,X
    CLC
    RTS
.found:
    LDA.w !Evt_Unk0930,X
    SEC
    RTS

; ------------------------------------------------------------
; $C0:5CC7 — LocLoad_CheckEvtData (37 bytes, $5CC7–$5CEB)
; Two checks LocLoad_Unk56D4 makes on the event data it has just
; unpacked; each failure ends in Sys_HaltWithColor:
; - Evt_ObjCount = Evt_BadObjCount ($0D) with first Evt_Data byte
;   Evt_BadFirstByte ($0A): colour Halt_ColorEvtUnk ($01F0). Why this
;   pair is refused is not known;
; - Decomp_OutLen above Evt_DataMax ($1700; CPX then BPL, so the test
;   is the sign of $1700 - Decomp_OutLen): colour Halt_ColorEvtLong
;   ($000F). $7F:2000 + $1700 is where
;   Map_Unk7F3700 starts, which LocLoad_InitUnk7F3700 fills right
;   after, so this looks like an overflow guard.
; Callers (1 JSR site): LocLoad_Unk56D4 ($C0:5703).
; On entry: M=1 (8-bit A), X=0 (16-bit X: the colour), DB=$00
; (Decomp_OutLen absolute); DP not used.
; Exit: returns only when both checks pass: M=1, X=0, DP and DB
; unchanged; A and X clobbered.
; ------------------------------------------------------------
org $C05CC7
LocLoad_CheckEvtData:
    LDA.l !Evt_ObjCount
    CMP.b #!Evt_BadObjCount
    BNE .check_length
    LDA.l !Evt_Data
    CMP.b #!Evt_BadFirstByte
    BNE .check_length
    LDX.w #!Halt_ColorEvtUnk
    BRL Sys_HaltWithColor
.check_length:
    LDX.w #!Evt_DataMax
    CPX.w !Decomp_OutLen
    BPL .ok
    LDX.w #!Halt_ColorEvtLong
    BRL Sys_HaltWithColor
.ok:
    RTS

; ------------------------------------------------------------
; $C0:5CEC — LocLoad_InitUnk7F3700 (75 bytes, $5CEC–$5D36)
; Seeds the 134 bytes at Map_Unk7F3700 from LocLoad_Unk7F3700Init with
; five MVNs: 32 bytes from the table's start to $7F:3700, then three
; times 32 bytes from LocLoad_Unk7F3700Init_Rec1 to $7F:3720, $7F:3740
; and $7F:3760, and 6 bytes from LocLoad_Unk7F3700Init_Rec4 to
; $7F:3780. The 32-byte copies read past the record they start at: the
; first takes 7 bytes of Rec1 along, those from Rec1 all of Rec4 and
; the first 2 bytes of Evt_OpcodeTable; kept as found. Map_Unk7F3728/3748/3768 and
; Map_Unk7F3781 lie inside these blocks.
; Callers (1 BRL site): LocLoad_Unk56D4 ($C0:5706).
; Callers note: BRL from LocLoad_Unk56D4 ($C0:5706), its only reference.
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y); DP not used; any DB
; (preserved around each MVN).
; Exit: M=1, X=0, DB preserved; A, X and Y clobbered.
; ------------------------------------------------------------
LocLoad_InitUnk7F3700:
    REP #$20
    LDX.w #LocLoad_Unk7F3700Init
    LDY.w #!Map_Unk7F3700&$FFFF
    PHB
    LDA.w #!Map_Unk7F3700RecBytes-1     ; MVN count - 1
    MVN !Bank7F,!BankC0                 ; lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    PLB
    LDX.w #LocLoad_Unk7F3700Init_Rec1
    LDY.w #(!Map_Unk7F3700+(1*!Map_Unk7F3700RecBytes))&$FFFF
    PHB
    LDA.w #!Map_Unk7F3700RecBytes-1
    MVN !Bank7F,!BankC0                 ; lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    PLB
    LDX.w #LocLoad_Unk7F3700Init_Rec1
    LDY.w #(!Map_Unk7F3700+(2*!Map_Unk7F3700RecBytes))&$FFFF
    PHB
    LDA.w #!Map_Unk7F3700RecBytes-1
    MVN !Bank7F,!BankC0                 ; lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    PLB
    LDX.w #LocLoad_Unk7F3700Init_Rec1
    LDY.w #(!Map_Unk7F3700+(3*!Map_Unk7F3700RecBytes))&$FFFF
    PHB
    LDA.w #!Map_Unk7F3700RecBytes-1
    MVN !Bank7F,!BankC0                 ; lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    PLB
    LDX.w #LocLoad_Unk7F3700Init_Rec4
    LDY.w #(!Map_Unk7F3700+(4*!Map_Unk7F3700RecBytes))&$FFFF
    PHB
    LDA.w #!Map_Unk7F3700TailBytes-1
    MVN !Bank7F,!BankC0                 ; lint-ok: MVN operands are bank bytes; asar rejects a width suffix on MVN
    PLB
    SEP #$20
    RTS

; $C0:5D37 — LocLoad_Unk7F3700Init (55 bytes, $5D37–$5D6D)
; LocLoad_InitUnk7F3700's source: 25 bytes for $7F:3700, 24 for the
; three blocks at $7F:3720-$7F:3760 (Rec1; the copies take 32 and so
; also read Rec4 and the first two bytes of Evt_OpcodeTable) and 6 for
; $7F:3780 (Rec4). The bytes look like script data (each block starts
; $E3 and the first two end $11 $09); not decoded.
LocLoad_Unk7F3700Init:
    db $E3,$00,$89,$40,$0D,$00,$0E,$02,$AE,$95,$00,$0E,$00,$71,$FF,$12
    db $FF,$03,$04,$04,$E3,$01,$00,$11,$09
.Rec1:
    db $E3,$00,$89,$40,$0D,$00,$AE,$96,$00,$00,$A6,$00,$71,$FE,$12,$FE
    db $04,$04,$04,$E3,$00,$00,$11,$09
.Rec4:
    db $96,$00,$00,$FF,$9D,$00

; $C0:5D6E — Evt_OpcodeTable (512 bytes, $5D6E–$5F6D)
; The event-script opcode handlers, one word per opcode $00-$FF (bank
; $C0 addresses), indexed by opcode x 2: the script runners read the
; opcode byte at Evt_Data + the script position, set Y = that offset,
; double the opcode and JSR (Evt_OpcodeTable,X). The 32 unused opcodes ($01, $3A, $3D, $3E, $45,
; $46, $6E, $70, $74, $78, $79, $85, $86, $93, $9B, $A2-$A5, $BE, $BF,
; $C5, $C6, $DB, $E9, $EF, $F5-$F7, $FB-$FD) point at Evt_UnusedOpcode
; (a halt through Sys_HaltWithColor). Its first two bytes are also read by
; LocLoad_InitUnk7F3700's 32-byte copies (see LocLoad_Unk7F3700Init).
; Read by JSR (Evt_OpcodeTable,X) at $C0:5910 (Evt_InitObjects),
; $C0:5977 (Evt_RunObj0Func1), $C0:59A0 (Evt_RunObjInit) and $C0:5AB1
; (Evt_RunObjScriptSteps).
Evt_OpcodeTable:
    dw Evt_Op00_Return              ; $00
    dw Evt_UnusedOpcode             ; $01
    dw Evt_Op02_CallObjFunc         ; $02
    dw Evt_Op03_CallObjFuncRetry    ; $03
    dw Evt_Op04_CallObjFuncWait     ; $04
    dw Evt_Op05_CallPcFunc          ; $05
    dw Evt_Op06_CallPcFuncRetry     ; $06
    dw Evt_Op07_CallPcFuncWait      ; $07
    dw Evt_Op08_BlockCalls          ; $08
    dw Evt_Op09_AllowCalls          ; $09
    dw Evt_Op0A_RemoveObj           ; $0A
    dw Evt_Op0B_StopObjScript       ; $0B
    dw Evt_Op0C_StartObjScript      ; $0C
    dw Evt_Op0D_SetUnk1C80          ; $0D
    dw Evt_Op0E_SetUnk1C81          ; $0E
    dw Evt_Op0F_FaceUp              ; $0F
    dw Evt_Op10_JumpFwd             ; $10
    dw Evt_Op11_JumpBack            ; $11
    dw Evt_Op12_IfVarByte           ; $12
    dw Evt_Op13_IfVarWord           ; $13
    dw Evt_Op14_IfVarVarByte        ; $14
    dw Evt_Op15_IfVarVarWord        ; $15
    dw Evt_Op16_IfMemByte           ; $16
    dw Evt_Op17_FaceDown            ; $17
    dw Evt_Op18_IfUnk7F0000Below    ; $18
    dw Evt_Op19_SetUnk7F0A80Var     ; $19
    dw Evt_Op1A_IfUnk7F0A80         ; $1A
    dw Evt_Op1B_FaceLeft            ; $1B
    dw Evt_Op1C_SetUnk7F0A80Mem     ; $1C
    dw Evt_Op1D_FaceRight           ; $1D
    dw Evt_Op1E_ObjFaceUp           ; $1E
    dw Evt_Op1F_ObjFaceDown         ; $1F
    dw Evt_Op20_GetPartyMember0     ; $20
    dw Evt_Op21_GetObjTile          ; $21
    dw Evt_Op22_GetPcTile           ; $22
    dw Evt_Op23_GetObjFacing        ; $23
    dw Evt_Op24_GetPcFacing         ; $24
    dw Evt_Op25_ObjFaceLeft         ; $25
    dw Evt_Op26_ObjFaceRight        ; $26
    dw Evt_Op27_IfObjUnk0F00        ; $27
    dw Evt_Op28_IfObjInsideScreen   ; $28
    dw Evt_Op29_StartCredits        ; $29
    dw Evt_Op2A_Field54Bit2         ; $2A
    dw Evt_Op2B_Field54Bit3         ; $2B
    dw Evt_Op2C_SetLayer3Pos        ; $2C
    dw Evt_Op2D_IfAnyHeld           ; $2D
    dw Evt_Op2E_PalAnim             ; $2E
    dw Evt_Op2F_SetCreditsPos       ; $2F
    dw Evt_Op30_IfMapHeldBit1       ; $30
    dw Evt_Op31_IfMapHeldBit7       ; $31
    dw Evt_Op32_CreditsLine         ; $32
    dw Evt_Op33_SetPalette          ; $33
    dw Evt_Op34_IfHeldA             ; $34
    dw Evt_Op35_IfHeldB             ; $35
    dw Evt_Op36_IfHeldX             ; $36
    dw Evt_Op37_IfHeldY             ; $37
    dw Evt_Op38_IfHeldL             ; $38
    dw Evt_Op39_IfHeldR             ; $39
    dw Evt_UnusedOpcode             ; $3A
    dw Evt_Op3B_IfMapPressedBit1    ; $3B
    dw Evt_Op3C_IfMapPressedBit7    ; $3C
    dw Evt_UnusedOpcode             ; $3D
    dw Evt_UnusedOpcode             ; $3E
    dw Evt_Op3F_IfPressedA          ; $3F
    dw Evt_Op40_IfPressedB          ; $40
    dw Evt_Op41_IfPressedX          ; $41
    dw Evt_Op42_IfPressedY          ; $42
    dw Evt_Op43_IfPressedL          ; $43
    dw Evt_Op44_IfPressedR          ; $44
    dw Evt_UnusedOpcode             ; $45
    dw Evt_UnusedOpcode             ; $46
    dw Evt_Op47_SetScanlineLimit    ; $47
    dw Evt_Op48_GetLongByte         ; $48
    dw Evt_Op49_GetLongWord         ; $49
    dw Evt_Op4A_SetLongByte         ; $4A
    dw Evt_Op4B_SetLongWord         ; $4B
    dw Evt_Op4C_SetLongVarByte      ; $4C
    dw Evt_Op4D_SetLongVarWord      ; $4D
    dw Evt_Op4E_CopyData            ; $4E
    dw Evt_Op4F_SetVarByte          ; $4F
