; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (EvtMem_Value is
;   dp), DB any (all accesses long); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = Y = the opcode + 3, C=1; A =
;   the new byte; EvtMem_Value = 0 (the count, run down).
; ------------------------------------------------------------
Evt_Op6F_ShrVarByte:
    INY
    TYX
    LDA.l !Evt_Data,X                   ; count
    STA.b !EvtMem_Value
    INX
    LDA.l !Evt_Data,X                   ; a
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAX
    SEP #$20
    LDA.l !Evt_Unk7F0200,X
.shift:
    LSR A
    DEC.b !EvtMem_Value
    BNE .shift
    STA.l !Evt_Unk7F0200,X
    INY
    INY
    TYX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:6C69 — Evt_Op71_IncVarByte (28 bytes, $6C69–$6C84)
; Event opcode $71 (2 bytes: $71, a): adds 1 to event word a's low byte
;   (wrapping in the byte); X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $71).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP any (not used), DB any
;   (all accesses long); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = Y = the opcode + 2, C=1; A =
;   the new byte.
; ------------------------------------------------------------
Evt_Op71_IncVarByte:
    INY
    TYX
    LDA.l !Evt_Data,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAX
    SEP #$20
    LDA.l !Evt_Unk7F0200,X
    INC A
    STA.l !Evt_Unk7F0200,X
    INY
    TYX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:6C85 — Evt_Op72_IncVarWord (28 bytes, $6C85–$6CA0)
; Event opcode $72 (2 bytes: $72, a): adds 1 to event word a;
;   X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $72).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP any (not used), DB any
;   (all accesses long); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = Y = the opcode + 2, C=1; A =
;   the new word's low byte (B its high byte).
; ------------------------------------------------------------
Evt_Op72_IncVarWord:
    INY
    TYX
    LDA.l !Evt_Data,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAX
    LDA.l !Evt_Unk7F0200,X
    INC A
    STA.l !Evt_Unk7F0200,X
    SEP #$20
    INY
    TYX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:6CA1 — Evt_Op73_DecVarByte (28 bytes, $6CA1–$6CBC)
; Event opcode $73 (2 bytes: $73, a): subtracts 1 from event word a's low
;   byte (wrapping in the byte); X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $73).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP any (not used), DB any
;   (all accesses long); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = Y = the opcode + 2, C=1; A =
;   the new byte.
; ------------------------------------------------------------
Evt_Op73_DecVarByte:
    INY
    TYX
    LDA.l !Evt_Data,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAX
    SEP #$20
    LDA.l !Evt_Unk7F0200,X
    DEC A
    STA.l !Evt_Unk7F0200,X
    INY
    TYX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:6CBD — Evt_Op75_SetVarByte1 (25 bytes, $6CBD–$6CD5)
; Event opcode $75 (2 bytes: $75, a): event word a's low byte = 1;
;   X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $75).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP any (not used), DB any
;   (all accesses long); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = Y = the opcode + 2, C=1; A =
;   1.
; ------------------------------------------------------------
Evt_Op75_SetVarByte1:
    INY
    TYX
    LDA.l !Evt_Data,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAX
    SEP #$20
    LDA.b #$01
    STA.l !Evt_Unk7F0200,X
    INY
    TYX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:6CD6 — Evt_Op76_SetVarWord1 (26 bytes, $6CD6–$6CEF)
; Event opcode $76 (2 bytes: $76, a): event word a = 1; X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $76).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP any (not used), DB any
;   (all accesses long); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = Y = the opcode + 2, C=1; A =
;   1 (B 0).
; ------------------------------------------------------------
Evt_Op76_SetVarWord1:
    INY
    TYX
    LDA.l !Evt_Data,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAX
    LDA.w #$0001
    STA.l !Evt_Unk7F0200,X
    SEP #$20
    INY
    TYX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:6CF0 — Evt_Op77_ClearVarByte (25 bytes, $6CF0–$6D08)
; Event opcode $77 (2 bytes: $77, a): event word a's low byte = 0;
;   X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $77).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP any (not used), DB any
;   (all accesses long); Y = the opcode's offset in Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = Y = the opcode + 2, C=1; A =
;   0.
; ------------------------------------------------------------
Evt_Op77_ClearVarByte:
    INY
    TYX
    LDA.l !Evt_Data,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAX
    SEP #$20
    LDA.b #$00
    STA.l !Evt_Unk7F0200,X
    INY
    TYX
    SEC
    RTS

; ------------------------------------------------------------
; $C0:6D09 — Evt_Op7F_RandomVarByte (38 bytes, $6D09–$6D2E)
; Event opcode $7F (2 bytes: $7F, a): event word a's low byte = the next
;   RandomTable byte: Field_Unk0400Copy is incremented and indexes it
;   (as Obj_SetVelocityChecked does); X = Y + 2, C=1.
; Reached through Evt_OpcodeTable (opcode $7F).
; Callers note: the JMP at $C0:5E6B is not code: it is Evt_OpcodeTable's
;   bytes (the $4C high byte of entry $7E, then entry $7F, $6D09).
; On entry: M=1 (8-bit A), X=0 (16-bit X/Y), DP=$0100 (Field_Unk0400Copy /
;   EvtMem_Value are dp), DB=$00 (RandomTable read absolute, in bank $C0
;   through the $00 mirror; the rest long); Y = the opcode's offset in
;   Evt_Data.
; Exit: M=1, X=0, DP and DB unchanged; X = Y = the opcode + 2, C=1; A =
;   EvtMem_Value = the random byte; Field_Unk0400Copy + 1.
; ------------------------------------------------------------
Evt_Op7F_RandomVarByte:
    TDC
    XBA                                 ; B = 0 for the 16-bit TAX
    LDA.b !Field_Unk0400Copy
    INC A
    STA.b !Field_Unk0400Copy
    TAX
    LDA.w RandomTable,X
    STA.b !EvtMem_Value
    INY
    TYX
    LDA.l !Evt_Data,X
    REP #$20
    AND.w #!Eng_LowByteMask
    ASL A
    TAX
    SEP #$20
    LDA.b !EvtMem_Value
    STA.l !Evt_Unk7F0200,X
    INY
    TYX
    SEC
    RTS

; ============================================================
; $C0:1ADF — Sub_1ADF (87 bytes, $1ADF–$1B35)
; Purpose unknown: every variable it touches (Field_Unk34, Field_Unk62-66,
; Pad_Unk00F6-F8) is still unidentified, so it keeps its address name.
; Leaf routine run by Field_PauseAndMenuInput ($C0:192B, its only
; caller) when Field_Unk62 is set (and Pad_Unk00F6 bit 6 is clear);
; A = Field_Unk62.
; Callers (1 JSR site): Field_PauseAndMenuInput ($C0:192B).
; On entry: M=1, X/Y 16-bit, DP=$0100, DB=$00.
; Exit: M=1, X/Y 16-bit, DP and DB unchanged; A clobbered, X = 0 when
; Field_Unk34 is cleared.
;
; A=1    → if Pad_Unk00F6 bit 7 is set, clear Field_Unk34.
; A=2    → Pad_Unk00F7 bit 2 steps Field_Unk63 up (wrapping from
;          Field_Unk65 to Field_Unk64), bit 3 steps it down (wrapping
;          the other way); else Pad_Unk00F8 bit 7 sets Field_Unk62 = 3.
;          (Bits 2/3 are Down/Up in the Pad_Pressed layout: a list
;          cursor is likely.)
; other  → save Field_Unk63 in Field_Unk66 and force it to 4 (unless it
;          is negative or already 4), then as A=1.
; ============================================================
org $C01ADF
Sub_1ADF:
    CMP #$01
    BEQ .chk_flags       ; A=1
    CMP #$02
    BNE .force_unk63     ; A≠1,2
    ; A=2
    LDA.w !Pad_Unk00F7
    BIT.b #!Pad_HiDown
    BNE .step_up
    BIT.b #!Pad_HiUp
    BNE .step_down
    LDA.w !Pad_Unk00F8
    BIT.b #!Pad_Unk00F8Bit7
    BEQ .done
    LDA #$03
    STA.b !Field_Unk62
    RTS
.force_unk63:           ; A≠1,2
    LDA.b !Field_Unk63
    BMI .chk_flags       ; negative → leave it
    CMP #$04
    BEQ .chk_flags       ; already 4
    STA.b !Field_Unk66
    LDA #$04
    STA.b !Field_Unk63
.chk_flags:
    LDA.w !Pad_Unk00F6
    BIT.b #!Pad_Unk00F6Bit7
    BEQ .done            ; bit 7 clear → leave Field_Unk34
    LDX #$0000
    STX.b !Field_Unk34
.done:
    RTS
.step_up:                ; past Field_Unk65 → wrap to Field_Unk64
    LDA.b !Field_Unk63
    INC A
    CMP.b !Field_Unk65
    BEQ .store
    BCS .wrap_to_low
.store:
    STA.b !Field_Unk63
    RTS
.wrap_to_low:
    LDA.b !Field_Unk64
    BRA .store
.step_down:              ; below Field_Unk64 (or from 0) → wrap to Field_Unk65
    LDA.b !Field_Unk63
    BEQ .wrap_to_high
    DEC A
    CMP.b !Field_Unk64
    BCS .store
.wrap_to_high:
    LDA.b !Field_Unk65
    BRA .store

; ============================================================
; $C0:0D78 — ModeE6_Handler (231 bytes, $0D78–$0E5E)
; Tile animation for map-tile state $E6: a 1x2 column, the tile at
; (Field_TileAnimX, Field_TileAnimY) and the one above it.
; BRL target from Field_SceneChangeTick (Field_SceneFlags bit 4).
; Callers (1 BRL site): Field_SceneChangeTick ($C0:0D56).
; On entry: A = $E6, X = Map_TileProps index of (col, row), M=1, X/Y
; 16-bit, DP=$0100 (TileAnim_* are dp), DB=$00 (absolute Map_* and
; TileAnim_VramAddrs stores).
; Exit: BRL DefaultHandler with M=1, X/Y 16-bit; X and Y clobbered.
;
; The general shape, shared by all five Mode*_Handlers:
;  1. Advance the state byte of each affected map tile in
;     Map_TileProps by one ($E6 → $E7 here), set TileAnim_PairCount
;     and play Audio_SfxTileAnimA.
;  2. For each affected map tile ("pass"), compute the VRAM word
;     address of its four 8x8 tiles in the 64x32 BG tilemap
;     (Bg_TilemapIndex64x32 + Map_TilemapVram) into TileAnim_VramAddrs,
;     4 words per map tile in TL, TR, BL, BR order.
;  3. Set VramQueue_TileAnim in Field_VramQueueFlags and continue in
;     DefaultHandler.
; Earlier comments here swapped rows and columns: Field_TileAnimX
; ($5B) is the map column, Field_TileAnimY ($5C) the row.
; ============================================================
org $C00D78
ModeE6_Handler:
    INC                  ; tile state $E6 → $E7
    STA.l !Map_TileProps,X ; tile (col, row)
    REP #$20             ; A → 16-bit
    TXA
    SEC
    SBC.w #!Map_RowStride ; index of (col, row-1)
    TAX
    LDA.l !Map_TileProps,X ; 16-bit: (col, row-1) and its right neighbour
    INC                  ; +1 lands in (col, row-1)
    STA.l !Map_TileProps,X
    SEP #$20             ; A → 8-bit
    STZ.b !TileAnim_PairCount ; one pair of tiles
    JSR Audio_PlayTileSfxA
    REP #$20             ; A → 16-bit
    LDA.w !Map_TileOriginX
    STA.b !TileAnim_OriginX
    LDA.w !Map_TileOriginY
    STA.b !TileAnim_OriginY

    ; --- Pass 1: map tile (col, row) → TileAnim_VramAddrs+0..+6 ---
    LDA.b !Field_TileAnimX
    ASL                         ; map tiles are 2x2 8x8 tiles
    SEC
    SBC.b !TileAnim_OriginX
    CLC
    ADC.w !Map_BgColBias
    AND.w #!Bg_ColMask64
    TAY                         ; Y = tilemap column (0-63)
    LDA.b !Field_TileAnimY
    ASL                         ; map tiles are 2x2 8x8 tiles
    SEC
    SBC.b !TileAnim_OriginY
    CLC
    ADC.w !Map_BgRowBias
    AND.w #!Bg_RowMask32
    TAX                         ; X = tilemap row (0-31)
    JSR Bg_TilemapIndex64x32
    CLC
    ADC.w !Map_TilemapVram
    STA.w !TileAnim_VramAddrs   ; top-left 8x8 tile
    TYA
    PHA
    INC
    AND.w #!Bg_ColMask64
    TAY                         ; Y = tilemap column (0-63)
    TXA
    JSR Bg_TilemapIndex64x32
    CLC
    ADC.w !Map_TilemapVram
    STA.w !TileAnim_VramAddrs+2 ; top-right 8x8 tile
    PLY
    TXA
    INC
    AND.w #!Bg_RowMask32
    TAX                         ; X = tilemap row (0-31)
    JSR Bg_TilemapIndex64x32
    CLC
    ADC.w !Map_TilemapVram
    STA.w !TileAnim_VramAddrs+4 ; bottom-left 8x8 tile
    TYA
    INC
    AND.w #!Bg_ColMask64
    TAY                         ; Y = tilemap column (0-63)
    TXA
    JSR Bg_TilemapIndex64x32
    CLC
    ADC.w !Map_TilemapVram
    STA.w !TileAnim_VramAddrs+6 ; bottom-right 8x8 tile
    ; --- Pass 2: map tile (col, row-1) → TileAnim_VramAddrs+8..+14 ---
    LDA.b !Field_TileAnimX
    ASL                         ; map tiles are 2x2 8x8 tiles
    SEC
    SBC.b !TileAnim_OriginX
    CLC
    ADC.w !Map_BgColBias
    AND.w #!Bg_ColMask64
    TAY                         ; Y = tilemap column (0-63)
    LDA.b !Field_TileAnimY
    DEC
    ASL                         ; map tiles are 2x2 8x8 tiles
    SEC
    SBC.b !TileAnim_OriginY
    CLC
    ADC.w !Map_BgRowBias
    AND.w #!Bg_RowMask32
    TAX                         ; X = tilemap row (0-31)
    JSR Bg_TilemapIndex64x32
    CLC
    ADC.w !Map_TilemapVram
    STA.w !TileAnim_VramAddrs+8 ; top-left 8x8 tile
    TYA
    PHA
    INC
    AND.w #!Bg_ColMask64
    TAY                         ; Y = tilemap column (0-63)
    TXA
    JSR Bg_TilemapIndex64x32
    CLC
    ADC.w !Map_TilemapVram
    STA.w !TileAnim_VramAddrs+10 ; top-right 8x8 tile
    PLY
    TXA
    INC
    AND.w #!Bg_RowMask32
    TAX                         ; X = tilemap row (0-31)
    JSR Bg_TilemapIndex64x32
    CLC
    ADC.w !Map_TilemapVram
    STA.w !TileAnim_VramAddrs+12 ; bottom-left 8x8 tile
    TYA
    INC
    AND.w #!Bg_ColMask64
    TAY                         ; Y = tilemap column (0-63)
    TXA
    JSR Bg_TilemapIndex64x32
    CLC
    ADC.w !Map_TilemapVram
    STA.w !TileAnim_VramAddrs+14 ; bottom-right 8x8 tile
    SEP #$20             ; A → 8-bit
    LDA.b #!VramQueue_TileAnim
    TSB.b !Field_VramQueueFlags ; TileAnim_VramAddrs ready
    BRL DefaultHandler

; ============================================================
; $C0:1B36 — Bg_TilemapIndex64x32 (29 bytes, $1B36–$1B52)
; (was Sub_1B36.) Word offset of an 8x8 tile in a 64x32 BG tilemap
; made of two 32x32 screens side by side.
; Callers (92 JSR sites): ModeE6_Handler ($C0:0DBD, $C0:0DCF, $C0:0DE0, $C0:0DF1, $C0:0E18,
;   $C0:0E2A, $C0:0E3B, $C0:0E4C), ModeEC_Handler ($C0:0EBB, $C0:0ECD, $C0:0EDE, $C0:0EEF, $C0:0F16,
;   $C0:0F28, $C0:0F39, $C0:0F4A, $C0:0F71, $C0:0F83, $C0:0F94, $C0:0FA5, $C0:0FCD, $C0:0FDF,
;   $C0:0FF0, $C0:1001), ModeEE_Handler ($C0:1071, $C0:1083, $C0:1094, $C0:10A5, $C0:10CD, $C0:10DF,
;   $C0:10F0, $C0:1101, $C0:1127, $C0:1139, $C0:114A, $C0:115B, $C0:1182, $C0:1194, $C0:11A5,
;   $C0:11B6), ModeFA_Handler ($C0:1242, $C0:1254, $C0:1265, $C0:1276, $C0:129D, $C0:12AF, $C0:12C0,
;   $C0:12D1, $C0:12F9, $C0:130B, $C0:131C, $C0:132D, $C0:1354, $C0:1366, $C0:1377, $C0:1388,
;   $C0:13B0, $C0:13C2, $C0:13D3, $C0:13E4, $C0:140D, $C0:141F, $C0:1430, $C0:1441), ModeFC_Handler
;   ($C0:14CE, $C0:14E0, $C0:14F1, $C0:1502, $C0:152A, $C0:153C, $C0:154D, $C0:155E, $C0:1587,
;   $C0:1599, $C0:15AA, $C0:15BB, $C0:15E1, $C0:15F3, $C0:1604, $C0:1615, $C0:163C, $C0:164E,
;   $C0:165F, $C0:1670, $C0:1698, $C0:16AA, $C0:16BB, $C0:16CC) and DefaultHandler ($C0:172C,
;   $C0:173E, $C0:174F, $C0:1760).
; On entry (M=0): A = tile row (0-31), Y = tile column (0-63).
; Returns A = row*32 + column for columns 0-31, or
;             row*32 + (column-32) + $0400 for columns 32-63.
; (Earlier comments had the row and column inputs swapped.)
; Keeps row*32 in Bg_RowWordOfs.
; On entry: M=0, X/Y 16-bit, DP=$0100 (Bg_RowWordOfs is dp).
; Exit: M=0; X and Y unchanged (the callers rely on it).
; ============================================================
org $C01B36
Bg_TilemapIndex64x32:
    ASL
    ASL
    ASL
    ASL
    ASL                  ; row × 32
    STA.b !Bg_RowWordOfs
    TYA                  ; A = column
    CMP.w #!Bg_ScreenWidth
    BCS .right_screen    ; columns 32-63
    CLC
    ADC.b !Bg_RowWordOfs ; row*32 + column
    RTS
.right_screen:
    SEC
    SBC.w #!Bg_ScreenWidth ; column - 32
    CLC
    ADC.b !Bg_RowWordOfs
    CLC
    ADC.w #!Bg_ScreenWords ; + the left screen's $400 words
    RTS

; ============================================================
; $C0:0E5F — ModeEC_Handler (437 bytes, $0E5F–$1013)
; Tile animation for map-tile state $EC: a 2x2 block, columns
; col..col+1, rows row-1..row. Same shape as ModeE6_Handler; 4 passes.
; Callers (1 BRL site): Field_SceneChangeTick ($C0:0D5D).
; On entry: A = $EC, X = Map_TileProps index of (col, row), M=1, X/Y
; 16-bit, DP=$0100 (TileAnim_* are dp), DB=$00 (absolute Map_* and
; TileAnim_VramAddrs stores).
; Exit: BRL DefaultHandler with M=1, X/Y 16-bit; X and Y clobbered.
; ============================================================
org $C00E5F
ModeEC_Handler:
    INC A                   ; $EC → $ED
    STA.l !Map_TileProps,X  ; tile (col, row)
    INX                     ; X = tile (col+1, row)
    LDA.l !Map_TileProps,X
    INC A
    STA.l !Map_TileProps,X  ; tile (col+1, row)
    REP #$20                ; M → 0 (16-bit A)
    TXA
    SEC
    SBC.w #!Map_RowStride   ; A = index of (col+1, row-1)
    TAX
    SEP #$20                ; M → 1 (8-bit A)
    LDA.l !Map_TileProps,X
    INC A
    STA.l !Map_TileProps,X
    DEX                     ; (col, row-1)
    LDA.l !Map_TileProps,X  ; load entry at (col, row-1)
    INC A
    STA.l !Map_TileProps,X
    LDA #$01
    STA.b !TileAnim_PairCount ; 2 pairs of tiles (stored minus 1)
    JSR Audio_PlayTileSfxA
    ; --- VRAM addresses of the 8x8 tiles ---
    REP #$20                ; M → 0 (16-bit A)
    LDA.w !Map_TileOriginX
    STA.b !TileAnim_OriginX
    LDA.w !Map_TileOriginY
    STA.b !TileAnim_OriginY
    ; --- Pass 1: map tile (col, row) → TileAnim_VramAddrs+0..+6 ---
    LDX.b !Field_TileAnimX      ; LDX+TXA here, LDA in the other passes
    TXA
    ASL                         ; map tiles are 2x2 8x8 tiles
    SEC
    SBC.b !TileAnim_OriginX
    CLC
    ADC.w !Map_BgColBias
    AND.w #!Bg_ColMask64
    TAY                         ; Y = tilemap column (0-63)
    LDA.b !Field_TileAnimY
    ASL                         ; map tiles are 2x2 8x8 tiles
    SEC
    SBC.b !TileAnim_OriginY
    CLC
    ADC.w !Map_BgRowBias
    AND.w #!Bg_RowMask32
    TAX                         ; X = tilemap row (0-31)
    JSR Bg_TilemapIndex64x32
    CLC
    ADC.w !Map_TilemapVram
    STA.w !TileAnim_VramAddrs   ; top-left 8x8 tile
    TYA
    PHA
    INC
    AND.w #!Bg_ColMask64
    TAY                         ; Y = tilemap column (0-63)
    TXA
    JSR Bg_TilemapIndex64x32
    CLC
    ADC.w !Map_TilemapVram
    STA.w !TileAnim_VramAddrs+2 ; top-right 8x8 tile
    PLY
    TXA
    INC
    AND.w #!Bg_RowMask32
    TAX                         ; X = tilemap row (0-31)
    JSR Bg_TilemapIndex64x32
