    STA.b !Spr_FramePtr
    SEP #$30
    LDA #$01
    STA.w WMADDH            ; WRAM bank $7F
    REP #$30
    LDA.b !Spr_WramPtr
    STA.w WMADDL
    ; tile words 0-15 → the buffer start
    LDA.w #!SprBuf_ChunkTiles
    STA.b !Spr_TileCount
    LDY #$0000
    BRA .loop_entry
.loop_top:
    LDA.b !Spr_WramPtr
    CLC
    ADC.w #!Gfx_Tile4bppBytes
    STA.b !Spr_WramPtr
.loop_entry:
    LDA.b [!Spr_FramePtr],Y
