    REP #$20
    LDA.w !Obj_TileBuf,X
    CLC
    ADC.w #!Gfx_8TilesBytes*4
    STA.b !Spr_WramPtr
    SEP #$20
    LDA.w !Obj_LastFrame,X
    STA.w WRMPYA
    LDA.b #!Frame12_Bytes
    STA.w WRMPYB
    LDA.w !Obj_FrameBank,X
    STA.b !Spr_FramePtr+2
    REP #$20
    LDA.w RDMPYL            ; frame × record size
    CLC
    ADC.w !Obj_FrameOfs,X
    STA.b !Spr_FramePtr
    SEP #$20
    LDA #$01
    STA.w WMADDH            ; WRAM bank $7F
    REP #$30
    LDA.b !Spr_WramPtr
    STA.w WMADDL
    LDA.w #!SprBuf_ChunkTiles ; 16 tiles
    STA.b !Spr_TileCount
    LDY.w #!Frame_TileWordBytes*32
    BRA .check
.next:
    LDA.b !Spr_WramPtr
    CLC
    ADC.w #!Gfx_Tile4bppBytes
    STA.b !Spr_WramPtr
.check:
    LDA.b [!Spr_FramePtr],Y
    BIT.w #!SprFrame_HFlip
    BNE .flip
    JSR Spr_CopyTile
    INY
    INY
    DEC.b !Spr_TileCount
    BNE .next
